def _load_embedded_xlsxwriter():
    global xlsxwriter
    if xlsxwriter is not None:
        return xlsxwriter
    import base64 as _base64
    import tempfile as _tempfile
    import importlib as _importlib
    import sys as _sys
    from pathlib import Path as _Path
    bundle_path = _Path(_tempfile.gettempdir()) / "swu_collection_manager_xlsxwriter_bundle.zip"
    try:
        if not bundle_path.exists() or bundle_path.stat().st_size < 100000:
            bundle_path.write_bytes(_base64.b64decode(_XLSXWRITER_BUNDLE_B64))
        bundle_str = str(bundle_path)
        if bundle_str not in _sys.path:
            _sys.path.insert(0, bundle_str)
        xlsxwriter = _importlib.import_module("xlsxwriter")
        return xlsxwriter
    except Exception:
        xlsxwriter = None
        raise


