    def _populate_keyword_filter(self, expansion_code=None, trait_code=None):
        """Charge les mots-clés compatibles avec les extensions et le trait sélectionnés."""
        if not hasattr(self, "keyword_combo") or self.db is None:
            return
        try:
            if expansion_code is None:
                expansion_codes = sorted(getattr(self, "_selected_expansion_codes", set()))
            elif isinstance(expansion_code, (list, tuple, set)):
                expansion_codes = [clean_text(x).upper() for x in expansion_code if clean_text(x)]
            else:
                code = clean_text(expansion_code).upper()
                expansion_codes = [code] if code else []

            trait_code = clean_text(trait_code).strip()
            conditions = ["TRIM(COALESCE(k.code, '')) <> ''"]
            params = []
            if expansion_codes:
                placeholders = ",".join("?" for _ in expansion_codes)
                conditions.append(f"e.code IN ({placeholders})")
                params.extend(expansion_codes)
            if trait_code:
                conditions.append("EXISTS (SELECT 1 FROM card_concept_trait cct_filter JOIN trait t_filter ON t_filter.id = cct_filter.trait_id WHERE cct_filter.card_concept_id = cck.card_concept_id AND t_filter.code = ?)")
                params.append(trait_code)

            sql = f"""
                SELECT DISTINCT k.code
                FROM keyword k
                JOIN card_concept_keyword cck ON cck.keyword_id = k.id
                JOIN card_printing cp ON cp.card_concept_id = cck.card_concept_id
                JOIN expansion e ON e.id = cp.expansion_id
                WHERE {' AND '.join(conditions)}
                ORDER BY LOWER(k.code)
            """
            rows = self.db.execute(sql, tuple(params)).fetchall()
            values = ["Tous les mots-clés"]
            for row in rows:
                code = clean_text(row[0])
                if code:
                    values.append(self._keyword_display_label(code))
            self._keyword_filter_codes = {
                self._keyword_display_label(clean_text(row[0])): clean_text(row[0])
                for row in rows if clean_text(row[0])
            }
            self.keyword_combo["values"] = tuple(values)
            current = self.keyword_filter_var.get()
            if current not in values:
                current = "Tous les mots-clés"
                self.keyword_filter_var.set(current)
            self.keyword_combo.set(current)
        except Exception:
            self._keyword_filter_codes = {}
            self.keyword_combo["values"] = ("Tous les mots-clés",)
            self.keyword_filter_var.set("Tous les mots-clés")
            self.keyword_combo.set("Tous les mots-clés")

