    def _populate_trait_filter(self, expansion_code=None, keyword_code=None):
        """Charge les traits compatibles avec les extensions et le mot-clé sélectionnés."""
        if not hasattr(self, "trait_combo") or self.db is None:
            return
        try:
            if expansion_code is None:
                expansion_codes = sorted(getattr(self, "_selected_expansion_codes", set()))
            elif isinstance(expansion_code, (list, tuple, set)):
                expansion_codes = [clean_text(x).upper() for x in expansion_code if clean_text(x)]
            else:
                code = clean_text(expansion_code).upper()
                expansion_codes = [code] if code else []
            keyword_code = clean_text(keyword_code).strip()
            fr_id = LANGUAGES.get("fr", 2)
            conditions = ["TRIM(COALESCE(t.code, '')) <> ''"]
            params = [fr_id]
            if expansion_codes:
                placeholders = ",".join("?" for _ in expansion_codes)
                conditions.append(f"e.code IN ({placeholders})")
                params.extend(expansion_codes)
            if keyword_code:
                conditions.append("EXISTS (SELECT 1 FROM card_concept_keyword cck_filter JOIN keyword k_filter ON k_filter.id = cck_filter.keyword_id WHERE cck_filter.card_concept_id = cct.card_concept_id AND k_filter.code = ?)")
                params.append(keyword_code)

            sql = f"""
                SELECT DISTINCT t.id, t.code,
                       COALESCE(NULLIF(TRIM(tl.name), ''), t.code) AS fr_name
                FROM trait t
                JOIN card_concept_trait cct ON cct.trait_id = t.id
                JOIN card_printing cp ON cp.card_concept_id = cct.card_concept_id
                JOIN expansion e ON e.id = cp.expansion_id
                LEFT JOIN trait_localization tl
                       ON tl.trait_id = t.id AND tl.language_id = ?
                WHERE {' AND '.join(conditions)}
                ORDER BY LOWER(fr_name)
            """
            rows = self.db.execute(sql, tuple(params)).fetchall()
            values = ["Tous les traits"]
            code_map = {}
            used_labels = set()
            for row in rows:
                code = clean_text(row[1])
                fr_name = clean_text(row[2])
                if not code:
                    continue
                mapped_name = self._trait_display_label(code)
                if mapped_name and mapped_name.lower() != code.lower().replace("_", " ").replace("-", " "):
                    label = mapped_name
                else:
                    label = fr_name or mapped_name
                if not label or label in used_labels:
                    continue
                used_labels.add(label)
                values.append(label)
                code_map[label] = code
            self._trait_filter_codes = code_map
            self.trait_combo["values"] = tuple(values)
            current = self.trait_filter_var.get()
            if current not in values:
                current = "Tous les traits"
                self.trait_filter_var.set(current)
            self.trait_combo.set(current)
        except Exception:
            self._trait_filter_codes = {}
            self.trait_combo["values"] = ("Tous les traits",)
            self.trait_filter_var.set("Tous les traits")
            self.trait_combo.set("Tous les traits")

    def _selected_trait_code(self):
        label = self.trait_filter_var.get().strip()
        if not label or label == "Tous les traits":
            return ""
        return getattr(self, "_trait_filter_codes", {}).get(label, "")

    def _selected_keyword_code(self):
        label = self.keyword_filter_var.get().strip()
        if not label or label == "Tous les mots-clés":
            return ""
        return getattr(self, "_keyword_filter_codes", {}).get(label, "")

    def _create_hex_all_control(self, parent, variable, command):
        """Crée le contrôle « Tous » sous forme d'hexagone."""
        holder = tk.Frame(parent, bg=self.root.cget("bg"), bd=0, highlightthickness=0)
        holder.pack(anchor="w", pady=(0, 3))

        width, height = 58, 30
        canvas = tk.Canvas(
            holder, width=width, height=height,
            bg=self.root.cget("bg"), bd=0, highlightthickness=0,
            cursor="hand2"
        )
        canvas.pack()

        def redraw(*_):
            selected = bool(variable.get())
            canvas.delete("all")
            inset = 2
            points = [
                inset + 9, inset,
                width - inset - 9, inset,
                width - inset, height / 2,
                width - inset - 9, height - inset,
                inset + 9, height - inset,
                inset, height / 2,
            ]
            fill = "#7b4bb7" if selected else "#3a3a3a"
            outline = "#f2c94c" if selected else "#777777"
            canvas.create_polygon(
                points, fill=fill, outline=outline, width=2
            )
            canvas.create_text(
                width / 2, height / 2, text="Tous",
                fill="white", font=("Arial", 9, "bold")
            )

        def click(_event=None):
            variable.set(not variable.get())
            command()
            redraw()

        canvas.bind("<Button-1>", click)
        variable.trace_add("write", redraw)
        redraw()
        return canvas

    def _build_aspect_filter_line(self, parent, label, variable, row_index, group="main", include_clear=False, pack_side="left"):
        """Construit un groupe d'affinités avec une logique propre au groupe."""
        line = ttk.Frame(parent, style="HUD.TFrame")
        line.pack(side=pack_side, fill="none", expand=False, pady=(0, 2))
        aspect_bg = self._ui_colors.get("panel", "#0a1b27")
        holder = tk.Frame(line, bg=aspect_bg, bd=0, highlightthickness=0)
        holder.pack(side="left", anchor="w")
        icon_box_size = 27

        codes = ("vigilance", "command", "aggression", "cunning", "neutral") if group == "main" else ("heroism", "villainy")
        for code in codes:
            cell_size = 38 if code == "neutral" else icon_box_size
            if code == "neutral":
                # Cadre HUD permanent, comme les boutons d'action principaux.
                cell = tk.Frame(holder, width=cell_size, height=cell_size, bg="#164b68", bd=0, highlightthickness=0)
                neutral_pad = (10, 10)
            else:
                cell = tk.Frame(holder, width=cell_size, height=cell_size, bg=aspect_bg, bd=0, highlightthickness=0)
                neutral_pad = 0
            cell.pack(side="left", padx=neutral_pad, pady=0)
            cell.pack_propagate(False)
            btn_font = ("Arial", 11, "bold") if code == "neutral" else ("Arial", 13, "bold")
            btn = tk.Button(
                cell, font=btn_font, relief="flat", bd=0,
                highlightthickness=0,
                fg=("#ffffff" if code == "neutral" else aspect_bg),
                padx=0, pady=0, cursor="hand2", anchor="center",
                bg=("#102b3b" if code == "neutral" else aspect_bg),
                activebackground=("#164b68" if code == "neutral" else aspect_bg),
                activeforeground="#ffffff"
            )
            btn.pack(fill="both", expand=True, padx=(2 if code == "neutral" else 0), pady=(2 if code == "neutral" else 0))
            btn.configure(command=lambda c=code: self._set_aspect_filter(group, c))
            self._aspect_filter_buttons[(id(variable), code, group)] = btn

        self._refresh_aspect_filter_line(variable, group)

    def _set_aspect_filter(self, group, value):
        value = clean_text(value).lower()
        if group == "main":
            if value:
                if value in self._selected_aspects_main:
                    self._selected_aspects_main.remove(value)
                else:
                    self._selected_aspects_main.add(value)
            else:
                self._selected_aspects_main.clear()
        else:
            # Héroïsme et Infâmie sont mutuellement exclusifs.
            # Cliquer une seconde fois sur l'affinité active la désélectionne :
            # l'état None signifie alors "ne pas filtrer sur Héroïsme/Infâmie".
            if value == "__exclude__":
                # Le bouton d'interdiction est un véritable interrupteur :
                # un second clic revient à l'état neutre (Héroïsme/Infâmie
                # autorisés).
                if self._selected_aspect_alignment == "__exclude__":
                    self._selected_aspect_alignment = None
                else:
                    self._selected_aspect_alignment = "__exclude__"
            elif value and value == self._selected_aspect_alignment:
                self._selected_aspect_alignment = None
            else:
                self._selected_aspect_alignment = value or None
        self._refresh_aspect_filter_line(self.aspect1_filter_var, group)
        self._update_filter_status()

    def _refresh_aspect_filter_line(self, variable, group="main"):
        """Actualise l'état visuel du groupe d'affinités demandé."""
        aspect_bg = self._ui_colors.get("panel", "#0a1b27")
        selected = {clean_text(x).lower() for x in self._selected_aspects_main}
        alignment = clean_text(self._selected_aspect_alignment).lower() if self._selected_aspect_alignment else ""
        codes = ("vigilance", "command", "aggression", "cunning", "neutral") if group == "main" else ("heroism", "villainy")
        for code in codes:
            btn = self._aspect_filter_buttons.get((id(variable), code, group))
            if btn is None or not btn.winfo_exists():
                continue
            active = (code in selected) if group == "main" else (code == alignment)
            try:
                btn.configure(
                    bg=("#164b68" if active else "#102b3b") if code == "neutral" else ("#164b68" if active else aspect_bg),
                    activebackground=("#164b68" if code == "neutral" else "#164b68"),
                    text=("N" if code == "neutral" else ""),
                    font=(("Arial", 11, "bold") if code == "neutral" else ("Arial", 13, "bold")),
                    fg=("#ffffff" if code == "neutral" else aspect_bg),
                    activeforeground="#ffffff",
                    highlightthickness=0,
                    highlightbackground=aspect_bg,
                    highlightcolor=aspect_bg,
                )
            except Exception:
                pass
        if group == "main":
            btn = self._aspect_filter_buttons.get((id(variable), "", group))
            if btn is not None and btn.winfo_exists():
                try:
                    active = not selected
                    photo = self._no_affinity_icon_on if active else self._no_affinity_icon_off
                    btn.configure(image=photo, text="")
                    btn.image = photo
                except Exception:
                    pass
        else:
            btn = self._aspect_filter_buttons.get((id(variable), "", group))
            if btn is not None and btn.winfo_exists():
                try:
                    excluded = alignment == "__exclude__"
                    btn.configure(
                        text="⊘", image="",
                        bg="#164b68" if excluded else aspect_bg,
                        activebackground="#164b68",
                        fg="#ff4040" if excluded else "#d94141",
                        activeforeground="#ff6b6b",
                        font=("Arial", 22, "bold"),
                    )
                    btn.image = None
                except Exception:
                    pass

    def _refresh_aspect_filter_images(self):
        """Charge les icônes agrandies des six affinités dans les boutons."""
        for code in ("vigilance", "command", "aggression", "cunning", "neutral", "heroism", "villainy"):
            btns = []
            for key, btn in self._aspect_filter_buttons.items():
                if len(key) >= 2 and key[1] == code and btn.winfo_exists():
                    btns.append(btn)
            if not btns:
                continue
            if code == "neutral":
                for btn in btns:
                    btn.configure(image="", text="N", fg="#ffffff", highlightthickness=2, highlightbackground="#8fd8ff", highlightcolor="#8fd8ff")
                    btn.image = None
                continue
            path = self._aspect_icon_path(code)
            if path is not None and path.is_file():
                try:
                    im = Image.open(path).convert("RGBA")
                    im.thumbnail((32, 32) if code == "neutral" else (28, 28), Image.Resampling.LANCZOS)
                    photo = ImageTk.PhotoImage(im)
                    self._aspect_filter_images[code] = photo
                    for btn in btns:
                        btn.configure(image=photo, text="")
                        btn.image = photo
                    continue
                except Exception:
                    pass

            # Téléchargement différé uniquement si l'icône n'est pas encore
            # présente dans le cache utilisé par la boîte de dialogue.
            url = self.ASPECT_ICON_URLS.get(code)
            if not url or getattr(self, f"_aspect_filter_download_{code}", False):
                continue
            setattr(self, f"_aspect_filter_download_{code}", True)

            def worker(c=code, u=url):
                try:
                    self.ASPECT_ICON_DIR.mkdir(parents=True, exist_ok=True)
                    response = self.session.get(u, timeout=30)
                    response.raise_for_status()
                    path2 = self._aspect_icon_path(c)
                    if path2 is not None:
                        path2.write_bytes(response.content)
                except Exception:
                    pass
                finally:
                    setattr(self, f"_aspect_filter_download_{c}", False)
                    try:
                        self.root.after(0, self._refresh_aspect_filter_images)
                    except Exception:
                        pass

            threading.Thread(target=worker, daemon=True).start()

    # ------------------------------------------------------------------
    # LOGOS DES EXTENSIONS — SWUDB
    # V79 : logos issus de la même source que SWU Proxy PDF Generator.
    # ------------------------------------------------------------------

    def _extension_logo_cache_path(self, code):
        logo_dir = CACHE_DIR / "_extension_logos_v6"
        logo_dir.mkdir(parents=True, exist_ok=True)
        return logo_dir / f"{safe_filename(str(code).upper())}.png"

    def _normalize_logo_text(self, value):
        """Normalise un nom de set pour permettre une détection automatique."""
        import unicodedata
        text = clean_text(value).lower()
        text = unicodedata.normalize("NFKD", text)
        text = "".join(ch for ch in text if not unicodedata.combining(ch))
        text = re.sub(r"[^a-z0-9]+", " ", text).strip()
        return text

    def _discover_official_set_page(self, code):
        """Découvre automatiquement la page Media Kit correspondant au set.

        Le code du set n'est jamais utilisé comme liste blanche. On récupère
        le catalogue officiel du Media Kit puis on rapproche son nom du nom
        anglais présent dans SQLite. Ainsi un futur set ajouté à la base et au
        Media Kit est pris en charge sans modification du programme.
        """
        code = clean_text(code).upper()
        if not code:
            return None, None

        cache = getattr(self, "_official_set_page_cache", {})
        if code in cache:
            return cache[code]

        english_name = self._english_expansion_name(code)
        target = self._normalize_logo_text(english_name)
        target_tokens = set(target.split())

        # Le Media Kit officiel utilise le nom anglais sous forme de slug
        # dans le paramètre chapter. Cela évite de dépendre du HTML de son
        # menu, qui est rendu dynamiquement.
        slug = re.sub(r"[^a-z0-9]+", "-", target).strip("-")
        if slug:
            direct_url = f"https://starwarsunlimited.com/media-kit?chapter={slug}"
            try:
                test = self.session.get(direct_url, timeout=30)
                if test.ok and "Set Assets" in test.text:
                    page_url = direct_url
                    page_label = english_name
                    result = (page_url, page_label)
                    cache[code] = result
                    self._official_set_page_cache = cache
                    return result
            except Exception:
                pass

        try:
            response = self.session.get(OFFICIAL_MEDIA_KIT_URL, timeout=30)
            response.raise_for_status()
            page_html = response.text
        except Exception:
            cache[code] = (None, None)
            self._official_set_page_cache = cache
            return None, None

        candidates = []
        for match in re.finditer(r"<a\b[^>]*href=[\"']([^\"']+)[\"'][^>]*>(.*?)</a>", page_html, re.I | re.S):
            href = html.unescape(match.group(1).strip())
            label_html = match.group(2)
            label = re.sub(r"<[^>]+>", " ", label_html)
            label = " ".join(label.split())
            if "media-kit?chapter=" not in href.lower():
                continue
            normalized = self._normalize_logo_text(label)
            slug = self._normalize_logo_text(href.split("chapter=", 1)[-1])
            if not normalized and not slug:
                continue

            score = 0
            if target and normalized == target:
                score += 1000
            if target and slug == target:
                score += 900
            if target and target in normalized:
                score += 500
            if target and target in slug:
                score += 450
            if target_tokens:
                score += 100 * len(target_tokens & set(normalized.split()))
                score += 80 * len(target_tokens & set(slug.split()))

            candidates.append((score, urljoin(OFFICIAL_MEDIA_KIT_URL, href), label))

        candidates.sort(key=lambda x: x[0], reverse=True)
        if not candidates or candidates[0][0] <= 0:
            result = (None, None)
        else:
            result = (candidates[0][1], candidates[0][2])

        cache[code] = result
        self._official_set_page_cache = cache
        return result

    def _find_official_set_logo_url(self, code):
        """Trouve automatiquement le logo d'une extension via SWUDB.

        C'est volontairement la même logique que celle utilisée par le
        SWU Proxy PDF Generator : SWUDB expose les logos d'extensions selon
        un schéma stable basé sur le code du set. Cela évite complètement
        les pages Media Kit et leurs ressources dynamiques.

        Exemple :
            SOR -> https://swudb.com/images//expansions/sor_logo.png

        Le fichier n'est retenu que si SWUDB renvoie réellement une image.
        Pour Legends of the Force, SWUDB utilise historiquement ``leg``
        comme nom de fichier ; ce seul alias est conservé comme fallback.
        """
        code = clean_text(code).upper()
        if not code:
            return None

        logo_codes = [code.lower()]
        if code == "LOF":
            logo_codes.append("leg")

        for logo_code in logo_codes:
            url = SWUDB_EXTENSION_LOGO_URL.format(logo_code=logo_code)
            try:
                response = self.session.get(
                    url,
                    timeout=30,
                    headers={"User-Agent": "Mozilla/5.0"},
                    stream=True,
                )
                response.raise_for_status()
                content_type = (response.headers.get("Content-Type") or "").lower()
                if "image/" in content_type:
                    return url

                head = response.raw.read(16, decode_content=True)
                if head.startswith((b"\x89PNG", b"\xff\xd8\xff", b"RIFF")):
                    return url
            except Exception:
                continue

        return None

    def _download_official_logo_data(self, source):
        """Retourne les octets du logo, y compris depuis une archive ZIP."""
        if source.startswith('__ZIP__'):
            payload = source[len('__ZIP__'):]
            zip_url, member = payload.split('||', 1)
            r = self.session.get(zip_url, timeout=60)
            r.raise_for_status()
            with zipfile.ZipFile(io.BytesIO(r.content)) as zf:
                return zf.read(member)
        r = self.session.get(source, timeout=60)
        r.raise_for_status()
        return r.content

    def _equalize_extension_recap_buttons(self, required_height=None):
        """Fixe une hauteur commune stable pour les boutons du récapitulatif.

        La hauteur est déterminée une seule fois, après que les logos ont été
        chargés et que Tkinter a calculé leurs dimensions. Les ouvertures de
        fenêtres, redimensionnements ou autres recalculs de géométrie ne peuvent
        donc plus modifier la hauteur des boutons.
        """
        buttons = [
            b for b in getattr(self, "_extension_recap_buttons", [])
            if b.winfo_exists()
        ]
        self._extension_recap_buttons = buttons
        if not buttons:
            return

        # Les noms longs doivent rester entièrement lisibles. On adapte la
        # largeur de la zone de texte à la cellule réelle du bouton ; si le
        # nom dépasse cette largeur, Tkinter le répartit sur plusieurs lignes
        # au lieu de le tronquer.
        for button in buttons:
            try:
                width = int(button.master.winfo_width()) - 8
                if width > 20:
                    button.configure(wraplength=width)
            except Exception:
                pass
        try:
            self.root.update_idletasks()
        except Exception:
            pass

        # Une fois la hauteur verrouillée, aucune nouvelle mesure ne doit
        # pouvoir l'augmenter lors de l'ouverture d'une boîte de dialogue.
        if getattr(self, "_extension_recap_height_locked", False):
            common = int(getattr(self, "_extension_recap_common_height", 1))
        else:
            heights = []
            for button in buttons:
                try:
                    heights.append(int(button.winfo_reqheight()))
                except Exception:
                    pass
            if required_height is not None:
                try:
                    heights.append(int(required_height))
                except Exception:
                    pass

            common = max(1, max(heights) if heights else 1)
            # Petite marge verticale interne, sans recréer de grand espace vide.
            common = common + 2
            # Sécurité contre une mesure aberrante de Tkinter.
            common = min(common, 180)
            self._extension_recap_common_height = common

        # Chaque bouton occupe une cellule distincte d'une vraie grille à
        # deux colonnes. On fixe également la hauteur des lignes de la grille
        # pour empêcher Tkinter de superposer les conteneurs lorsque la
        # géométrie est recalculée.
        frame = getattr(self, "extension_recap_frame", None)
        if frame is not None and frame.winfo_exists():
            row_count = (len(buttons) + 1) // 2
            for r in range(row_count):
                try:
                    frame.rowconfigure(r, weight=0, minsize=common + 6)
                except Exception:
                    pass

        for index, button in enumerate(buttons):
            try:
                holder = button.master
                holder.configure(height=common)
                holder.grid_propagate(False)
                holder.rowconfigure(0, weight=1)
                holder.columnconfigure(0, weight=1)
                holder.grid_configure(row=index // 2, column=index % 2,
                                      sticky="nsew", padx=3, pady=(0 if index // 2 == 0 else 3, 3))
                button.grid(row=0, column=0, sticky="nsew")
            except Exception:
                pass

    def _lock_extension_recap_height(self):
        """Verrouille définitivement la hauteur après le lancement du récap."""
        try:
            self.update_idletasks()
        except Exception:
            pass
        self._equalize_extension_recap_buttons()
        self._extension_recap_height_locked = True
        try:
            self.extension_recap_canvas.yview_moveto(0)
            bbox = self.extension_recap_canvas.bbox("all")
            if bbox:
                x0, y0, x1, y1 = bbox
                self.extension_recap_canvas.configure(
                    scrollregion=(0, 0, x1, max(0, y1 - y0))
                )
                self.extension_recap_canvas.yview_moveto(0)
        except Exception:
            pass

    def _mark_extension_recap_logo_ready(self, button):
        """Signale qu'un logo (ou son remplacement) est définitivement prêt."""
        try:
            if getattr(button, "_recap_logo_ready", False):
                return
            button._recap_logo_ready = True
            pending = max(0, int(getattr(self, "_extension_recap_pending", 0)) - 1)
            self._extension_recap_pending = pending
            if pending == 0:
                # Tous les boutons ont maintenant leur contenu réel : on peut
                # figer une fois pour toutes la hauteur commune.
                self.root.after_idle(self._lock_extension_recap_height)
        except Exception:
            pass

    def _fit_extension_button_text(self, button):
        """Applique la taille standard de 7 px aux noms d'extensions, sur une seule ligne."""
        if not button or not button.winfo_exists():
            return
        try:
            available = max(40, int(button.master.winfo_width()) - 10)
            text = str(button.cget("text") or "")
            if not text:
                return

            # Les boutons d'extensions utilisent la même taille de police que
            # la zone RECHERCHE : 7 px en gras. On ne réduit pas la police pour
            # les noms longs afin de conserver une présentation strictement
            # homogène entre RECHERCHE et COLLECTION.
            chosen = 7
            button.configure(
                font=("Arial", chosen, "bold"),
                wraplength=0,
                justify="center",
                anchor="center",
            )
        except Exception:
            pass

    def _queue_extension_logo_update(self, callback):
        """Distribue les mises à jour graphiques des logos par petites vagues.

        Les téléchargements restent parallèles, mais les créations PhotoImage /
        configure() sont regroupées par quelques éléments afin d'éviter une
        succession de gros passages dans la boucle Tkinter.
        """
        queue = getattr(self, "_extension_logo_ui_queue", None)
        if queue is None:
            queue = []
            self._extension_logo_ui_queue = queue
        queue.append(callback)

        if getattr(self, "_extension_logo_ui_pending", False):
            return
        self._extension_logo_ui_pending = True

        def _run_batch():
            try:
                current = getattr(self, "_extension_logo_ui_queue", [])
                self._extension_logo_ui_queue = []
                # Petit lot volontairement limité : on privilégie la fluidité
                # de la fenêtre pendant l'apparition progressive des logos.
                for cb in current[:4]:
                    try:
                        cb()
                    except Exception:
                        pass
                remaining = current[4:]
                if remaining:
                    self._extension_logo_ui_queue = remaining + getattr(
                        self, "_extension_logo_ui_queue", []
                    )
                    self.root.after(12, _run_batch)
                else:
                    self._extension_logo_ui_pending = False
            except Exception:
                self._extension_logo_ui_pending = False

        try:
            self.root.after_idle(_run_batch)
        except Exception:
            self._extension_logo_ui_pending = False

    def _load_extension_logo(self, code, target_widget, display_width=None, text=None, equalize_mode="recap"):
        """Charge le logo et construit un bouton de hauteur commune.

        Règles d'affichage :
        - le logo occupe toute la largeur disponible dans la colonne, en
          conservant strictement ses proportions ;
        - le nom de l'extension est placé sous le logo, sur une seule ligne ;
        - si aucun logo n'est disponible, le code à 3 lettres est affiché ;
        - tous les boutons du récapitulatif ont exactement la même hauteur.
        """
        code = clean_text(code).upper()
        text = clean_text(code if text is None else text)
        cache_path = self._extension_logo_cache_path(code)
        is_button = isinstance(target_widget, tk.Button)

        def _button_wraplength():
            """Largeur réelle réservée au texte sous le logo."""
            try:
                parent = target_widget.master
                parent.update_idletasks()
                return max(60, int(parent.winfo_width()) - 8)
            except Exception:
                return 90

        def fallback():
            if not is_button:
                return
            try:
                if target_widget.winfo_exists():
                    parent = target_widget.master
                    parent.update_idletasks()
                    available_width = max(20, parent.winfo_width() - 8)

                    # Pas de logo : même gabarit compact que les vrais logos.
                    # Le code doit rester entièrement visible, sans être coupé
                    # par le bord du bouton.
                    placeholder_w = max(56, min(int(available_width * 0.86), 100))
                    placeholder_h = 22
                    placeholder = Image.new(
                        "RGBA",
                        (placeholder_w, placeholder_h),
                        (13, 38, 52, 255),
                    )
                    draw = ImageDraw.Draw(placeholder)
                    font = None
                    for font_path in (
                        r"C:\Windows\Fonts\arialbd.ttf",
                        r"C:\Windows\Fonts\segoeuib.ttf",
                        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
                    ):
                        try:
                            font = ImageFont.truetype(font_path, 22)
                            break
                        except Exception:
                            continue
                    if font is None:
                        font = ImageFont.load_default()
                    bbox = draw.textbbox((0, 0), code, font=font)
                    tw = bbox[2] - bbox[0]
                    th = bbox[3] - bbox[1]
                    draw.text(
                        ((placeholder_w - tw) / 2, (placeholder_h - th) / 2 - bbox[1]),
                        code,
                        fill="white",
                        font=font,
                    )

                    photo = ImageTk.PhotoImage(placeholder)
                    target_widget.configure(
                        image=photo,
                        text=text,
                        compound='top',
                        anchor='center',
                        justify='center',
                        wraplength=0,
                        padx=1,
                        pady=1,
                    )
                    target_widget.image = photo
                    if equalize_mode == "dialog":
                        try:
                            logo_zone = target_widget.master
                            # En absence de logo, conserver la largeur de la
                            # zone de dialogue sans imposer une hauteur variable.
                            logo_zone.configure(width=200, height=22)
                            logo_zone.pack_propagate(False)
                            logo_zone.grid_propagate(False)
                        except Exception:
                            pass
                    target_widget.update_idletasks()
                    self._fit_extension_button_text(target_widget)
                    callback = getattr(target_widget, "_dialog_geometry_callback", None)
                    if callback:
                        try:
                            self.root.after_idle(callback)
                        except Exception:
                            pass
                    if equalize_mode == "filter":
                        self._equalize_filter_extension_buttons(
                            target_widget.winfo_reqheight()
                        )
                    elif equalize_mode == "collection":
                        self._equalize_collection_extension_buttons(
                            target_widget.winfo_reqheight()
                        )
                    elif equalize_mode == "dialog":
                        # Un logo placé dans une boîte de dialogue ne doit
                        # JAMAIS modifier la hauteur des boutons d'extensions
                        # de l'interface principale.
                        pass
                    else:
                        self._equalize_extension_recap_buttons(
                            target_widget.winfo_reqheight()
                        )
                        self._mark_extension_recap_logo_ready(target_widget)
            except Exception:
                if equalize_mode == "filter":
                    try:
                        self._equalize_filter_extension_buttons()
                    except Exception:
                        pass
                else:
                    self._mark_extension_recap_logo_ready(target_widget)

        def prepare_logo(image):
            """Rogne les marges transparentes et adapte le logo à la largeur."""
            image = image.convert('RGBA')

            alpha = image.getchannel('A')
            bbox = alpha.getbbox()
            if bbox:
                image = image.crop(bbox)

            # display_width peut être soit une largeur maximale, soit un
            # couple (largeur maximale, hauteur maximale).
            #
            # IMPORTANT : pour les logos des dialogues, on ne doit surtout
            # pas utiliser winfo_width() du Label. Lors du chargement
            # asynchrone de l'image, le Label peut encore mesurer 1 px alors
            # que sa zone est déjà prévue pour 200 px. C'est ce qui provoquait
            # les logos minuscules pour certaines cartes.
            max_width = None
            max_height = None
            if display_width is not None:
                try:
                    if isinstance(display_width, (tuple, list)) and len(display_width) >= 2:
                        max_width = int(display_width[0])
                        max_height = int(display_width[1])
                    else:
                        max_width = int(display_width)
                except Exception:
                    pass

            if equalize_mode == "dialog" and max_width and max_width > 1:
                # Dans un dialogue, les dimensions transmises sont celles
                # de la zone d'affichage fixe. Elles sont donc la référence
                # absolue et non une mesure instantanée du widget.
                available_width = max_width
            else:
                # Pour les boutons d'extensions, on mesure le bouton lui-même
                # (et non son conteneur) afin que le logo ne puisse jamais
                # dépasser sa largeur réelle.
                try:
                    target_widget.update_idletasks()
                    available_width = target_widget.winfo_width()
                except Exception:
                    available_width = 0

                if available_width <= 1:
                    try:
                        parent = target_widget.master
                        parent.update_idletasks()
                        available_width = parent.winfo_width()
                    except Exception:
                        pass

                if max_width and max_width > 1:
                    available_width = (
                        min(available_width, max_width)
                        if available_width > 1 else max_width
                    )

                if available_width <= 1:
                    available_width = 180

            # Taille maximale réellement disponible. Pour les boutons
            # d'extensions (RECHERCHE et COLLECTION), le logo ne doit pas
            # toucher les bords ni être tronqué : on reprend exactement le
            # même gabarit compact dans les deux interfaces.
            if equalize_mode in ("filter", "collection"):
                # Les logos restent compacts : leur largeur s'adapte à la
                # cellule, mais leur hauteur est plafonnée afin qu'un logo
                # très vertical ne prenne pas la place du texte.
                # Les proportions originales sont toujours conservées.
                target_width = max(20, min(int(available_width - 28), 100))
                target_height = 42
            else:
                if equalize_mode == "dialog" and max_width:
                    # Dans « Ma collection », la largeur du logo est FIXE.
                    # Seule sa hauteur varie afin de conserver exactement
                    # ses proportions. Il ne faut donc surtout pas imposer
                    # une hauteur maximale qui réduirait les logos horizontaux.
                    target_width = max_width
                    target_height = None
                else:
                    target_width = max(20, available_width - 12)
                    target_height = None
                    if max_height and max_height > 1:
                        target_height = max_height

            # Conserve strictement les proportions et tient dans le cadre
            # largeur/hauteur demandé.
            ratio_w = target_width / float(image.width)
            ratio_h = (target_height / float(image.height)) if target_height else ratio_w
            ratio = min(ratio_w, ratio_h)
            target_width = max(1, int(round(image.width * ratio)))
            target_height = max(1, int(round(image.height * ratio)))
            image = image.resize(
                (target_width, target_height),
                Image.Resampling.LANCZOS,
            )
            return image

        def worker():
            try:
                data = cache_path.read_bytes() if cache_path.is_file() else None
                image = None

                if data is not None:
                    try:
                        image = Image.open(io.BytesIO(data)).convert('RGBA')
                    except Exception:
                        image = None

                if image is None:
                    source = self._find_official_set_logo_url(code)
                    if not source:
                        self._queue_extension_logo_update(fallback)
                        return
                    data = self._download_official_logo_data(source)
                    image = Image.open(io.BytesIO(data)).convert('RGBA')
                    image.save(cache_path, format='PNG')
                    try:
                        cache_path.with_suffix('.source.txt').write_text(
                            source, encoding='utf-8'
                        )
                    except Exception:
                        pass

                def update():
                    if not target_widget.winfo_exists():
                        return
                    try:
                        image_data = prepare_logo(image)
                        photo = ImageTk.PhotoImage(image_data)

                        target_widget.configure(
                            image=photo,
                            text=text,
                            compound='top',
                            anchor='center',
                            justify='center',
                            wraplength=0,
                            padx=1,
                            pady=1,
                        )
                        target_widget.image = photo

                        # Pour les logos de « Ma collection », la zone
                        # d'affichage doit avoir exactement la largeur du
                        # logo (300 px) et une hauteur calculée à partir de
                        # l'image redimensionnée. Ainsi la hauteur varie avec
                        # le ratio du logo, mais sa largeur reste toujours
                        # identique et aucune image n'est tronquée.
                        if equalize_mode == "dialog":
                            try:
                                logo_zone = target_widget.master
                                logo_zone.configure(
                                    width=int(image_data.width),
                                    height=int(image_data.height),
                                )
                                logo_zone.pack_propagate(False)
                                logo_zone.grid_propagate(False)
                            except Exception:
                                pass

                        target_widget.update_idletasks()
                        self._fit_extension_button_text(target_widget)
                        callback = getattr(target_widget, "_dialog_geometry_callback", None)
                        if callback:
                            try:
                                self.root.after_idle(callback)
                            except Exception:
                                pass

                        # On mesure la hauteur réellement nécessaire à ce
                        # bouton puis on l'utilise comme minimum commun.
                        if equalize_mode == "filter":
                            self._equalize_filter_extension_buttons(
                                target_widget.winfo_reqheight()
                            )
                        elif equalize_mode == "collection":
                            self._equalize_collection_extension_buttons(
                                target_widget.winfo_reqheight()
                            )
                        elif equalize_mode == "dialog":
                            # Le logo du dialogue reste strictement local.
                            pass
                        else:
                            self._equalize_extension_recap_buttons(
                                target_widget.winfo_reqheight()
                            )
                            self._mark_extension_recap_logo_ready(target_widget)
                    except Exception:
                        fallback()

                self._queue_extension_logo_update(update)
            except Exception:
                self._queue_extension_logo_update(fallback)

        threading.Thread(target=worker, daemon=True).start()

    def _refresh_dependent_filter_choices(self):
        """Actualise les filtres en cascade : extensions -> mot-clé <-> trait."""
        selected = sorted(getattr(self, "_selected_expansion_codes", set()))
        keyword_code = self._selected_keyword_code()
        trait_code = self._selected_trait_code()

        # Chaque liste tient compte du filtre complémentaire actuellement choisi.
        # L'ordre de reconstruction est volontairement symétrique : si une valeur
        # devient impossible, elle est réinitialisée à « Tous... ».
        self._populate_keyword_filter(selected, trait_code)
        keyword_code = self._selected_keyword_code()
        self._populate_trait_filter(selected, keyword_code)

    def _keyword_filter_changed(self):
        """Un mot-clé modifié recalcule immédiatement la liste des traits compatibles."""
        selected = sorted(getattr(self, "_selected_expansion_codes", set()))
        self._populate_trait_filter(selected, self._selected_keyword_code())
        self._update_filter_status()

    def _trait_filter_changed(self):
        """Un trait modifié recalcule immédiatement la liste des mots-clés compatibles."""
        selected = sorted(getattr(self, "_selected_expansion_codes", set()))
        self._populate_keyword_filter(selected, self._selected_trait_code())
        self._update_filter_status()

    def _set_filter_extension(self, code, display_name):
        """Ajoute/retire une extension de la sélection multiple des filtres."""
        code = clean_text(code).upper()
        display_name = clean_text(display_name)
        selected = getattr(self, "_selected_expansion_codes", set())

        if code in selected:
            selected.remove(code)
        else:
            selected.add(code)
        self._selected_expansion_codes = selected

        # Le StringVar reste utilisé par quelques fonctions historiques : on y
        # conserve maintenant un résumé lisible de la sélection multiple.
        labels = []
        for item_code in sorted(selected):
            button = getattr(self, "_filter_extension_buttons", {}).get(item_code)
            if button is not None:
                labels.append(f"{item_code} — {clean_text(button.cget('text'))}")
            elif item_code == code:
                labels.append(f"{item_code} — {display_name}")
            else:
                labels.append(item_code)
        self.expansion.set(" ; ".join(labels))

        for item_code, button in getattr(self, "_filter_extension_buttons", {}).items():
            try:
                is_selected = item_code in selected
                button.configure(
                    relief="sunken" if is_selected else "flat",
                    bg="#164b68" if is_selected else "#0d2634",
                    activebackground="#205f7f" if is_selected else "#164b68",
                    highlightbackground="#f2c94c" if is_selected else "#07131d",
                    highlightcolor="#f2c94c" if is_selected else "#07131d",
                    highlightthickness=2 if is_selected else 0,
                )
            except Exception:
                pass

        # Les mots-clés et traits disponibles correspondent à l'union des sets sélectionnés.
        self._refresh_dependent_filter_choices()
        self._update_filter_status()

    def _equalize_filter_extension_buttons(self, required_height=None):
        """Donne aux boutons d'extensions des filtres une hauteur commune."""
        buttons = [
            b for b in getattr(self, "_filter_extension_buttons", {}).values()
            if b.winfo_exists()
        ]
        if not buttons:
            return

        # Les noms d'extensions restent toujours sur UNE seule ligne.
        # On adapte dynamiquement la taille de la police à la largeur réelle
        # de la cellule afin d'éviter toute troncature, notamment pour IBH
        # et TS26.
        for button in buttons:
            try:
                self._fit_extension_button_text(button)
            except Exception:
                pass

        try:
            self.root.update_idletasks()
        except Exception:
            pass

        heights = []
        for button in buttons:
            try:
                heights.append(int(button.winfo_reqheight()))
            except Exception:
                pass
        if required_height is not None:
            try:
                heights.append(int(required_height))
            except Exception:
                pass
        common = max(heights) if heights else 1
        common = min(common, 180)
        self._filter_extension_common_height = common

        frame = getattr(self, "filter_extension_frame", None)
        if frame is not None and frame.winfo_exists():
            row_count = (len(buttons) + 1) // 2
            for r in range(row_count):
                try:
                    frame.rowconfigure(r, minsize=common, weight=0)
                except Exception:
                    pass

        for index, button in enumerate(buttons):
            try:
                holder = button.master
                holder.configure(height=common)
                holder.grid_propagate(False)
                holder.rowconfigure(0, weight=1)
                holder.columnconfigure(0, weight=1)
                holder.grid_configure(
                    row=index // 2, column=index % 2, sticky="nsew",
                    padx=3, pady=(0 if index // 2 == 0 else 3, 3)
                )
                button.grid(row=0, column=0, sticky="nsew")
            except Exception:
                pass

    def build_extension_filter_buttons(self, rows, collection=False):
        """Construit les boutons d'extensions avec un gabarit unique.

        RECHERCHE et COLLECTION utilisent volontairement exactement la même
        construction. Seule l'action du bouton et le conteneur de destination
        changent. Cela évite que deux implémentations de boutons divergent au
        fil des corrections de taille, de logo ou de texte.
        """
        if collection:
            frame = getattr(self, "extension_recap_frame", None)
            if frame is None or not frame.winfo_exists():
                return
            button_store = {}
            holder_store = {}
            self._extension_recap_buttons = []
            self._extension_recap_holders = {}
            self._extension_recap_common_height = 0
            self._extension_recap_height_fixed = False
            self._extension_recap_pending = len(rows)
        else:
            frame = getattr(self, "filter_extension_frame", None)
            if frame is None or not frame.winfo_exists():
                return
            button_store = {}
            holder_store = {}
            self._filter_extension_buttons = button_store
            self._filter_extension_holders = holder_store
            self._filter_extension_common_height = 0

        for child in frame.winfo_children():
            child.destroy()

        frame.columnconfigure(0, weight=1, uniform="filter_extensions")
        frame.columnconfigure(1, weight=1, uniform="filter_extensions")

        current_codes = set(getattr(self, "_selected_expansion_codes", set())) if not collection else set()

        for index, row in enumerate(rows):
            code = clean_text(row["code"]).upper()
            name = clean_text(row["localized_name"] or row["fallback_name"])
            r = index // 2
            c = index % 2

            holder = tk.Frame(frame, bg="#07131d", bd=0, highlightthickness=0)
            holder.grid(
                row=r, column=c, sticky="nsew",
                padx=3, pady=(0 if r == 0 else 3, 3)
            )
            holder.columnconfigure(0, weight=1)

            if collection:
                command = lambda ec=code: self.open_collection_recap(ec)
                selected = False
            else:
                command = lambda ec=code, en=name: self._set_filter_extension(ec, en)
                selected = code in current_codes

            btn = tk.Button(
                holder,
                text=name,
                command=command,
                font=("Arial", 7, "bold"),
                bg="#164b68" if selected else "#0d2634",
                fg="white",
                activebackground="#205f7f" if selected else "#164b68",
                activeforeground="white",
                relief="sunken" if selected else "flat",
                highlightbackground="#f2c94c" if selected else "#07131d",
                highlightcolor="#f2c94c" if selected else "#07131d",
                highlightthickness=2 if selected else 0,
                bd=0,
                cursor="hand2",
                compound="top",
                anchor="center",
                justify="center",
                wraplength=0,
                padx=1,
                pady=1,
            )
            btn.grid(row=0, column=0, sticky="nsew")

            button_store[code] = btn
            holder_store[code] = holder
            if collection:
                self._extension_recap_buttons.append(btn)
                self._extension_recap_holders[code] = holder

            # Même moteur de logo dans les deux zones. Le moteur reçoit
            # simplement le nom du groupe à redimensionner.
            self._load_extension_logo(
                code, btn, text=name,
                equalize_mode="collection" if collection else "filter"
            )

            if collection:
                scroll_handler = getattr(self, "_scroll_extension_recap", None)
            else:
                scroll_handler = getattr(self, "_filter_extension_scroll_handler", None)
            if scroll_handler is not None:
                for widget in (holder, btn):
                    widget.bind("<MouseWheel>", scroll_handler, add="+")
                    widget.bind("<Button-4>", scroll_handler, add="+")
                    widget.bind("<Button-5>", scroll_handler, add="+")

        if not collection:
            try:
                self.filter_extension_canvas.yview_moveto(0)
                self.filter_extension_canvas.configure(
                    scrollregion=self.filter_extension_canvas.bbox("all")
                )
            except Exception:
                pass
        else:
            try:
                self.root.update_idletasks()
                self._equalize_collection_extension_buttons()
                self.extension_recap_canvas.yview_moveto(0)
                self._update_collection_extension_scroll()
            except Exception:
                pass

    def _equalize_collection_extension_buttons(self, required_height=None):
        """Reprend exactement la hauteur calculée pour RECHERCHE."""
        buttons = [
            b for b in getattr(self, "_extension_recap_buttons", [])
            if b.winfo_exists()
        ]
        if not buttons:
            return

        common = int(getattr(self, "_filter_extension_common_height", 0) or 0)
        if common <= 0:
            common = 60
        common = max(1, min(common, 180))
        self._extension_recap_common_height = common
        self._extension_recap_height_fixed = True

        frame = getattr(self, "extension_recap_frame", None)
        if frame is not None and frame.winfo_exists():
            row_count = (len(buttons) + 1) // 2
            for r in range(row_count):
                try:
                    frame.rowconfigure(
                        r, minsize=common, maxsize=common, weight=0
                    )
                except Exception:
                    pass
        for index, button in enumerate(buttons):
            try:
                holder = button.master
                holder.configure(height=common)
                holder.grid_propagate(False)
                holder.rowconfigure(0, weight=1)
                holder.columnconfigure(0, weight=1)
                holder.grid_configure(
                    row=index // 2, column=index % 2, sticky="nsew",
                    padx=3, pady=(0 if index // 2 == 0 else 3, 3)
                )
                button.grid(row=0, column=0, sticky="nsew")
            except Exception:
                pass

    def _sync_collection_extension_height_from_search(self):
        """Aligne COLLECTION sur la hauteur réelle des boutons RECHERCHE."""
        try:
            self._equalize_collection_extension_buttons()
            self._update_collection_extension_scroll()
            return True
        except Exception:
            return False

    def build_extension_recap_buttons(self, rows):
        """Compatibilité : COLLECTION utilise exactement le constructeur de RECHERCHE."""
        return self.build_extension_filter_buttons(rows, collection=True)

    def _refresh_collection_extension_buttons(self):
        """Ancien point d'entrée conservé pour compatibilité.

        COLLECTION est maintenant dimensionnée une seule fois lors de sa
        construction. Cette méthode ne déclenche donc plus de recalcul de
        hauteur asynchrone.
        """
        try:
            self._equalize_collection_extension_buttons()
            self._update_collection_extension_scroll()
        except Exception:
            pass

    def _update_collection_extension_scroll(self):
        try:
            self.extension_recap_canvas.update_idletasks()
            bbox = self.extension_recap_canvas.bbox("all")
            if not bbox:
                return
            _, y0, x1, y1 = bbox
            viewport_h = self.extension_recap_canvas.winfo_height()
            content_h = max(0, y1 - y0)
            if content_h <= viewport_h + 1:
                self.extension_recap_canvas.yview_moveto(0)
                self.extension_recap_scrollbar.pack_forget()
            elif not self.extension_recap_scrollbar.winfo_ismapped():
                self.extension_recap_scrollbar.pack(side="right", fill="y")
            self.extension_recap_canvas.configure(
                scrollregion=(0, 0, max(x1, self.extension_recap_canvas.winfo_width()), max(y1, viewport_h))
            )
        except Exception:
            pass

    def _estimate_collection_value(self, expansion_code=None):
        """Estime la valeur des exemplaires possédés à partir du Price Guide Cardmarket.

        Le calcul utilise le prix ``low`` du produit Cardmarket correspondant à
        chaque impression réellement possédée et multiplie ce tarif par la
        quantité possédée. Les langues sont additionnées car le Price Guide
        public ne fournit pas ici de tarif distinct par langue. Les exemplaires
        sans correspondance ou sans tarif sont comptabilisés comme non évalués.
        """
        if not getattr(self, "_cardmarket_loaded", False) or self.db is None:
            return {"value": 0.0, "priced_copies": 0, "unpriced_copies": 0}

        where = "WHERE e.code = ?" if expansion_code else ""
        params = (expansion_code,) if expansion_code else ()
        try:
            rows = self.db.execute(f"""
                SELECT
                    cp.id AS printing_id,
                    cp.card_uid,
                    cp.card_concept_id AS concept_id,
                    e.code AS expansion_code,
                    vt.variant_id,
                    cl.title,
                    cl.subtitle,
                    (
                        SELECT cp_std.card_uid
                        FROM card_printing cp_std
                        JOIN variant_type vt_std ON vt_std.id = cp_std.variant_type_id
                        WHERE cp_std.card_concept_id = cp.card_concept_id
                          AND cp_std.expansion_id = cp.expansion_id
                          AND vt_std.variant_id = '01'
                        ORDER BY cp_std.id
                        LIMIT 1
                    ) AS standard_uid
                FROM card_printing cp
                JOIN expansion e ON e.id = cp.expansion_id
                JOIN variant_type vt ON vt.id = cp.variant_type_id
                LEFT JOIN card_localization cl
                  ON cl.card_concept_id = cp.card_concept_id
                 AND cl.language_id = 1
                {where}
                ORDER BY e.sort_value, e.code, cp.id
            """, params).fetchall()
        except Exception:
            return {"value": 0.0, "priced_copies": 0, "unpriced_copies": 0}

        cards_data = self.collection.get("cards", {}) if isinstance(self.collection, dict) else {}
        total_value = 0.0
        priced_copies = 0
        unpriced_copies = 0
        price_cache = {}
        seen_stock_variants = set()

        for row in rows:
            standard_uid = clean_text(row["standard_uid"] or row["card_uid"])
            if not standard_uid:
                continue
            raw = cards_data.get(standard_uid, {}) if isinstance(cards_data, dict) else {}
            if not isinstance(raw, dict):
                continue
            languages = raw.get("languages", {})
            variant_id = clean_text(row["variant_id"]) or "01"
            quantity = 0
            if isinstance(languages, dict):
                for lang_values in languages.values():
                    if isinstance(lang_values, dict):
                        try:
                            quantity += max(0, int(lang_values.get(variant_id, 0) or 0))
                        except (TypeError, ValueError):
                            pass
            else:
                try:
                    quantity = max(0, int(raw.get(variant_id, 0) or 0))
                except (TypeError, ValueError):
                    quantity = 0
            if quantity <= 0:
                continue
            stock_variant_key = (standard_uid, variant_id)
            if stock_variant_key in seen_stock_variants:
                continue
            seen_stock_variants.add(stock_variant_key)

            cache_key = (clean_text(row["printing_id"]), variant_id)
            if cache_key not in price_cache:
                card = {
                    "printing_id": row["printing_id"],
                    "concept_id": row["concept_id"],
                    "card_concept_id": row["concept_id"],
                    "card_uid": row["card_uid"],
                    "expansion_code": row["expansion_code"],
                    "title": row["title"] or "",
                    "subtitle": row["subtitle"] or "",
                }
                try:
                    result = self._synchronize_cardmarket_price(
                        card, variant_id, self.language.get() if hasattr(self, "language") else "fr"
                    )
                    price_cache[cache_key] = result.get("price") if result and result.get("status") == "indicative" else None
                except Exception:
                    price_cache[cache_key] = None

            price = price_cache.get(cache_key)
            if price is None:
                unpriced_copies += quantity
            else:
                total_value += float(price) * quantity
                priced_copies += quantity

        return {
            "value": total_value,
            "priced_copies": priced_copies,
            "unpriced_copies": unpriced_copies,
        }

    @staticmethod
    def _format_estimated_value(value):
        try:
            return f"{float(value):,.2f} €".replace(",", "X").replace(".", ",").replace("X", " ")
        except (TypeError, ValueError):
            return "—"

    def _collection_recap_stats(self, expansion_code=None):
        """Calcule une synthèse légère à partir de la base + JSON utilisateur."""
        if self.db is None:
            return []
        where = ""
        params = []
        if expansion_code:
            where = "WHERE e.code = ?"
            params.append(expansion_code)

        # Le nombre de playsets possibles correspond STRICTEMENT aux cartes
        # Standard du set. Les variantes (Foil, Hyperspace, Weekly Play,
        # promotions, etc.) ne créent jamais de nouveau playset.
        # Les leaders et les bases sont ensuite exclus par type_code.
        rows = self.db.execute(
            f"""
            SELECT DISTINCT cp.card_uid, e.code AS expansion_code,
                   CASE
                       WHEN e.code = 'SOR' THEN 'Spark of Rebellion'
                       ELSE COALESCE(el.name, e.name, e.code)
                   END AS expansion_name,
                   ct.code AS type_code
            FROM card_printing cp
            JOIN card_concept cc ON cc.id = cp.card_concept_id
            LEFT JOIN card_type ct ON ct.id = cc.type_id
            JOIN expansion e ON e.id = cp.expansion_id
            JOIN variant_type vt ON vt.id = cp.variant_type_id
            LEFT JOIN expansion_localization el
              ON el.expansion_id = e.id AND el.language_id = ?
            {where}
              AND vt.variant_id = '01'
            ORDER BY e.sort_value, e.code, cp.card_uid
            """,
            [LANGUAGES.get(self.language.get(), LANGUAGES["fr"])] + params
        ).fetchall()

        by_exp = {}
        cards_data = self.collection.get("cards", {}) if isinstance(self.collection, dict) else {}
        for row in rows:
            code = clean_text(row["expansion_code"]).upper()
            key = clean_text(row["card_uid"])
            if not key:
                continue

            # Un playset concerne uniquement les cartes classiques. Les
            # leaders et les bases ne sont donc jamais comptabilisés parmi
            # les playsets possibles.
            type_code = clean_text(row["type_code"]).lower()
            is_playset_card = type_code not in {"leader", "base"}

            raw = cards_data.get(key, {}) if isinstance(cards_data, dict) else {}
            owned = 0
            wanted = False
            if isinstance(raw, dict):
                langs = raw.get("languages", {})
                if isinstance(langs, dict):
                    for values in langs.values():
                        if isinstance(values, dict):
                            for v in values.values():
                                try:
                                    owned += max(0, int(v or 0))
                                except (TypeError, ValueError):
                                    pass
                wanted_raw = self.wanted_data.get("cards", {}).get(key, {}) if isinstance(getattr(self, "wanted_data", {}), dict) else {}
                wanted = isinstance(wanted_raw, dict) and any(bool(v) for v in wanted_raw.values())

            entry = by_exp.setdefault(code, {
                "name": clean_text(row["expansion_name"]),
                "total": set(),
                "owned_cards": set(),
                "wanted": 0,
                "trade": 0,
                "copies": 0,
                "playset_possible": set(),
                "playset_completed": set(),
            })
            entry["total"].add(key)
            if owned > 0:
                entry["owned_cards"].add(key)
                entry["copies"] += owned
            if wanted:
                entry["wanted"] += 1
            if isinstance(raw, dict):
                trade = self.trade_data.get("cards", {}).get(key, {}) if isinstance(getattr(self, "trade_data", {}), dict) else {}
                if isinstance(trade, dict):
                    for values in trade.values():
                        if isinstance(values, dict):
                            for value in values.values():
                                try:
                                    entry["trade"] += max(0, int(value or 0))
                                except (TypeError, ValueError):
                                    pass
            if is_playset_card:
                entry["playset_possible"].add(key)
                # Toutes les langues et toutes les versions sont additionnées
                # avant de vérifier le seuil de 3 exemplaires.
                if owned >= 3:
                    entry["playset_completed"].add(key)

        result = []
        for code, item in by_exp.items():
            total = len(item["total"])
            owned_cards = len(item["owned_cards"])
            playset_possible = len(item["playset_possible"])
            playset_completed = len(item["playset_completed"])
            pct = (owned_cards / total * 100) if total else 0
            # La valeur Cardmarket est calculée après l'affichage du récapitulatif.
            result.append({"code": code, "name": item["name"], "total": total,
                           "owned_cards": owned_cards, "copies": item["copies"],
                           "wanted": item["wanted"], "trade": item["trade"], "pct": pct,
                           "playset_possible": playset_possible,
                           "playset_completed": playset_completed,
                           "estimated_value": 0.0,
                           "priced_copies": 0,
                           "unpriced_copies": 0})
        return result

    def _collection_variant_rows(self, expansion_code):
        """Retourne toutes les impressions réellement présentes dans le set.

        Cette méthode utilise volontairement une requête minimale et robuste :
        card_printing + expansion + variant_type. Les images sont ensuite
        résolues par le mécanisme déjà utilisé par la galerie principale.
        Ainsi, l'affichage ne dépend pas de la présence d'une ligne card_image
        dans la langue courante et une erreur d'image ne peut pas supprimer la
        liste des impressions.
        """
        if self.db is None or not expansion_code:
            return []

        sql = """
            SELECT
                cp.id AS printing_id,
                cp.card_uid,
                cp.serial_code,
                cp.card_number,
                cp.card_concept_id AS concept_id,
                cc.cost,
                ct.code AS type_code,
                cl.title,
                cl.subtitle,
                e.code AS expansion_code,
                COALESCE(e.name, e.code) AS expansion_name,
                vt.variant_id,
                COALESCE(vtl.name, vtl_en.name, vt.variant_id) AS variant_name,
                COALESCE(vtl.sort_value, vtl_en.sort_value, 9999) AS variant_sort
            FROM card_printing cp
            LEFT JOIN card_concept cc ON cc.id = cp.card_concept_id
            LEFT JOIN card_type ct ON ct.id = cc.type_id
            LEFT JOIN card_localization cl
              ON cl.card_concept_id = cc.id
             AND cl.language_id = ?
            JOIN expansion e ON e.id = cp.expansion_id
            JOIN variant_type vt ON vt.id = cp.variant_type_id
            LEFT JOIN variant_type_localization vtl
              ON vtl.variant_type_id = vt.id
             AND vtl.language_id = ?
            LEFT JOIN variant_type_localization vtl_en
              ON vtl_en.variant_type_id = vt.id
             AND vtl_en.language_id = 1
            WHERE e.code = ?
            ORDER BY
                CASE
                    WHEN cp.card_number IS NULL OR TRIM(CAST(cp.card_number AS TEXT)) = '' THEN 999999
                    WHEN TRIM(CAST(cp.card_number AS TEXT)) GLOB '[0-9]*'
                        THEN CAST(cp.card_number AS INTEGER)
                    ELSE 999999
                END,
                cp.card_number,
                COALESCE(vtl.sort_value, vtl_en.sort_value, 9999),
                cp.id
        """

        lang_id = LANGUAGES.get(self.language.get(), LANGUAGES["fr"])
        try:
            rows = self.db.execute(sql, (lang_id, lang_id, expansion_code)).fetchall()
        except Exception:
            # Compatibilité maximale : même si les localisations de variante
            # sont absentes, les impressions doivent rester affichables.
            try:
                rows = self.db.execute("""
                    SELECT cp.id AS printing_id, cp.card_uid, cp.serial_code,
                           cp.card_number, cp.card_concept_id AS concept_id,
                           cc.cost, ct.code AS type_code,
                           cl.title, cl.subtitle,
                           e.code AS expansion_code, COALESCE(e.name,e.code) AS expansion_name,
                           vt.variant_id, vt.variant_id AS variant_name,
                           9999 AS variant_sort
                    FROM card_printing cp
                    LEFT JOIN card_concept cc ON cc.id = cp.card_concept_id
                    LEFT JOIN card_type ct ON ct.id = cc.type_id
                    LEFT JOIN card_localization cl
                      ON cl.card_concept_id = cc.id
                     AND cl.language_id = ?
                    JOIN expansion e ON e.id = cp.expansion_id
                    JOIN variant_type vt ON vt.id = cp.variant_type_id
                    WHERE e.code = ?
                    ORDER BY
                        CASE WHEN cp.card_number IS NULL OR TRIM(CAST(cp.card_number AS TEXT))=''
                             THEN 999999 ELSE CAST(cp.card_number AS INTEGER) END,
                        cp.id
                """, (lang_id, expansion_code)).fetchall()
            except Exception:
                return []

        result = []
        for r in rows:
            item = dict(r)
            item["variant_id"] = clean_text(item.get("variant_id")) or "01"
            item["variant_name"] = clean_text(item.get("variant_name")) or item["variant_id"]
            item["expansion_code"] = clean_text(item.get("expansion_code")).upper()
            item["expansion_name"] = clean_text(item.get("expansion_name")) or item["expansion_code"]
            item["title"] = clean_text(item.get("title")) or item["card_number"] or item.get("card_uid") or "Carte"
            try:
                item["available_languages"] = self._get_variant_language_availability(
                    item, item["variant_id"]
                )
            except Exception:
                item["available_languages"] = set(LANGUAGES.keys())
            item["image_language_id"] = lang_id
            result.append(item)
        return result

    def _collection_variant_card(self, row, parent, counts, image_done_callback=None):
        """Crée une miniature de collection pour une impression précise.

        En mode COLLECTION, les quantités par langue ne sont plus affichées
        sous la carte : elles apparaissent dans une petite fenêtre au survol.
        Cela permet de conserver la même densité visuelle que la galerie
        RECHERCHE.
        """
        card = dict(row)
        card["title"] = clean_text(row.get("title")) or clean_text(row.get("card_number")) or clean_text(row.get("card_uid")) or "Carte"
        card["subtitle"] = ""
        card["display_language_id"] = row.get("image_language_id")
        card["image_language_id"] = row.get("image_language_id")
        card["variant_id"] = clean_text(row.get("variant_id")) or "01"
        card["variant_name"] = clean_text(row.get("variant_name")) or card["variant_id"]

        # La vue COLLECTION peut afficher une impression Foil/Hyperspace/etc.,
        # mais les quantités sont enregistrées dans la collection sous la clé
        # de l'impression Standard du même concept. On conserve l'identifiant
        # de l'impression affichée pour les images, tout en fournissant la clé
        # de stock au dialogue de gestion.
        try:
            concept_id = clean_text(row.get("concept_id") or row.get("card_concept_id"))
            expansion_code = clean_text(row.get("expansion_code")).upper()
            if concept_id and self.db is not None:
                standard_row = self.db.execute(
                    """
                    SELECT cp.card_uid
                    FROM card_printing cp
                    JOIN expansion e ON e.id = cp.expansion_id
                    JOIN variant_type vt ON vt.id = cp.variant_type_id
                    WHERE cp.card_concept_id = ?
                      AND e.code = ?
                      AND vt.variant_id = '01'
                    ORDER BY cp.id
                    LIMIT 1
                    """,
                    (concept_id, expansion_code)
                ).fetchone()
                if standard_row and standard_row[0]:
                    card["_collection_stock_card_uid"] = clean_text(standard_row[0])
        except Exception:
            pass

        cell = tk.Frame(parent, bg="#07131d", padx=4, pady=4,
                        highlightthickness=1, highlightbackground="#294455")
        image_holder = tk.Label(cell, text="Chargement…", bg="#07131d", fg="#91a8b5",
                                width=18, height=18)
        image_holder.pack()
        image_holder._swu_card = card

        tk.Label(cell, text=f"#{clean_text(row.get('card_number')) or '?'}",
                 bg="#07131d", fg="#dce8ee", font=("Arial", 9, "bold")).pack(pady=(4, 0))
        tk.Label(cell, text=clean_text(row.get("variant_name")) or clean_text(row.get("variant_id")),
                 bg="#07131d", fg="#91a8b5", font=("Arial", 8), wraplength=170).pack()

        # Stock détaillé disponible au survol.
        self._bind_collection_stock_hover(cell, card, counts)
        self._bind_collection_stock_hover(image_holder, card, counts)

        def resolve_and_load():
            try:
                lang_id = card.get("image_language_id") or LANGUAGES.get(self.language.get(), 2)
                available = card.get("available_languages") or set(LANGUAGES.keys())
                cached = self._cache_image_path(card, lang_id)
                if cached:
                    source = str(cached)
                else:
                    source = self._resolve_image_url(
                        card.get("printing_id"), card.get("card_uid"), lang_id,
                        card.get("serial_code")
                    )
                if not source and "en" in available and lang_id != LANGUAGES["en"]:
                    lang_id = LANGUAGES["en"]
                    card["image_language_id"] = lang_id
                    cached = self._cache_image_path(card, lang_id)
                    source = str(cached) if cached else self._resolve_image_url(
                        card.get("printing_id"), card.get("card_uid"), lang_id,
                        card.get("serial_code")
                    )
                if not source:
                    self.root.after(0, lambda: self._set_image_error(image_holder, "Image indisponible"))
                    if image_done_callback is not None:
                        self.root.after(0, image_done_callback)
                    return
                self.download_and_show(
                    source, image_holder, card["printing_id"],
                    card.get("expansion_code"), card.get("expansion_name"),
                    lang_id, card.get("serial_code"), card.get("title"),
                    image_done_callback=image_done_callback
                )
            except Exception:
                self.root.after(0, lambda: self._set_image_error(image_holder, "Image indisponible"))
                if image_done_callback is not None:
                    self.root.after(0, image_done_callback)
        self._image_executor.submit(resolve_and_load)

        # Le clic doit fonctionner sur toute la carte, y compris l'image et
        # les libellés. Tkinter ne propage pas automatiquement un événement
        # d'un widget enfant vers son Frame parent : le binding sur ``cell``
        # seul ne suffit donc pas.
        #
        # Chaque widget déclenche le même gestionnaire et retourne ``break``
        # afin d'empêcher un éventuel second traitement de l'événement.
        def _open_collection_from_click(event=None, c=card):
            self.open_collection_dialog(c)
            return "break"

        for widget in (cell, *cell.winfo_children()):
            widget.bind("<Button-1>", _open_collection_from_click)

        # En mode COLLECTION, le survol est réservé au stock détaillé :
        # on ne déclenche pas le zoom de la galerie Recherche qui masquait
        # auparavant le popup de stock.
        return cell

    def _bind_collection_stock_hover(self, widget, card, counts):
        """Affiche les stocks par langue au survol d'une carte de COLLECTION."""
        widget.bind("<Enter>", lambda e, w=widget, c=card, ct=dict(counts):
                    self._show_collection_stock_tooltip(e, w, c, ct), add="+")
        widget.bind("<Leave>", lambda _e, w=widget: self._schedule_collection_stock_tooltip_hide(w), add="+")

    def _show_collection_stock_tooltip(self, event, widget, card, counts):
        self._hide_collection_stock_tooltip(widget)
        if not widget.winfo_exists():
            return

        variant = clean_text(card.get("variant_name")) or clean_text(card.get("variant_id"))
        number = clean_text(card.get("card_number")) or "?"
        title = clean_text(card.get("title")) or f"Carte {number}"
        flags = {"fr": "🇫🇷", "en": "🇬🇧", "de": "🇩🇪", "it": "🇮🇹", "es": "🇪🇸"}
        names = {"fr": "Français", "en": "English", "de": "Deutsch", "it": "Italiano", "es": "Español"}
        available = card.get("available_languages") or set(LANGUAGES.keys())

        popup = tk.Toplevel(self.root)
        popup.overrideredirect(True)
        popup.attributes("-topmost", True)
        popup.configure(bg="#07131d")
        frame = tk.Frame(popup, bg="#0a1b27", bd=1, relief="solid",
                         highlightthickness=1, highlightbackground="#2f9bd1")
        frame.pack(padx=1, pady=1)

        tk.Label(frame, text=f"#{number} — {variant}", bg="#0a1b27", fg="#e2b84b",
                 font=("Arial", 10, "bold"), padx=12, pady=(8, 2)).pack(anchor="w")
        tk.Label(frame, text=title, bg="#0a1b27", fg="#e7f1f7",
                 font=("Arial", 9, "bold"), padx=12, pady=(0, 5)).pack(anchor="w")

        for lang in ("fr", "en", "de", "it", "es"):
            if lang not in available:
                continue
            qty = max(0, int(counts.get(lang, 0) or 0))
            tk.Label(frame, text=f"{flags[lang]}  {names[lang]} : {qty}",
                     bg="#0a1b27", fg="#e7f1f7", font=("Arial", 9),
                     anchor="w", padx=12, pady=1).pack(fill="x")

        total = sum(max(0, int(v or 0)) for v in counts.values())
        tk.Label(frame, text=f"Total : {total}", bg="#0a1b27", fg="#e2b84b",
                 font=("Arial", 9, "bold"), anchor="w", padx=12, pady=(5, 8)).pack(fill="x")

        popup.update_idletasks()
        x = event.x_root + 16
        y = event.y_root + 16
        sw, sh = popup.winfo_screenwidth(), popup.winfo_screenheight()
        w, h = popup.winfo_width(), popup.winfo_height()
        if x + w > sw - 8:
            x = event.x_root - w - 16
        if y + h > sh - 8:
            y = event.y_root - h - 16
        popup.geometry(f"+{max(5, x)}+{max(5, y)}")
        if not hasattr(self, "_collection_stock_tooltips"):
            self._collection_stock_tooltips = {}
        self._collection_stock_tooltips[widget] = popup

        popup.bind("<Enter>", lambda _e, w=widget: self._cancel_collection_stock_tooltip_hide(w))
        popup.bind("<Leave>", lambda _e, w=widget: self._schedule_collection_stock_tooltip_hide(w))

    def _cancel_collection_stock_tooltip_hide(self, widget):
        job = getattr(self, "_collection_stock_tooltip_jobs", {}).pop(widget, None)
        if job is not None:
            try:
                self.root.after_cancel(job)
            except Exception:
                pass

    def _schedule_collection_stock_tooltip_hide(self, widget):
        self._cancel_collection_stock_tooltip_hide(widget)
        if not hasattr(self, "_collection_stock_tooltip_jobs"):
            self._collection_stock_tooltip_jobs = {}
        self._collection_stock_tooltip_jobs[widget] = self.root.after(180, lambda w=widget: self._hide_collection_stock_tooltip(w))

    def _hide_collection_stock_tooltip(self, widget):
        if hasattr(self, "_collection_stock_tooltip_jobs"):
            self._cancel_collection_stock_tooltip_hide(widget)
        popup = getattr(self, "_collection_stock_tooltips", {}).pop(widget, None) if hasattr(self, "_collection_stock_tooltips") else None
        if popup is not None:
            try:
                popup.destroy()
            except Exception:
                pass

    # ------------------------------------------------------------------
    # PROGRESSION DES GROS AFFICHAGES
    # ------------------------------------------------------------------

    def _start_gallery_loading(self, total):
        """Affiche le chargement des galeries et verrouille les cartes."""
        # Un nouveau chargement doit pouvoir remplacer proprement l'ancien HUD.
        self._stop_gallery_loading(force=True)
        total = max(1, int(total or 0))
        self._gallery_loading = True
        self._gallery_loading_total = total
        self._gallery_loading_done = 0
        self._gallery_loading_created = 0
        self._gallery_loading_images_done = 0
        self._gallery_loading_cards_total = total
        self._gallery_loading_phase = "distribution"
        self._gallery_loading_stable_checks = 0
        self._gallery_loading_last_bbox = None
        # Verrou indépendant du HUD : une carte ne devient cliquable que
        # lorsque toute la chaîne de construction/rendu de la galerie est
        # réellement terminée.
        self._gallery_ready = False
        self._gallery_loading_generation = int(getattr(self, "_gallery_batch_generation", 0) or 0)

        win, win_body = self._create_hud_toplevel(self.root, "SWU Collection Manager")
        frame = tk.Frame(
            win_body, bg="#0b1d2a", bd=1, relief="solid",
            highlightthickness=1, highlightbackground="#2f9bd1"
        )
        frame.pack(padx=2, pady=2)

        tk.Label(
            frame, text="✦  SWU COLLECTION MANAGER  ✦",
            bg="#0b1d2a", fg="#e2b84b",
            font=("Arial", 12, "bold")
        ).pack(padx=28, pady=(18, 8))

        self._gallery_loading_label = tk.Label(
            frame,
            text="Le droïde archiviste recherche les cartes",
            bg="#0b1d2a", fg="#ffffff",
            font=("Arial", 11, "bold"),
            justify="center", wraplength=520
        )
        self._gallery_loading_label.pack(padx=28, pady=(18, 10))

        self._gallery_loading_detail = tk.Label(
            frame,
            text="Création des cellules en cours…",
            bg="#0b1d2a", fg="#91a8b5",
            font=("Arial", 9),
            justify="center", wraplength=520
        )
        self._gallery_loading_detail.pack(padx=28, pady=(0, 18))

        # Barre de progression globale : 50 % pour la création des cellules,
        # puis 50 % pour le chargement effectif des images. Elle reste affichée
        # jusqu\'au point exact où _gallery_ready passe à True.
        self._gallery_loading_bar = ttk.Progressbar(
            frame, orient="horizontal", mode="determinate",
            length=500, maximum=100, value=0
        )
        self._gallery_loading_bar.pack(padx=28, pady=(0, 8))

        self._gallery_loading_window = win
        # Le HUD de chargement est créé caché par _create_hud_toplevel.
        # Contrairement aux dialogues classiques, il n'a pas de déclencheur
        # de deiconify ultérieur : il faut donc l'afficher explicitement ici.
        win._hud_close_button.configure(command=lambda: None)
        try:
            win.update_idletasks()
            sw, sh = win.winfo_screenwidth(), win.winfo_screenheight()
            ww, wh = win.winfo_width(), win.winfo_height()
            win.geometry(f"{ww}x{wh}+{max(0, (sw-ww)//2)}+{max(0, (sh-wh)//2)}")
            win.deiconify()
            win.lift()
            # V400 : conserver le HUD au premier plan pendant TOUT le chargement.
            # Dans V399, le -topmost était retiré après 150 ms : la fenêtre
            # continuait d'exister (confirmé par le diagnostic) mais pouvait
            # repasser derrière la fenêtre principale, donnant l'impression
            # que la barre disparaissait immédiatement.
            try:
                win.attributes("-topmost", True)
            except Exception:
                pass
            win.update_idletasks()
        except Exception:
            pass

    def _gallery_loading_card_created(self):
        if not getattr(self, "_gallery_loading", False):
            return
        # Une seule incrémentation par carte.
        # _gallery_loading_step() effectue déjà l'incrémentation : ne pas
        # incrémenter _gallery_loading_created une seconde fois ici.
        self._gallery_loading_step()
        if self._gallery_loading_created >= self._gallery_loading_cards_total:
            self._gallery_loading_phase = "finalisation"
            try:
                total = int(getattr(self, "_gallery_loading_cards_total", 0) or 0)
                self._gallery_loading_label.configure(
                    text="Le droïde croupier distribue les cartes"
                )
                self._gallery_loading_detail.configure(
                    text="Affichage des images en cours…"
                )
            except Exception:
                pass

    def _gallery_loading_step(self, amount=1):
        """Met à jour la progression de construction de la galerie.

        La progression distingue volontairement la création des cellules et
        l'affichage effectif des images. Cela évite de considérer la galerie
        terminée simplement parce que les premières cartes visibles à l'écran
        ont fini leur rendu.
        """
        if not getattr(self, "_gallery_loading", False):
            return
        self._gallery_loading_created = min(
            int(getattr(self, "_gallery_loading_cards_total", 0) or 0),
            int(getattr(self, "_gallery_loading_created", 0) or 0) + max(1, int(amount or 1))
        )
        self._gallery_loading_update_progress()

    def _gallery_loading_update_progress(self):
        """Met à jour la progression réelle de construction et d'affichage."""
        if not getattr(self, "_gallery_loading", False):
            return
        total = max(1, int(getattr(self, "_gallery_loading_cards_total", 0) or 0))
        created = min(total, int(getattr(self, "_gallery_loading_created", 0) or 0))
        images_done = min(total, int(getattr(self, "_gallery_loading_images_done", 0) or 0))
        # Première moitié : cellules créées. Seconde moitié : images affichées.
        progress = (created / total) * 50.0 + (images_done / total) * 50.0
        try:
            if self._gallery_loading_bar is not None and self._gallery_loading_bar.winfo_exists():
                self._gallery_loading_bar.configure(value=progress)
            if self._gallery_loading_detail is not None:
                phase = "Création des cellules…" if created < total else "Affichage des images…"
                self._gallery_loading_detail.configure(
                    text=(f"{phase}  {created} / {total} cellules  •  "
                          f"{images_done} / {total} images  •  {int(progress)} %")
                )
                # Forcer uniquement le rafraîchissement visuel du HUD, sans
                # lancer une boucle update() générale susceptible de perturber
                # la construction progressive de la galerie.
                try:
                    self._gallery_loading_window.update_idletasks()
                except Exception:
                    pass
        except Exception:
            pass

    def _gallery_loading_finalize(self):
        """Termine le chargement uniquement lorsque l'affichage est réellement stabilisé.

        Le téléchargement d'une image et son affichage par Tkinter ne sont pas
        exactement synchrones. En Recherche, avec plusieurs centaines de cartes,
        le dernier callback image pouvait donc arriver alors que Tkinter avait
        encore beaucoup de géométrie et de rendu à traiter.

        On attend ici plusieurs contrôles successifs :
        - toutes les cartes ont été créées ;
        - tous les callbacks image du dernier lot sont revenus ;
        - le nombre de widgets de cartes correspond au nombre attendu ;
        - la géométrie du Canvas reste stable plusieurs fois de suite.
        Tant que ces conditions ne sont pas réunies, le verrouillage des clics et
        le HUD restent actifs.
        """
        if not getattr(self, "_gallery_loading", False):
            return

        self._gallery_loading_phase = "finalisation"
        try:
            self._gallery_loading_label.configure(text="Le droïde croupier distribue les cartes")
            self._gallery_loading_detail.configure(text="Affichage des images en cours…")
        except Exception:
            pass

        self._gallery_loading_stable_checks = 0
        self._gallery_loading_last_bbox = None

        def _wait_until_gallery_stable():
            if not getattr(self, "_gallery_loading", False):
                return

            try:
                self.root.update_idletasks()
            except Exception:
                pass

            created = int(getattr(self, "_gallery_loading_created", 0) or 0)
            expected = int(getattr(self, "_gallery_loading_cards_total", 0) or 0)
            done = int(getattr(self, "_gallery_loading_done", 0) or 0)
            total = int(getattr(self, "_gallery_loading_total", 0) or 0)
            pending = int(getattr(self, "_gallery_batch_pending", 0) or 0)
            batch_active = bool(getattr(self, "_gallery_batch_active", False))

            bbox = None
            try:
                bbox = tuple(self.canvas.bbox("all") or ())
            except Exception:
                bbox = None

            images_done = int(getattr(self, "_gallery_loading_images_done", 0) or 0)
            ready = (
                expected > 0
                and created >= expected
                and images_done >= expected
                and pending <= 0
                and not batch_active
            )

            if ready and bbox == getattr(self, "_gallery_loading_last_bbox", None):
                self._gallery_loading_stable_checks = int(
                    getattr(self, "_gallery_loading_stable_checks", 0) or 0
                ) + 1
            elif ready:
                self._gallery_loading_stable_checks = 1
            else:
                self._gallery_loading_stable_checks = 0

            self._gallery_loading_last_bbox = bbox

            if ready:
                try:
                    self._gallery_loading_detail.configure(
                        text=f"{expected} / {expected} cartes affichées"
                    )

                except Exception:
                    pass

            # Cinq contrôles espacés de 120 ms donnent environ 600 ms de géométrie
            # stable. Cela est volontairement plus strict pour Recherche, où les
            # dernières cartes peuvent encore apparaître après le dernier callback.
            if ready and self._gallery_loading_stable_checks >= 5:
                # Ne libère pas encore les clics ici : on laisse un dernier
                # cycle Tkinter se terminer, puis on valide explicitement la
                # galerie comme prête.
                generation = int(getattr(self, "_gallery_loading_generation", 0) or 0)
                self._gallery_loading_finish_job = self.root.after(180, lambda g=generation: self._mark_gallery_ready_and_finish(g))
                return

            self._gallery_loading_finish_job = self.root.after(120, _wait_until_gallery_stable)

        try:
            self._gallery_loading_finish_job = self.root.after_idle(_wait_until_gallery_stable)
        except Exception:
            self._stop_gallery_loading()

    def _mark_gallery_ready_and_finish(self, generation=None):
        """Valide la galerie seulement après la fin réelle du dernier lot."""
        if not getattr(self, "_gallery_loading", False):
            return
        current_generation = int(getattr(self, "_gallery_loading_generation", 0) or 0)
        if generation is not None and int(generation) != current_generation:
            return

        expected = int(getattr(self, "_gallery_loading_cards_total", 0) or 0)
        created = int(getattr(self, "_gallery_loading_created", 0) or 0)
        images_done = int(getattr(self, "_gallery_loading_images_done", 0) or 0)
        pending = int(getattr(self, "_gallery_batch_pending", 0) or 0)
        batch_active = bool(getattr(self, "_gallery_batch_active", False))

        if expected <= 0 or created < expected or images_done < expected or pending > 0 or batch_active:
            # Une condition n'est pas encore satisfaite : surtout ne pas
            # autoriser le clic. On reprend la vérification.
            try:
                self._gallery_loading_finish_job = self.root.after(120, lambda g=current_generation: self._mark_gallery_ready_and_finish(g))
            except Exception:
                pass
            return

        try:
            self.root.update_idletasks()
            self.canvas.update_idletasks()
        except Exception:
            pass

        # Le point de bascule unique : à partir d'ici seulement, les cellules
        # de la galerie peuvent ouvrir « Ma collection ».
        # Déverrouillage des cartes AVANT fermeture du HUD.
        # Ainsi, le HUD ne peut jamais disparaître alors que les cartes sont
        # encore bloquées. Le clic devient possible dès ce point précis.
        self._gallery_ready = True
        try:
            if self._gallery_loading_bar is not None and self._gallery_loading_bar.winfo_exists():
                self._gallery_loading_bar.configure(value=100)
        except Exception:
            pass
        # Le clic est maintenant réellement autorisé par _gallery_ready.
        # IMPORTANT : le HUD de chargement possède normalement le grab Tkinter,
        # ce qui empêcherait les cartes de recevoir le clic même si _gallery_ready
        # vaut True. On libère donc explicitement le grab AVANT de conserver
        # la barre visible. La barre reste affichée pendant que les cartes sont
        # déjà cliquables, puis disparaît après ce délai de sécurité.
        try:
            win = getattr(self, "_gallery_loading_window", None)
            if win is not None and win.winfo_exists():
                # La galerie est réellement prête : le HUD peut maintenant
                # cesser d'être topmost puis libérer le clic.
                try:
                    win.attributes("-topmost", False)
                except Exception:
                    pass
                win.grab_release()
                win._gallery_ready_for_click = True
        except Exception:
            pass
        try:
            self.root.update_idletasks()
        except Exception:
            pass
        # Toutes les progressions éventuellement créées par l'ancien pipeline
        # doivent elles aussi rester visibles jusqu'à ce point. On les ferme
        # seulement maintenant, après le déverrouillage effectif de la galerie.
        try:
            self._stop_bulk_progress()
        except Exception:
            pass

        # Laisser un cycle complet de messages Windows/Tkinter après la libération
        # du grab. La galerie est déjà cliquable pendant toute cette période.
        # On ne ferme le HUD qu'après avoir laissé Tkinter traiter plusieurs
        # cycles complets avec le clic déjà autorisé.
        def _close_when_click_is_really_released():
            if not getattr(self, "_gallery_ready", False):
                try:
                    self._gallery_loading_finish_job = self.root.after(120, _close_when_click_is_really_released)
                except Exception:
                    self._stop_gallery_loading()
                return
            try:
                self.root.update_idletasks()
            except Exception:
                pass
            try:
                self._gallery_loading_finish_job = self.root.after(1500, self._stop_gallery_loading)
            except Exception:
                self._stop_gallery_loading()
        try:
            self._gallery_loading_finish_job = self.root.after(50, _close_when_click_is_really_released)
        except Exception:
            self._stop_gallery_loading()

    def _stop_gallery_loading(self, force=False):
        # INVARIANT IMPORTANT : tant que la galerie n'est pas réellement prête,
        # aucun appel accidentel à cette méthode ne doit pouvoir faire disparaître
        # la barre. Le HUD reste donc affiché jusqu'au déverrouillage effectif.
        # Les reconstructions explicites (nouvelle galerie / clear_gallery)
        # utilisent force=True.
        if (not force
                and getattr(self, "_gallery_loading", False)
                and not getattr(self, "_gallery_ready", False)):
            return

        job = getattr(self, "_gallery_loading_finish_job", None)
        if job is not None:
            try:
                self.root.after_cancel(job)
            except Exception:
                pass
        self._gallery_loading_finish_job = None
        win = getattr(self, "_gallery_loading_window", None)
        if win is not None:
            try:
                if win.winfo_exists():
                    win.destroy()
            except Exception:
                pass
        self._gallery_loading_window = None
        self._gallery_loading_bar = None
        self._gallery_loading_label = None
        self._gallery_loading_detail = None
        self._gallery_loading = False
        self._gallery_loading_phase = ""
        self._gallery_loading_total = 0
        self._gallery_loading_done = 0
        self._gallery_loading_created = 0
        self._gallery_loading_images_done = 0
        self._gallery_loading_cards_total = 0
        self._gallery_loading_stable_checks = 0
        self._gallery_loading_last_bbox = None

    def _start_bulk_progress(self, total, title="Préparation de la galerie"):
        """Affiche une petite fenêtre centrale pour les gros chargements.

        Elle reste non modale afin de ne pas bloquer Tkinter. Les cartes sont
        ajoutées par petits lots et les images ne sont soumises au pool que
        lorsque le lot précédent est terminé : cela évite les files de
        milliers de tâches qui faisaient parfois planter le logiciel.
        """
        self._stop_bulk_progress()
        total = max(1, int(total or 0))
        self._bulk_progress_total = total
        self._bulk_progress_done = 0
        self._bulk_progress_phrase_index = 0

        win, win_body = self._create_hud_toplevel(self.root, "SWU Collection Manager")

        frame = tk.Frame(win_body, bg="#0b1d2a", bd=1, relief="solid",
                         highlightthickness=1, highlightbackground="#2f9bd1")
        frame.pack(padx=2, pady=2)

        tk.Label(frame, text="✦  SWU COLLECTION MANAGER  ✦",
                 bg="#0b1d2a", fg="#e2b84b",
                 font=("Arial", 12, "bold")).pack(padx=28, pady=(18, 8))
        self._bulk_progress_label = tk.Label(
            frame, text=title, bg="#0b1d2a", fg="#ffffff",
            font=("Arial", 11, "bold"), justify="center", wraplength=520
        )
        self._bulk_progress_label.pack(padx=28, pady=(0, 6))

        self._bulk_progress_detail = tk.Label(
            frame, text="Préparation des cartes…", bg="#0b1d2a", fg="#91a8b5",
            font=("Arial", 9), justify="center", wraplength=520
        )
        self._bulk_progress_detail.pack(padx=28, pady=(0, 10))

        self._bulk_progress_bar = ttk.Progressbar(
            frame, orient="horizontal", mode="determinate", length=500,
            maximum=total, value=0
        )
        self._bulk_progress_bar.pack(padx=28, pady=(0, 6))

        tk.Label(frame, text="Le droïde s'occupe de tout. Ne tirez pas sur le blaster.",
                 bg="#0b1d2a", fg="#6f8795",
                 font=("Arial", 8, "italic")).pack(padx=28, pady=(0, 16))

        win.update_idletasks()
        sw, sh = win.winfo_screenwidth(), win.winfo_screenheight()
        ww, wh = win.winfo_width(), win.winfo_height()
        x = max(0, (sw - ww) // 2)
        y = max(0, (sh - wh) // 2)
        win.geometry(f"{ww}x{wh}+{x}+{y}")
        win._hud_close_button.configure(command=lambda: None)
        self._bulk_progress_window = win
        self._cycle_bulk_progress_phrase()

    def _cycle_bulk_progress_phrase(self):
        if not self._bulk_progress_window or not self._bulk_progress_window.winfo_exists():
            return
        phrases = (
            "En train de coiffer le Wookie…",
            "Nettoyage du sabre laser…",
            "Rechargement du blaster…",
            "Réglage de l’hyperdrive…",
            "Dépoussiérage du droïde…",
            "Vérification des holocrons…",
            "Calibrage des senseurs…",
            "Ravitaillement du Faucon…",
            "Tri des cartes dans l’ordinateur central…",
            "Le droïde cherche la bonne carte…",
            "Réveil du droïde archiviste…",
            "Astiquage du casque de Stormtrooper…",
            "Recharge des cristaux kyber…",
            "Réglage des propulseurs ioniques…",
            "Déblocage du sas de stockage…",
            "Inspection des holocrons oubliés…",
            "Réorganisation du hangar à cartes…",
            "Le droïde a perdu une carte… il la retrouve…",
            "Alignement des cartes dans le rayon galactique…",
            "Vérification : aucune carte ne doit passer du côté obscur…",
            "Nettoyage des circuits du R2-D2 imaginaire…",
            "Chargement des données depuis une galaxie très lointaine…",
            "Le Faucon accélère pour livrer les miniatures…",
            "Consultation des archives de l’Empire…",
            "Le droïde pousse les cartes dans la bonne file…",
            "Contrôle du niveau de bacta… inutile, tout va bien…",
            "Recherche d’un stormtrooper qui sait viser…",
            "Graissage des articulations du droïde…",
            "Ouverture du coffre-fort de Jabba…",
            "Synchronisation des chasseurs stellaires…",
        )
        available = [p for p in phrases if p != self._bulk_progress_last_phrase]
        phrase = random.choice(available or phrases)
        self._bulk_progress_last_phrase = phrase
        self._bulk_progress_phrase_index += 1
        if self._bulk_progress_detail is not None:
            try:
                self._bulk_progress_detail.configure(
                    text=f"{phrase}\n{self._bulk_progress_done} / {self._bulk_progress_total}"
                )
            except tk.TclError:
                return
        try:
            self._bulk_progress_job = self.root.after(2500, self._cycle_bulk_progress_phrase)
        except Exception:
            pass

    def _bulk_progress_step(self, amount=1):
        if self._bulk_progress_total <= 0:
            return
        self._bulk_progress_done = min(
            self._bulk_progress_total,
            self._bulk_progress_done + max(1, int(amount or 1))
        )
        try:
            if self._bulk_progress_bar is not None:
                self._bulk_progress_bar.configure(value=self._bulk_progress_done)
            if self._bulk_progress_detail is not None:
                phrase = self._bulk_progress_last_phrase or "Le droïde prépare la prochaine escouade…"
                self._bulk_progress_detail.configure(
                    text=f"{phrase}\n{self._bulk_progress_done} / {self._bulk_progress_total}"
                )
        except tk.TclError:
            pass

    def _stop_bulk_progress(self):
        job = getattr(self, "_bulk_progress_job", None)
        if job is not None:
            try:
                self.root.after_cancel(job)
            except Exception:
                pass
        self._bulk_progress_job = None
        win = getattr(self, "_bulk_progress_window", None)
        if win is not None:
            try:
                win.destroy()
            except Exception:
                pass
        self._bulk_progress_window = None
        self._bulk_progress_bar = None
        self._bulk_progress_label = None
        self._bulk_progress_detail = None
        self._bulk_progress_total = 0
        self._bulk_progress_done = 0
        self._bulk_progress_last_phrase = None

    def _collection_batch_image_done(self, generation=None):
        """Compte une image seulement après son affichage Tkinter effectif.

        Les téléchargements peuvent être terminés alors que Tk n'a pas encore
        effectué le cycle de rendu correspondant. On attend donc un cycle
        ``after_idle`` avant de faire progresser la finalisation de la galerie.
        """
        if not self._gallery_batch_active or generation != self._gallery_batch_generation:
            return

        def _commit_image_done():
            if not self._gallery_batch_active or generation != self._gallery_batch_generation:
                return
            self._gallery_batch_pending = max(0, self._gallery_batch_pending - 1)
            if getattr(self, "_gallery_loading", False):
                self._gallery_loading_images_done = min(
                    int(getattr(self, "_gallery_loading_cards_total", 0) or 0),
                    int(getattr(self, "_gallery_loading_images_done", 0) or 0) + 1
                )
                self._gallery_loading_update_progress()
            self._bulk_progress_step()
            if self._gallery_batch_pending == 0:
                callback = self._gallery_batch_next
                self._gallery_batch_next = None
                if callback is not None:
                    # Laisser Tk terminer le rendu du lot avant d'en créer un autre.
                    self.root.after_idle(callback)
                else:
                    self._gallery_batch_active = False
                    # IMPORTANT : ne pas fermer la barre de progression ici.
                    # Le dernier lot d'images est terminé, mais la galerie n'est
                    # pas encore déclarée prête et les clics restent verrouillés.
                    # La fermeture des éventuelles progressions est centralisée
                    # dans _mark_gallery_ready_and_finish(), au tout dernier stade.
                    self.root.after_idle(self._gallery_loading_finalize)

        try:
            self.root.after_idle(_commit_image_done)
        except Exception:
            _commit_image_done()

    def _build_collection_version_filter(self, parent, rows, refresh_callback):
        """Construit le filtre des versions à partir des impressions du set."""
        bar = tk.Frame(parent, bg="#07131d")
        bar.pack(fill="x", pady=(0, 12))

        tk.Label(bar, text="VERSIONS", bg="#07131d", fg="#e2b84b",
                 font=("Arial", 9, "bold")).pack(side="left", padx=(0, 8))

        versions = []
        seen = set()
        for r in rows:
            vid = clean_text(r.get("variant_id")) or "01"
            name = clean_text(r.get("variant_name")) or vid
            if vid not in seen:
                seen.add(vid)
                versions.append((vid, name))
        versions.sort(key=lambda x: (min([clean_text(r.get("variant_sort")) for r in rows if clean_text(r.get("variant_id")) == x[0]] or ["9999"]), x[0]))

        default_version = "01" if any(v[0] == "01" for v in versions) else (versions[0][0] if versions else "01")
        var = tk.StringVar(value=default_version)
        self._collection_version_var = var
        buttons = {}

        def choose(value):
            var.set(value)
            for key, b in buttons.items():
                try:
                    b.configure(bg="#2f9bd1" if key == value else "#0d2634")
                except Exception:
                    pass
            refresh_callback(value)

        def add(value, label):
            b = tk.Button(bar, text=label, command=lambda v=value: choose(v),
                          bg="#2f9bd1" if value == "__ALL__" else "#0d2634",
                          fg="#e7f1f7", activebackground="#164b68", activeforeground="#fff",
                          relief="flat", bd=0, padx=10, pady=4, cursor="hand2")
            b.pack(side="left", padx=(0, 5))
            buttons[value] = b

        for vid, name in versions:
            add(vid, name)
        if default_version in buttons:
            buttons[default_version].configure(bg="#2f9bd1")
        self._collection_version_buttons = buttons
        return bar

    def _collection_variant_stock_counts(self, row, variant_id):
        """Retourne le stock de la variante en utilisant la même clé de
        collection que celle enregistrée par la boîte « Ma collection ».

        Point important : card_uid identifie une *impression* dans la base,
        alors que la boîte de stock enregistre les différentes versions
        (Standard, Foil, Hyperspace...) sous la carte de départ, généralement
        l'impression Standard. Il ne faut donc pas utiliser directement le
        card_uid de l'impression Foil/Hyperspace pour lire le JSON.
        """
        variant_id = str(variant_id)
        base_card = dict(row)

        # La clé utilisée pour le stock est celle de l'impression Standard
        # du même concept et de la même extension.
        concept_id = clean_text(row.get("concept_id") or row.get("card_concept_id"))
        expansion_code = clean_text(row.get("expansion_code")).upper()
        if self.db is not None and concept_id:
            try:
                standard = self.db.execute(
                    """
                    SELECT cp.card_uid
                    FROM card_printing cp
                    JOIN expansion e ON e.id = cp.expansion_id
                    JOIN variant_type vt ON vt.id = cp.variant_type_id
                    WHERE cp.card_concept_id = ?
                      AND e.code = ?
                      AND vt.variant_id = '01'
                    ORDER BY cp.id
                    LIMIT 1
                    """,
                    (concept_id, expansion_code)
                ).fetchone()
                if standard and standard[0]:
                    base_card["card_uid"] = standard[0]
            except Exception:
                pass

        # Pour les variantes spéciales rattachées à un autre conteneur,
        # on conserve le card_uid déjà porté par la ligne si aucun Standard
        # n'existe dans l'extension courante.
        return self._get_collection_counts(base_card, [variant_id])

    def _collection_standard_uid_for_row(self, row):
        """Retourne la clé de collection Standard du concept affiché."""
        concept_id = clean_text(row.get("concept_id") or row.get("card_concept_id"))
        expansion_code = clean_text(row.get("expansion_code")).upper()
        if self.db is not None and concept_id and expansion_code:
            try:
                r = self.db.execute(
                    """SELECT cp.card_uid
                       FROM card_printing cp
                       JOIN expansion e ON e.id = cp.expansion_id
                       JOIN variant_type vt ON vt.id = cp.variant_type_id
                       WHERE cp.card_concept_id = ? AND e.code = ? AND vt.variant_id = '01'
                       ORDER BY cp.id LIMIT 1""",
                    (concept_id, expansion_code)
                ).fetchone()
                if r and r[0]:
                    return clean_text(r[0])
            except Exception:
                pass
        return clean_text(row.get("card_uid"))

    def _collection_status_for_variant(self, row, mode, variant_id):
        """Teste le statut d'une impression précise (version)."""
        key = self._collection_standard_uid_for_row(row)
        raw = self.collection.get("cards", {}).get(key, {}) if isinstance(self.collection, dict) else {}
        if not isinstance(raw, dict):
            raw = {}
        vid = str(variant_id)
        if mode == "owned":
            counts = self._collection_variant_stock_counts(row, vid)
            return sum(
                max(0, int((counts.get(lang) or {}).get(vid, 0) or 0))
                for lang in LANGUAGES
            ) > 0
        if mode == "wanted":
            wanted = self.wanted_data.get("cards", {}).get(key, {}) if isinstance(getattr(self, "wanted_data", {}), dict) else {}
            return isinstance(wanted, dict) and bool(wanted.get(vid, False))
        if mode == "trade":
            counts = self._get_trade_counts({"card_uid": key}, [vid])
            return sum(
                max(0, int((counts.get(lang) or {}).get(vid, 0) or 0))
                for lang in LANGUAGES
            ) > 0
        return False

    def _reset_gallery_canvas_content(self):
        """Réinitialise complètement la fenêtre Canvas utilisée par la galerie.

        Un simple destroy() des cartes ne suffit pas toujours avec Tkinter :
        le Frame interne et la fenêtre Canvas peuvent conserver une géométrie
        calculée pour une galerie précédente. C'est notamment ce qui pouvait
        produire une grande zone vide au-dessus des cartes dans les
        récapitulatifs de set. On repart donc d'une fenêtre Canvas neuve avant
        chaque reconstruction de galerie.
        """
        try:
            old_window = getattr(self, "canvas_window", None)
            if old_window is not None:
                self.canvas.delete(old_window)
        except Exception:
            pass

        try:
            old_content = getattr(self, "content", None)
            if old_content is not None and old_content.winfo_exists():
                old_content.destroy()
        except Exception:
            pass

        self.content = tk.Frame(
            self.canvas, bg="#07131d", bd=0, highlightthickness=0
        )
        # Le contenu du Canvas est toujours ancré en haut à gauche.
        # Le binding Configure maintient le scrollregion synchronisé avec
        # la hauteur réelle de la galerie pendant l'arrivée des images.
        def _on_gallery_content_configure(_event=None):
            try:
                self.canvas.update_idletasks()
                natural_height = max(1, self.content.winfo_reqheight())
                viewport_height = max(1, self.canvas.winfo_height())
                # Le contenu garde sa hauteur naturelle. En revanche, la
                # zone de défilement ne peut jamais être plus petite que la
                # fenêtre visible : sinon Tkinter peut déplacer/centrer la
                # zone lorsque quelques cartes seulement sont affichées.
                self.canvas.configure(
                    scrollregion=(
                        0, 0,
                        max(1, self.canvas.winfo_width()),
                        max(viewport_height, natural_height)
                    )
                )
                if natural_height <= viewport_height:
                    self.canvas.yview_moveto(0.0)
            except Exception:
                pass

        self.content.bind("<Configure>", _on_gallery_content_configure)
        self.canvas_window = self.canvas.create_window(
            (0, 0), window=self.content, anchor="nw",
            width=max(1, self.canvas.winfo_width())
        )
        self.canvas.configure(scrollregion=(0, 0, max(1, self.canvas.winfo_width()), 1))
        self.canvas.yview_moveto(0.0)
        self.canvas.update_idletasks()

    def _refresh_collection_canvas_geometry(self):
        """Synchronise proprement la géométrie du Canvas avec le contenu réel."""
        try:
            self.canvas.update_idletasks()
            self.content.update_idletasks()
            canvas_width = max(1, self.canvas.winfo_width())
            content_width = max(canvas_width, self.content.winfo_reqwidth())
            content_height = max(1, self.content.winfo_reqheight())

            self.canvas.itemconfigure(
                self.canvas_window,
                x=0, y=0, anchor="nw",
                width=canvas_width,
                height=content_height,
            )
            viewport_height = max(1, self.canvas.winfo_height())
            # IMPORTANT : on ne donne jamais au window item la hauteur de la
            # fenêtre visible. Il conserve sa hauteur naturelle afin de ne
            # pas faire disparaître les cartes. Seule la scrollregion est
            # étendue à la hauteur visible lorsqu'il y a peu de cartes.
            scroll_height = max(viewport_height, content_height)
            self.canvas.configure(
                scrollregion=(0, 0, content_width, scroll_height)
            )
            if content_height <= viewport_height:
                self.canvas.yview_moveto(0.0)
        except Exception:
            pass

    def _display_collection_status_or_owned_gallery(self, gallery, rows, selected_version, mode=None, expansion_code=None):
        """Affiche le contenu de la galerie selon le statut, sans quitter le récapitulatif."""
        if mode not in ("owned", "wanted", "trade"):
            return self._display_collection_version_gallery(gallery, rows, selected_version)

        for widget in gallery.winfo_children():
            widget.destroy()
        selected = str(selected_version)
        candidates = rows if selected == "__ALL__" else [r for r in rows if clean_text(r.get("variant_id")) == selected]
        filtered = []
        for row in candidates:
            vid = clean_text(row.get("variant_id")) or "01"
            if self._collection_status_for_variant(row, mode, vid):
                item = dict(row)
                item["_collection_total"] = 1
                filtered.append(item)

        def numeric_number(value):
            try:
                return int(clean_text(value))
            except Exception:
                return 999999

        filtered.sort(key=lambda r: (
            1 if clean_text(r.get("type_code")).lower() == "token" else 0,
            numeric_number(r.get("card_number")),
            clean_text(r.get("card_number")),
            clean_text(r.get("variant_sort")),
            clean_text(r.get("printing_id")),
        ))

        if not filtered:
            labels = {"owned": "possédée", "wanted": "recherchée", "trade": "à échanger"}
            tk.Label(gallery, text=f"Aucune carte {labels.get(mode, 'dans cette catégorie')} dans cette version.",
                     bg="#07131d", fg="#91a8b5", font=("Arial", 11)).pack(pady=30)
            return

        width = max(self.canvas.winfo_width(), 900)
        columns = max(3, min(8, width // 175))
        for col in range(columns):
            gallery.grid_columnconfigure(col, weight=1)

        self.canvas.yview_moveto(0)
        self._refresh_collection_canvas_geometry()

        # Affichage séquentiel : jamais des centaines/milliers de tâches
        # image en attente dans le ThreadPoolExecutor.
        self._gallery_batch_active = True
        self._gallery_batch_pending = 0
        self._gallery_batch_next = None
        self._gallery_batch_generation += 1
        batch_generation = self._gallery_batch_generation
        if len(filtered) > self._gallery_batch_size:
            self._start_bulk_progress(len(filtered), "Préparation des cartes de collection…")

        def add_batch(offset):
            batch = filtered[offset:offset + self._gallery_batch_size]
            self._gallery_batch_pending = len(batch)
            if not batch:
                self._gallery_batch_active = False
                self._stop_bulk_progress()
                return
            for i, row in enumerate(batch):
                cell = self._collection_variant_card(
                    row, gallery, {}, image_done_callback=lambda g=batch_generation: self._collection_batch_image_done(g)
                )
                absolute = offset + i
                cell.grid(row=absolute // columns, column=absolute % columns,
                          padx=3, pady=3, sticky="n")
            self.canvas.yview_moveto(0.0)
            self.root.after_idle(lambda: (
                self._refresh_collection_canvas_geometry(),
                self.canvas.yview_moveto(0.0)
            ))
            if offset + len(batch) < len(filtered):
                self._gallery_batch_next = lambda n=offset + len(batch): add_batch(n)
            else:
                self._gallery_batch_next = None

        add_batch(0)

    def _display_collection_version_gallery(self, gallery, rows, selected_version="__ALL__"):
        """Affiche les cartes possédées avec EXACTEMENT la galerie RECHERCHE.

        La logique spécifique de construction des cellules Collection est
        volontairement supprimée ici. On conserve uniquement le filtrage
        propre à Collection (ne garder que les impressions réellement
        possédées et, si demandé, la version sélectionnée), puis on transmet
        les cartes à ``display_cards()``.

        Cela garantit que Collection et Recherche utilisent :
        - le même tri leaders/bases puis cartes classiques ;
        - le même nombre de colonnes ;
        - le même Canvas et la même géométrie ;
        - le même widget de carte ;
        - le même comportement de clic et de survol.

        La seule différence fonctionnelle reste donc le filtre préalable :
        Collection n'affiche que les cartes possédées.
        """
        # La galerie doit être vidée avant de laisser display_cards()
        # reconstruire exactement la même structure que Recherche.
        for widget in gallery.winfo_children():
            widget.destroy()

        selected = str(selected_version)
        candidates = rows if selected == "__ALL__" else [
            r for r in rows
            if clean_text(r.get("variant_id")) == selected
        ]

        filtered = []
        for row in candidates:
            vid = clean_text(row.get("variant_id")) or "01"
            counts = self._collection_variant_stock_counts(row, vid)
            total = 0
            for lang in LANGUAGES:
                try:
                    total += max(0, int((counts.get(lang) or {}).get(vid, 0) or 0))
                except Exception:
                    pass

            if total <= 0:
                continue

            item = dict(row)
            item["_collection_counts"] = counts
            item["_collection_total"] = total
            item["image_language_id"] = row.get("image_language_id") or LANGUAGES.get(self.language.get(), LANGUAGES["fr"])
            item["display_language_id"] = item["image_language_id"]
            item["variant_id"] = vid
            item["variant_name"] = clean_text(row.get("variant_name")) or vid
            item["title"] = clean_text(row.get("title")) or clean_text(row.get("card_number")) or clean_text(row.get("card_uid")) or "Carte"
            item["subtitle"] = ""
            filtered.append(item)

        if not filtered:
            message = (
                "Aucune carte possédée dans cette version."
                if selected != "__ALL__"
                else "Aucune carte possédée dans cette extension."
            )
            tk.Label(
                gallery, text=message, bg="#07131d", fg="#91a8b5",
                font=("Arial", 11)
            ).pack(pady=30)
            return

        # À partir de ce point, Collection ne possède plus de logique de
        # galerie propre : c'est exactement la galerie Recherche qui prend
        # le relais. display_cards() séparera notamment les leaders/bases
        # des cartes portrait, comme dans Recherche.
        self.display_cards(filtered)


    # ------------------------------------------------------------------
    # EXPORT EXCEL DE LA COLLECTION
    # ------------------------------------------------------------------

    def _export_main_extension_rows(self):
        """Retourne les extensions principales, comme celles de COLLECTION."""
        if self.db is None:
            return []
        lang_id = LANGUAGES.get(self.language.get(), LANGUAGES["fr"])
        rows = list(self.db.execute(
            """
            SELECT e.code, e.name AS fallback_name, e.sort_value,
                   COALESCE(el.name, el_en.name, e.name) AS localized_name
            FROM expansion e
            LEFT JOIN expansion_localization el
              ON el.expansion_id = e.id AND el.language_id = ?
            LEFT JOIN expansion_localization el_en
              ON el_en.expansion_id = e.id AND el_en.language_id = ?
            ORDER BY COALESCE(e.sort_value, 9999), e.code
            """,
            (lang_id, LANGUAGES["en"])
        ))

        def is_promo(row):
            code = clean_text(row["code"]).upper()
            name = clean_text(row["localized_name"] or row["fallback_name"]).lower()
            if code in {"WPL", "WEEKLYPLAY"}:
                return True
            return any(k in name for k in PROMO_EXTENSION_KEYWORDS)

        return [r for r in rows if not is_promo(r)]

    def _export_card_rows_for_extension(self, expansion_code):
        """Construit une ligne par concept de carte dans une extension."""
        lang_id = LANGUAGES.get(self.language.get(), LANGUAGES["fr"])
        en_id = LANGUAGES["en"]
        rows = self.db.execute(
            """
            SELECT cp.id AS printing_id,
                   cp.card_uid,
                   cp.card_number,
                   cp.card_concept_id AS concept_id,
                   cc.cost,
                   ct.code AS type_code,
                   e.code AS expansion_code,
                   COALESCE(cl.title, cl_en.title, cp.card_number, cp.card_uid) AS title,
                   vt.variant_id,
                   COALESCE(vtl.name, vtl_en.name, vt.variant_id) AS variant_name,
                   COALESCE(vtl.sort_value, vtl_en.sort_value, 9999) AS variant_sort
            FROM card_printing cp
            JOIN card_concept cc ON cc.id = cp.card_concept_id
            LEFT JOIN card_type ct ON ct.id = cc.type_id
            JOIN expansion e ON e.id = cp.expansion_id
            JOIN variant_type vt ON vt.id = cp.variant_type_id
            LEFT JOIN card_localization cl
              ON cl.card_concept_id = cc.id AND cl.language_id = ?
            LEFT JOIN card_localization cl_en
              ON cl_en.card_concept_id = cc.id AND cl_en.language_id = ?
            LEFT JOIN variant_type_localization vtl
              ON vtl.variant_type_id = vt.id AND vtl.language_id = ?
            LEFT JOIN variant_type_localization vtl_en
              ON vtl_en.variant_type_id = vt.id AND vtl_en.language_id = ?
            WHERE e.code = ?
            ORDER BY cp.card_concept_id,
                     CASE WHEN vt.variant_id = '01' THEN 0 ELSE 1 END,
                     COALESCE(vtl.sort_value, vtl_en.sort_value, 9999),
                     cp.id
            """,
            (lang_id, en_id, lang_id, en_id, expansion_code)
        ).fetchall()

        grouped = {}
        for r in rows:
            cid = clean_text(r["concept_id"])
            if not cid:
                continue
            item = grouped.setdefault(cid, {
                "id": cid,
                "number": clean_text(r["card_number"]),
                "title": clean_text(r["title"]),
                "type": clean_text(r["type_code"]),
                "standard_uid": "",
                "variants": {},
            })
            # Le numéro et le nom proviennent prioritairement de l'impression
            # Standard de l'extension.
            if clean_text(r["variant_id"]) == "01":
                item["number"] = clean_text(r["card_number"]) or item["number"]
                item["title"] = clean_text(r["title"]) or item["title"]
                item["standard_uid"] = clean_text(r["card_uid"])
            vid = clean_text(r["variant_id"])
            if vid:
                item["variants"].setdefault(vid, {
                    "name": clean_text(r["variant_name"]) or vid,
                    "sort": r["variant_sort"] if r["variant_sort"] is not None else 9999,
                    "printing_ids": [],
                })["printing_ids"].append(clean_text(r["printing_id"]))

        # Certaines cartes spéciales n'ont pas de Standard dans l'extension.
        # Leur première impression reste la clé de secours historique du stock.
        for item in grouped.values():
            if not item["standard_uid"]:
                for v in item["variants"].values():
                    if v["printing_ids"]:
                        row = self.db.execute(
                            "SELECT card_uid FROM card_printing WHERE id = ? LIMIT 1",
                            (v["printing_ids"][0],)
                        ).fetchone()
                        if row and row[0]:
                            item["standard_uid"] = clean_text(row[0])
                            break
        return list(grouped.values())

    def _export_variant_languages(self, concept_id, expansion_code, variant_id, printing_ids):
        """Réutilise la même logique de disponibilité des langues que COLLECTION."""
        variant_id = str(variant_id)
        normal = variant_id in {"01", "02", "03", "31", "32", "35", "60"}
        if normal:
            rows = self.db.execute(
                """
                SELECT DISTINCT l.code
                FROM card_localization cl
                JOIN language l ON l.id = cl.language_id
                WHERE cl.card_concept_id = ?
                  AND l.code IN ('fr','en','de','it','es')
                """, (concept_id,)
            ).fetchall()
            found = {clean_text(r["code"]).lower() for r in rows if r and r["code"]}
            return found & set(LANGUAGES.keys()) or set(LANGUAGES.keys())

        # Prestige / Carbonite : anglais uniquement, comme dans la gestion de stock.
        vt = self.db.execute(
            """
            SELECT COALESCE(vtl_en.name, vt.variant_id) AS name
            FROM variant_type vt
            LEFT JOIN variant_type_localization vtl_en
              ON vtl_en.variant_type_id = vt.id AND vtl_en.language_id = ?
            WHERE vt.variant_id = ? LIMIT 1
            """, (LANGUAGES["en"], variant_id)
        ).fetchone()
        vname = clean_text(vt["name"]).lower() if vt else ""
        if "prestige" in vname or variant_id in {"06", "33", "34"}:
            return {"en"}

        if variant_id in {"40", "41", "42", "43", "44", "45"}:
            rows = self.db.execute(
                """
                SELECT DISTINCT l.code
                FROM card_localization cl
                JOIN language l ON l.id = cl.language_id
                WHERE cl.card_concept_id = ?
                  AND l.code IN ('fr','en','de','it','es')
                """, (concept_id,)
            ).fetchall()
            found = {clean_text(r["code"]).lower() for r in rows if r and r["code"]}
            if found:
                return found & set(LANGUAGES.keys())

        ids = [x for x in printing_ids if x]
        if not ids:
            return set()
        placeholders = ",".join("?" for _ in ids)
        rows = self.db.execute(
            f"""
            SELECT DISTINCT l.code
            FROM card_image ci
            JOIN language l ON l.id = ci.language_id
            WHERE ci.card_printing_id IN ({placeholders})
              AND ci.image_role = 'front'
              AND l.code IN ('fr','en','de','it','es')
            """, ids
        ).fetchall()
        return {clean_text(r["code"]).lower() for r in rows if r and r["code"]} & set(LANGUAGES.keys())

    def _export_cloud_folder(self, kind):
        """Demande où enregistrer localement un export destiné au cloud.

        Google Drive et OneDrive ne sont volontairement pas recherchés sur
        l'ordinateur : le fichier est d'abord créé dans le dossier choisi
        par l'utilisateur, puis le service cloud correspondant est ouvert
        dans le navigateur pour permettre la connexion et le dépôt manuel.
        """
        labels = {
            "Google Drive": "Google Drive",
            "OneDrive": "OneDrive",
        }
        service_name = labels.get(kind, kind)
        try:
            return filedialog.askdirectory(
                parent=self.root,
                title=f"Choisir le dossier où enregistrer la collection avant de l'envoyer sur {service_name}"
            ) or None
        except Exception:
            return None

    def _open_export_folder_and_cloud(self, folder, cloud_kind):
        """Ouvre le dossier local ET le service cloud correspondant.

        Le fichier reste volontairement local : aucun dossier Drive/OneDrive
        synchronisé n'est utilisé. Le navigateur est ouvert explicitement
        vers le service choisi afin que l'utilisateur puisse se connecter et
        déposer manuellement le fichier exporté.
        """
        urls = {
            "Google Drive": "https://drive.google.com/drive/my-drive",
            "OneDrive": "https://onedrive.live.com/",
        }

        # 1) Ouvrir le dossier local contenant le fichier.
        try:
            if os.name == "nt":
                os.startfile(str(folder))
            else:
                subprocess.Popen(["xdg-open", str(folder)])
        except Exception:
            pass

        # 2) Ouvrir le service cloud dans le navigateur.
        url = urls.get(cloud_kind)
        if not url:
            return
        try:
            opened = webbrowser.open_new_tab(url)
            if not opened:
                # Fallback Windows : demande directement au système d'ouvrir l'URL.
                if os.name == "nt":
                    os.startfile(url)
        except Exception:
            try:
                if os.name == "nt":
                    os.startfile(url)
            except Exception:
                pass


    @staticmethod
    def _ensure_xlsxwriter():
        """Charge XlsxWriter embarqué, sans dépendance à installer."""
        global xlsxwriter
        if xlsxwriter is not None:
            return xlsxwriter
        try:
            return _load_embedded_xlsxwriter()
        except Exception as exc:
            raise RuntimeError(
                "Impossible de charger le module XlsxWriter embarqué.\n\n"
                f"Détail : {exc}"
            ) from exc

    def _build_collection_workbook(self, target_path):
        """Construit directement l'export XLSX avec XlsxWriter."""
        writer = self._ensure_xlsxwriter()

        target_path = Path(target_path)
        workbook = writer.Workbook(str(target_path))
        try:
            border_fmt = {"border": 1, "border_color": "4B6270"}
            header_fmt = workbook.add_format({
                "bold": True, "font_color": "#FFFFFF", "bg_color": "#0B2635",
                "border": 1, "border_color": "4B6270", "align": "center",
                "valign": "vcenter", "text_wrap": True, "locked": True,
            })
            meta_fmt = workbook.add_format({**border_fmt, "valign": "vcenter", "locked": True})
            meta_alt_fmt = workbook.add_format({**border_fmt, "bg_color": "#EAF1F5", "valign": "vcenter", "locked": True})
            qty_valid_fmt = workbook.add_format({**border_fmt, "bg_color": "#FFFFFF", "align": "center", "valign": "vcenter", "locked": False})
            qty_valid_alt_fmt = workbook.add_format({**border_fmt, "bg_color": "#EAF1F5", "align": "center", "valign": "vcenter", "locked": False})
            qty_invalid_fmt = workbook.add_format({**border_fmt, "bg_color": "#D0D5D8", "align": "center", "valign": "vcenter", "locked": True})

            lang_codes = ("fr", "en", "de", "it", "es")
            lang_short = {"fr": "FR", "en": "EN", "de": "DE", "it": "IT", "es": "ES"}
            extensions = self._export_main_extension_rows()
            if not extensions:
                raise RuntimeError("Aucune extension principale n'est disponible dans la base.")

            created_sheets = 0
            for ext in extensions:
                code = clean_text(ext["code"]).upper()
                rows = self._export_card_rows_for_extension(code)
                if not rows:
                    continue

                variants = {}
                for item in rows:
                    for vid, v in item["variants"].items():
                        prev = variants.get(vid)
                        if prev is None or (v["sort"], vid) < (prev["sort"], vid):
                            variants[vid] = v
                variant_order = sorted(
                    variants,
                    key=lambda vid: (variants[vid]["sort"], int(vid) if vid.isdigit() else 9999, vid),
                )

                sheet_name = re.sub(r'[\\/*?:\[\]]', '_', code)[:31] or "SET"
                ws = workbook.add_worksheet(sheet_name)
                created_sheets += 1

                headers = ["ID technique", "Set", "N°", "Carte", "Type"]
                for vid in variant_order:
                    vname = variants[vid]["name"] or vid
                    for lc in lang_codes:
                        headers.append(f"{vname} / {lang_short[lc]}")
                for col, value in enumerate(headers):
                    ws.write(0, col, value, header_fmt)

                ws.set_column(0, 0, 18, None, {"hidden": True})
                ws.set_column(1, 1, 10)
                ws.set_column(2, 2, 8)
                ws.set_column(3, 3, 32)
                ws.set_column(4, 4, 14)
                if len(headers) > 5:
                    ws.set_column(5, len(headers) - 1, 16)
                ws.set_row(0, 32)
                ws.freeze_panes(1, 5)
                ws.hide_gridlines(2)

                sorted_rows = sorted(
                    rows,
                    key=lambda x: (int(x["number"]) if x["number"].isdigit() else 999999, x["number"], x["id"]),
                )
                for row_index, item in enumerate(sorted_rows, start=1):
                    alt = (row_index % 2 == 0)
                    meta_fmt_row = meta_alt_fmt if alt else meta_fmt
                    excel_row = row_index
                    ws.write(excel_row, 0, item["id"], meta_fmt_row)
                    ws.write(excel_row, 1, code, meta_fmt_row)
                    ws.write(excel_row, 2, item["number"], meta_fmt_row)
                    ws.write(excel_row, 3, item["title"], meta_fmt_row)
                    ws.write(excel_row, 4, item["type"], meta_fmt_row)

                    stock = self._get_collection_counts({"card_uid": item["standard_uid"]}, variant_order)
                    col = 5
                    for vid in variant_order:
                        v = item["variants"].get(vid)
                        available = set()
                        if v:
                            available = self._export_variant_languages(item["id"], code, vid, v["printing_ids"])
                        for lc in lang_codes:
                            if not v or lc not in available:
                                ws.write_blank(excel_row, col, None, qty_invalid_fmt)
                            else:
                                try:
                                    value = max(0, int((stock.get(lc) or {}).get(vid, 0) or 0))
                                except (TypeError, ValueError):
                                    value = 0
                                qty_fmt = qty_valid_alt_fmt if alt else qty_valid_fmt
                                ws.write_number(excel_row, col, value, qty_fmt)
                            col += 1

                ws.add_table(0, 0, len(sorted_rows), len(headers) - 1, {
                    "name": f"Table_{re.sub(r'[^A-Za-z0-9_]', '_', code)}",
                    "style": "Table Style Medium 2",
                    "columns": [{"header": h} for h in headers],
                })

                ws.protect("SWUCM", {
                    "select_locked_cells": False,
                    "select_unlocked_cells": True,
                    "format_cells": False,
                    "format_columns": False,
                    "format_rows": False,
                    "insert_columns": False,
                    "insert_rows": False,
                    "delete_columns": False,
                    "delete_rows": False,
                    "insert_hyperlinks": False,
                    "sort": True,
                    "autofilter": True,
                    "pivot_tables": False,
                    "objects": False,
                    "scenarios": False,
                })

            if created_sheets == 0:
                raise RuntimeError("Aucune donnée de carte n'a pu être exportée.")
        finally:
            workbook.close()
        return target_path

    @staticmethod
    def _verify_and_finalize_export_protection(path):
        """Vérifie le XLSX XlsxWriter sans le réécrire avec openpyxl."""
        if load_workbook is None:
            raise RuntimeError("openpyxl est nécessaire pour vérifier l'export Excel.")
        path = Path(path)
        wb = load_workbook(path, read_only=False)
        total_unlocked = 0
        try:
            for ws in wb.worksheets:
                if not ws.protection.sheet:
                    raise RuntimeError(f"La feuille '{ws.title}' n'est pas protégée.")
                for row in ws.iter_rows():
                    for cell in row:
                        if not cell.protection.locked:
                            if cell.row == 1 or cell.column <= 5:
                                raise RuntimeError(
                                    f"Protection Excel invalide : {ws.title}!{cell.coordinate} est déverrouillée."
                                )
                            total_unlocked += 1
        finally:
            wb.close()
        if total_unlocked == 0:
            raise RuntimeError("Aucune cellule de quantité modifiable n'a été détectée dans l'export.")
        return total_unlocked

    @staticmethod
    def _normalize_import_header(value):
        """Normalise un libellé Excel pour faciliter la comparaison."""
        text = clean_text(value)
        text = unicodedata.normalize("NFKD", text)
        text = "".join(ch for ch in text if not unicodedata.combining(ch))
        return re.sub(r"\s+", " ", text).strip().casefold()

    def _import_variant_aliases(self):
        """Construit la table nom de variante -> variant_id à partir de SQLite.

        L'export peut avoir été réalisé dans n'importe quelle langue. On charge
        donc toutes les traductions connues de chaque variante, et pas seulement
        la langue actuellement sélectionnée dans le logiciel.
        """
        aliases = {}
        if self.db is None:
            return aliases

        rows = self.db.execute(
            """
            SELECT vt.variant_id,
                   vt.variant_id AS raw_variant_id,
                   vtl.name AS localized_name
            FROM variant_type vt
            LEFT JOIN variant_type_localization vtl
              ON vtl.variant_type_id = vt.id
            ORDER BY vt.id, vtl.language_id
            """
        ).fetchall()

        for row in rows:
            vid = clean_text(row["variant_id"])
            if not vid:
                continue
            candidates = {vid, clean_text(row["localized_name"])}
            for candidate in candidates:
                key = self._normalize_import_header(candidate)
                if not key:
                    continue
                # Une même traduction peut exceptionnellement être utilisée
                # par plusieurs variantes. Dans ce cas on ne choisit pas
                # arbitrairement : l'import signalera la colonne ambiguë.
                previous = aliases.get(key)
                if previous is None:
                    aliases[key] = vid
                elif previous != vid:
                    aliases[key] = None
        return aliases

    def _ask_import_existing_action(self, parent=None):
        """Demande explicitement comment traiter la collection existante."""
        parent = parent or self.root
        dialog, body = self._create_hud_toplevel(parent, "Importer une collection")
        result = {"action": None}

        tk.Label(
            body,
            text="UNE COLLECTION EXISTE DÉJÀ",
            bg="#07131d", fg="#e2b84b",
            font=("Arial", 15, "bold")
        ).pack(pady=(20, 8))
        tk.Label(
            body,
            text="Que veux-tu faire avec la collection actuellement enregistrée ?",
            bg="#07131d", fg="#e7f1f7",
            font=("Arial", 10), justify="center", wraplength=560
        ).pack(padx=24, pady=(0, 18))

        actions = tk.Frame(body, bg="#07131d")
        actions.pack(fill="x", padx=22, pady=(0, 18))
        actions.columnconfigure(0, weight=1)
        actions.columnconfigure(1, weight=1)
        actions.columnconfigure(2, weight=1)

        def finish(action):
            result["action"] = action
            try:
                dialog.grab_release()
            except Exception:
                pass
            dialog.destroy()

        choices = [
            ("ÉCRASER", "overwrite", "#245c4b"),
            ("SAUVEGARDER\nPUIS IMPORTER", "backup", "#164b68"),
            ("ANNULER", "cancel", "#263b34"),
        ]
        for col, (label, action, bg) in enumerate(choices):
            hud = HUDFrame(actions, bg="#07131d")
            hud.grid(row=0, column=col, sticky="nsew", padx=4)
            tk.Button(
                hud, text=label, command=lambda a=action: finish(a),
                bg=bg, fg="#ffffff", activebackground="#2f9bd1",
                activeforeground="#ffffff", font=("Arial", 9, "bold"),
                relief="flat", bd=0, highlightthickness=0,
                cursor="hand2", padx=7, pady=10
            ).pack(fill="both", expand=True, padx=5, pady=5)

        dialog._hud_close_button.configure(command=lambda: finish("cancel"))
        dialog.bind("<Escape>", lambda _e: finish("cancel"))
        self._center_toplevel(dialog, 650, 245)
        dialog.deiconify()
        dialog.lift()
        dialog.grab_set()
        dialog.wait_visibility()
        parent.wait_window(dialog)
        return result["action"] or "cancel"

    def _read_collection_export_xlsx(self, source_path, progress_callback=None):
        """Lit un export Excel SWU Collection Manager et le convertit en JSON.

        Version optimisée :
        - lecture openpyxl en ``read_only`` avec ``iter_rows(values_only=True)`` ;
        - aucune lecture cellule par cellule ;
        - correspondances SQLite préchargées une seule fois ;
        - seules les colonnes de quantité identifiées sont inspectées ;
        - progression rafraîchie par blocs pour limiter le coût Tkinter.

        La fonction est exécutée dans le thread d'import et ne touche jamais
        directement à Tkinter.
        """
        if load_workbook is None:
            raise RuntimeError(
                "Le module openpyxl est nécessaire pour importer une collection.\n\n"
                "Installe-le avec : pip install openpyxl"
            )

        source_path = Path(source_path)
        if source_path.suffix.lower() not in {".xlsx", ".xlsm"}:
            raise ValueError(
                "Le fichier sélectionné n'est pas un fichier Excel compatible (.xlsx ou .xlsm)."
            )

        def report(percent, detail):
            if progress_callback is not None:
                try:
                    progress_callback(max(0, min(100, int(percent))), str(detail))
                except Exception:
                    pass

        aliases = self._import_variant_aliases()
        if not aliases:
            raise RuntimeError(
                "Impossible de lire les variantes de cartes dans la base de données."
            )

        wb = None
        worker_db = None
        imported_cards = {}
        invalid_rows = []
        ambiguous_columns = []
        quantity_cells = 0
        sheets_read = 0

        try:
            report(3, "Ouverture du fichier Excel…")
            wb = load_workbook(
                filename=str(source_path),
                read_only=True,
                data_only=True,
            )
            if not wb.sheetnames:
                raise ValueError("Le fichier Excel ne contient aucune feuille.")

            sheet_codes = [
                clean_text(name).upper()
                for name in wb.sheetnames
                if clean_text(name)
            ]
            if not sheet_codes:
                raise ValueError("Aucune feuille exploitable n'a été trouvée.")

            # Connexion SQLite dédiée au thread d'import.
            worker_db = sqlite3.connect(
                self.db_path,
                timeout=30,
                check_same_thread=False,
            )
            worker_db.row_factory = sqlite3.Row
            worker_db.execute("PRAGMA foreign_keys = ON")

            # Une seule requête pour toutes les extensions du classeur.
            placeholders = ",".join("?" for _ in sheet_codes)
            db_rows = worker_db.execute(
                f"""
                SELECT
                    e.code AS expansion_code,
                    cp.card_concept_id AS concept_id,
                    cp.card_uid,
                    cp.serial_code,
                    vt.variant_id,
                    COALESCE(cl.title, cl_en.title, cp.card_number, cp.card_uid) AS title
                FROM card_printing cp
                JOIN expansion e ON e.id = cp.expansion_id
                JOIN variant_type vt ON vt.id = cp.variant_type_id
                JOIN card_concept cc ON cc.id = cp.card_concept_id
                LEFT JOIN card_localization cl
                  ON cl.card_concept_id = cc.id
                 AND cl.language_id = ?
                LEFT JOIN card_localization cl_en
                  ON cl_en.card_concept_id = cc.id
                 AND cl_en.language_id = ?
                WHERE UPPER(e.code) IN ({placeholders})
                ORDER BY e.code, cp.card_concept_id,
                         CASE WHEN vt.variant_id = '01' THEN 0 ELSE 1 END,
                         cp.id
                """,
                (
                    LANGUAGES.get(self.language.get(), LANGUAGES["fr"]),
                    LANGUAGES["en"],
                    *sheet_codes,
                ),
            ).fetchall()

            concept_map = {}
            for row in db_rows:
                ext_code = clean_text(row["expansion_code"]).upper()
                concept_id = clean_text(row["concept_id"])
                if not ext_code or not concept_id:
                    continue

                key = (ext_code, concept_id)
                info = concept_map.setdefault(
                    key,
                    {
                        "standard_uid": "",
                        "serial_code": clean_text(row["serial_code"]),
                        "title": clean_text(row["title"]),
                        "variant_ids": set(),
                    },
                )

                vid = clean_text(row["variant_id"])
                if vid:
                    info["variant_ids"].add(vid)

                if vid == "01" and clean_text(row["card_uid"]):
                    info["standard_uid"] = clean_text(row["card_uid"])
                    if clean_text(row["serial_code"]):
                        info["serial_code"] = clean_text(row["serial_code"])
                    if clean_text(row["title"]):
                        info["title"] = clean_text(row["title"])

                # Certaines cartes spéciales n'ont pas de Standard.
                if not info["standard_uid"] and clean_text(row["card_uid"]):
                    info["standard_uid"] = clean_text(row["card_uid"])

            report(8, "Préparation de la correspondance avec la base…")

            # On calcule le nombre de lignes une seule fois. Cela permet une
            # progression stable sans reparcourir les feuilles pendant l'import.
            worksheet_infos = []
            total_rows = 0

            for ws in wb.worksheets:
                sheet_code = clean_text(ws.title).upper()
                if not sheet_code or ws.max_row < 2 or ws.max_column < 6:
                    continue

                # Lecture de la seule ligne d'en-tête.
                header_values = next(
                    ws.iter_rows(
                        min_row=1,
                        max_row=1,
                        min_col=1,
                        max_col=ws.max_column,
                        values_only=True,
                    ),
                    (),
                )

                quantity_columns = {}
                for col_index in range(5, len(header_values)):
                    header = clean_text(header_values[col_index])
                    if not header:
                        continue

                    parts = header.rsplit(" / ", 1)
                    if len(parts) != 2:
                        continue

                    variant_name, lang_short = parts[0].strip(), parts[1].strip().upper()
                    lang_code = {
                        "FR": "fr",
                        "EN": "en",
                        "DE": "de",
                        "IT": "it",
                        "ES": "es",
                    }.get(lang_short)
                    if not lang_code:
                        continue

                    vid = aliases.get(self._normalize_import_header(variant_name))
                    if vid is None:
                        ambiguous_columns.append(f"{ws.title}: {header}")
                        continue

                    # On conserve l'index zéro de la ligne retournée par
                    # iter_rows(), ce qui évite les appels ws.cell().
                    quantity_columns[col_index] = (vid, lang_code)

                if not quantity_columns:
                    continue

                row_count = max(0, ws.max_row - 1)
                worksheet_infos.append(
                    (ws, sheet_code, quantity_columns, row_count)
                )
                total_rows += row_count

            total_rows = max(1, total_rows)
            processed_rows = 0
            progress_span = 70

            for ws_index, (ws, sheet_code, quantity_columns, row_count) in enumerate(
                worksheet_infos, start=1
            ):
                sheets_read += 1
                report(
                    10 + int((processed_rows / total_rows) * progress_span),
                    f"Lecture de l'extension {sheet_code}…",
                )

                # On ne demande à openpyxl que les colonnes nécessaires :
                # ID technique (colonne A) + dernière colonne de quantité utile.
                max_needed_col = max(quantity_columns.keys()) + 1
                row_iter = ws.iter_rows(
                    min_row=2,
                    max_row=ws.max_row,
                    min_col=1,
                    max_col=max_needed_col,
                    values_only=True,
                )

                # Mise à jour de progression moins fréquente : Tkinter ne reçoit
                # qu'une mise à jour par bloc de 500 lignes.
                next_report = 0
                for row_values in row_iter:
                    technical_id = clean_text(row_values[0] if row_values else None)
                    if not technical_id:
                        processed_rows += 1
                        continue

                    concept_info = concept_map.get((sheet_code, technical_id))
                    if concept_info is None:
                        invalid_rows.append(
                            f"{ws.title} — ligne {processed_rows + 2} — ID {technical_id}"
                        )
                        processed_rows += 1
                        continue

                    standard_uid = clean_text(concept_info.get("standard_uid"))
                    if not standard_uid:
                        invalid_rows.append(
                            f"{ws.title} — ligne {processed_rows + 2} — ID {technical_id} (UID manquant)"
                        )
                        processed_rows += 1
                        continue

                    entry = imported_cards.setdefault(
                        standard_uid,
                        {
                            "languages": {},
                            "serial_code": clean_text(concept_info.get("serial_code")),
                            "last_title": clean_text(concept_info.get("title")),
                        },
                    )

                    valid_variant_ids = concept_info.get("variant_ids", set())

                    for col_index, (vid, lang_code) in quantity_columns.items():
                        if vid not in valid_variant_ids or col_index >= len(row_values):
                            continue

                        raw_value = row_values[col_index]
                        if raw_value in (None, ""):
                            continue

                        try:
                            quantity = max(0, min(999, int(float(raw_value))))
                        except (TypeError, ValueError):
                            continue

                        if quantity <= 0:
                            continue

                        entry["languages"].setdefault(lang_code, {})[vid] = quantity
                        quantity_cells += 1

                    processed_rows += 1

                    if processed_rows >= next_report:
                        pct = 20 + int((processed_rows / total_rows) * progress_span)
                        report(
                            min(90, pct),
                            f"Importation des quantités… {processed_rows:,} / {total_rows:,} lignes"
                            .replace(",", " "),
                        )
                        next_report = processed_rows + 500

            # Ne conserve pas les cartes dont aucune quantité positive n'a été
            # importée. Cela produit le même modèle compact que les collections
            # créées normalement par l'application.
            imported_cards = {
                key: value
                for key, value in imported_cards.items()
                if any(value.get("languages", {}).values())
            }

            report(95, "Vérification finale de la collection importée…")

            return {
                "version": 2,
                "cards": imported_cards,
                "_import_info": {
                    "source": source_path.name,
                    "sheets": sheets_read,
                    "cards": len(imported_cards),
                    "quantity_cells": quantity_cells,
                    "invalid_rows": invalid_rows,
                    "ambiguous_columns": ambiguous_columns,
                },
            }

        finally:
            if wb is not None:
                try:
                    wb.close()
                except Exception:
                    pass
            if worker_db is not None:
                try:
                    worker_db.close()
                except Exception:
                    pass

    def _write_collection_json(self, path, collection_data):
        """Écrit une collection JSON de façon atomique."""
        path = Path(path)
        path.parent.mkdir(parents=True, exist_ok=True)
        cards_source = collection_data.get("cards", {}) if isinstance(collection_data, dict) else {}
        cards_clean = {}
        if isinstance(cards_source, dict):
            for key, raw in cards_source.items():
                if not isinstance(raw, dict):
                    continue
                item = dict(raw)
                item.pop("trade", None)
                item.pop("wanted_versions", None)
                cards_clean[str(key)] = item
        payload = {
            "version": int(collection_data.get("version", 2) or 2),
            "cards": cards_clean,
        }
        temp = path.with_suffix(path.suffix + ".tmp")
        temp.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
        os.replace(temp, path)

    def _activate_imported_account(self, account):
        """Active immédiatement le compte importé dans l'interface courante."""
        self.account_pseudo = account["pseudo"]
        self._set_account_paths(self.account_pseudo, account.get("filename"))
        self.collection = self.load_collection()
        self._ensure_account_files()
        self.status.set(f"Collection de {self.account_pseudo} importée.")

        # Si la vue Collection est actuellement affichée, reconstruire son
        # contenu pour que les quantités importées soient visibles immédiatement.
        try:
            self.clear_gallery()
        except Exception:
            pass
        try:
            if getattr(self, "_recap_view", None) is not None and self._recap_view.winfo_ismapped():
                self.root.after_idle(lambda: self.open_collection_recap())
        except Exception:
            pass


    # ------------------------------------------------------------------
    # IMPORT EXTERNE SWUCARDEX (CSV)
    # ------------------------------------------------------------------

    @staticmethod
    def _normalize_external_text(value):
        """Normalise un texte du Cardex pour les correspondances SQLite."""
        value = clean_text(value)
        if not value:
            return ""
        value = unicodedata.normalize("NFKD", value)
        value = "".join(ch for ch in value if not unicodedata.combining(ch))
        value = value.lower().strip()
        value = value.replace("’", "'")
        value = re.sub(r"[^a-z0-9]+", " ", value)
        return re.sub(r"\s+", " ", value).strip()

    @staticmethod
    def _normalize_external_number(value):
        value = clean_text(value)
        if not value:
            return ""
        try:
            return str(int(float(value)))
        except Exception:
            return value.lstrip("0") or "0"

    def _external_type_matches(self, external_type, db_type):
        """Le type du CSV est indicatif ; Token peut désigner une vraie unité."""
        ext = self._normalize_external_text(external_type)
        db = self._normalize_external_text(db_type)
        aliases = {
            "unit": {"unit", "unite", "unité"},
            "event": {"event", "evenement", "événement"},
            "leader": {"leader"},
            "upgrade": {"upgrade", "amelioration", "amélioration"},
            "base": {"base"},
            "token": {"token", "jeton"},
        }
        if ext == "token":
            # Certains jetons du Cardex correspondent à une carte de type Unit
            # dans notre base (ex. C-3PO). On ne rejette donc jamais un candidat
            # uniquement parce que le CSV indique Token.
            return True
        for canonical, values in aliases.items():
            if ext in values:
                return db in values
        return ext == db

    def _external_variant_matches(self, external_variant, variant_id, variant_fr, variant_en):
        ext = self._normalize_external_text(external_variant)
        if not ext:
            return variant_id == "01"

        # Cardex : « Normal » correspond à l'impression Standard.
        if ext in {"normal", "standard"}:
            return variant_id == "01"

        names = {
            self._normalize_external_text(variant_fr),
            self._normalize_external_text(variant_en),
        }
        names.discard("")
        if ext in names:
            return True

        # Quelques libellés du Cardex sont en français alors que la base
        # conserve le libellé anglais.
        aliases = {
            "exclusivite de l evenement": {"event exclusive", "convention exclusive"},
            "exclusivite evenement": {"event exclusive", "convention exclusive"},
        }
        return any(
            self._normalize_external_text(alias) in names
            for alias in aliases.get(ext, set())
        )

    def _load_external_import_index(self):
        """Charge en mémoire les impressions utiles à l'appariement du CSV."""
        rows = self.db.execute(
            """
            SELECT
                cp.id AS printing_id,
                cp.card_uid AS printing_uid,
                cp.card_number,
                cp.card_concept_id AS concept_id,
                e.code AS expansion_code,
                COALESCE(ct.code, '') AS type_code,
                vt.variant_id,
                COALESCE(vtl_fr.name, '') AS variant_fr,
                COALESCE(vtl_en.name, '') AS variant_en,
                COALESCE(cl_fr.title, '') AS title_fr,
                COALESCE(cl_en.title, '') AS title_en,
                COALESCE(
                    (
                        SELECT cp_std.card_uid
                        FROM card_printing cp_std
                        WHERE cp_std.card_concept_id = cp.card_concept_id
                          AND cp_std.expansion_id = cp.expansion_id
                          AND cp_std.variant_type_id = (
                              SELECT vt_std.id
                              FROM variant_type vt_std
                              WHERE vt_std.variant_id = '01'
                              LIMIT 1
                          )
                        ORDER BY cp_std.id
                        LIMIT 1
                    ),
                    cp.card_uid
                ) AS standard_uid,
                COALESCE(
                    (
                        SELECT GROUP_CONCAT(DISTINCT l.code)
                        FROM card_localization cl_any
                        JOIN language l ON l.id = cl_any.language_id
                        WHERE cl_any.card_concept_id = cp.card_concept_id
                          AND l.code IN ('fr','en','de','it','es')
                    ),
                    ''
                ) AS available_languages
            FROM card_printing cp
            JOIN expansion e ON e.id = cp.expansion_id
            JOIN card_concept cc ON cc.id = cp.card_concept_id
            LEFT JOIN card_type ct ON ct.id = cc.type_id
            JOIN variant_type vt ON vt.id = cp.variant_type_id
            LEFT JOIN variant_type_localization vtl_fr
              ON vtl_fr.variant_type_id = vt.id
             AND vtl_fr.language_id = ?
            LEFT JOIN variant_type_localization vtl_en
              ON vtl_en.variant_type_id = vt.id
             AND vtl_en.language_id = ?
            LEFT JOIN card_localization cl_fr
              ON cl_fr.card_concept_id = cc.id
             AND cl_fr.language_id = ?
            LEFT JOIN card_localization cl_en
              ON cl_en.card_concept_id = cc.id
             AND cl_en.language_id = ?
            """,
            (LANGUAGES["fr"], LANGUAGES["en"], LANGUAGES["fr"], LANGUAGES["en"]),
        ).fetchall()

        index = {}
        for row in rows:
            code = clean_text(row["expansion_code"]).upper()
            number = self._normalize_external_number(row["card_number"])
            if not code or not number:
                continue
            index.setdefault((code, number), []).append(dict(row))
        return index

    def _match_external_card(self, csv_row, index):
        """Retourne la meilleure impression DB pour une ligne Cardex."""
        expansion = clean_text(csv_row.get("Set")).upper()
        number = self._normalize_external_number(csv_row.get("Number"))
        name = self._normalize_external_text(csv_row.get("Name"))
        ext_type = csv_row.get("Type")
        ext_variant = csv_row.get("VariantType")

        # 1) Chemin nominal : extension + numéro.
        candidates = list(index.get((expansion, number), []))
        number_fallback = not bool(candidates)

        # 2) Certains produits promotionnels ont un numéro externe différent
        # de celui de l'impression en base (ex. P25/P26). On retombe alors
        # sur extension + nom.
        if not candidates:
            seen = set()
            for (code, _num), rows_for_key in index.items():
                if code != expansion:
                    continue
                for candidate in rows_for_key:
                    cid = clean_text(candidate.get("concept_id"))
                    if cid and cid not in seen:
                        seen.add(cid)
                        candidates.append(candidate)

        scored = []
        for candidate in candidates:
            names = {
                self._normalize_external_text(candidate.get("title_fr")),
                self._normalize_external_text(candidate.get("title_en")),
            }
            names.discard("")
            name_score = 0
            if name and name in names:
                name_score = 100
            elif name and any(name in x or x in name for x in names):
                name_score = 60
            elif name and any(
                SequenceMatcher(None, name, x).ratio() >= 0.84
                for x in names
            ):
                # Tolère les petites différences de saisie (« Dark Maul » /
                # « Darth Maul ») sans abandonner l'appariement.
                name_score = 55

            if name_score == 0:
                continue

            variant_match = self._external_variant_matches(
                ext_variant,
                clean_text(candidate.get("variant_id")),
                candidate.get("variant_fr"),
                candidate.get("variant_en"),
            )
            variant_score = 35 if variant_match else 0

            type_score = 20 if self._external_type_matches(
                ext_type, candidate.get("type_code")
            ) else -20

            # Pour « Normal », la variante 01 est prioritaire. Si cette
            # impression n'existe pas dans l'extension promotionnelle,
            # l'unique variante du concept reste admissible.
            if clean_text(candidate.get("variant_id")) == "01" and (
                self._normalize_external_text(ext_variant) in {"", "normal", "standard"}
            ):
                variant_score += 5

            number_score = 0
            if number_fallback:
                try:
                    distance = abs(int(number) - int(candidate.get("card_number")))
                    number_score = max(0, 25 - min(distance, 25))
                except Exception:
                    pass

            score = name_score + variant_score + type_score + number_score
            scored.append((score, candidate))

        if not scored:
            return None, "nom_type_variant"

        scored.sort(key=lambda item: item[0], reverse=True)
        best_score = scored[0][0]
        best = [item[1] for item in scored if item[0] == best_score]

        if len(best) > 1:
            # Si plusieurs impressions sont identiques, le même concept reste
            # exploitable : la variante réellement demandée départage ensuite.
            concepts = {clean_text(x.get("concept_id")) for x in best}
            if len(concepts) == 1:
                # Préfère la variante demandée ; sinon la première impression.
                exact_variant = [
                    x for x in best
                    if self._external_variant_matches(
                        ext_variant,
                        clean_text(x.get("variant_id")),
                        x.get("variant_fr"),
                        x.get("variant_en"),
                    )
                ]
                return (exact_variant[0] if exact_variant else best[0]), None
            return None, "ambigu"

        # Si aucun candidat n'a exactement la variante demandée mais qu'un seul
        # concept correspond au nom dans l'extension, on accepte sa variante.
        # Cela couvre notamment les entrées promotionnelles « Normal » dont
        # l'impression interne n'est pas 01.
        return scored[0][1], None

    def _ask_external_import_language(self):
        """Demande la langue cible avant l'analyse du fichier externe."""
        dialog, body = self._create_hud_toplevel(
            self.root, "Langue de la collection externe"
        )
        dialog.geometry("560x300")
        dialog.resizable(False, False)
        try:
            self.root.update_idletasks()
            ww, wh = self.root.winfo_width(), self.root.winfo_height()
            rw, rh = self.root.winfo_rootx(), self.root.winfo_rooty()
            dialog.geometry(f"560x300+{rw + max(0, (ww - 560)//2)}+{rh + max(0, (wh - 300)//2)}")
        except Exception:
            pass

        tk.Label(
            body,
            text="Dans quelle langue veux-tu enregistrer les quantités importées ?",
            bg="#07131d", fg="#e7f1f7",
            font=("Arial", 11, "bold"),
        ).pack(pady=(24, 8))

        tk.Label(
            body,
            text="Si la langue choisie n'existe pas pour une carte, "
                 "l'anglais sera utilisé automatiquement lorsqu'il est disponible.",
            bg="#07131d", fg="#91a8b5",
            font=("Arial", 9), wraplength=490, justify="center",
        ).pack(pady=(0, 18))

        result = {"value": None}
        grid = tk.Frame(body, bg="#07131d")
        grid.pack(fill="x", padx=24)

        def choose(code):
            result["value"] = code
            try:
                dialog.grab_release()
            except Exception:
                pass
            dialog.destroy()

        for idx, code in enumerate(("fr", "en", "de", "it", "es")):
            tk.Button(
                grid,
                text=LANGUAGE_LABELS.get(code, code.upper()),
                command=lambda c=code: choose(c),
                bg="#0d2634", fg="#ffffff",
                activebackground="#164b68", activeforeground="#ffffff",
                font=("Arial", 9, "bold"), relief="flat", bd=0,
                cursor="hand2", padx=10, pady=9,
            ).grid(row=idx // 3, column=idx % 3, padx=5, pady=5, sticky="ew")

        for c in range(3):
            grid.columnconfigure(c, weight=1)

        tk.Button(
            body, text="ANNULER", command=dialog.destroy,
            bg="#18232b", fg="#91a8b5",
            activebackground="#243641", activeforeground="#ffffff",
            font=("Arial", 8, "bold"), relief="flat", bd=0,
            cursor="hand2", padx=14, pady=6,
        ).pack(pady=(18, 8))

        dialog.protocol("WM_DELETE_WINDOW", dialog.destroy)

        # _create_hud_toplevel() crée volontairement le HUD en état withdrawn.
        # Ici, contrairement aux dialogues qui calculent leur géométrie puis
        # l'affichent explicitement, le dialogue de choix de langue était
        # directement passé à grab_set() sans jamais être déiconifié.
        # Sous Windows, il pouvait donc rester invisible jusqu'à ce qu'un
        # clic dans la fenêtre principale provoque un FocusIn et son affichage.
        # On rend maintenant le dialogue visible AVANT de prendre le grab.
        try:
            dialog.update_idletasks()
            dialog.deiconify()
            dialog.lift()
            dialog.wait_visibility()
            dialog.focus_force()
            dialog.grab_set()
        except Exception:
            pass
        self.root.wait_window(dialog)
        return result["value"]

    def _show_external_import_preview(self, result, source_path, language_code):
        """Présente le bilan avant toute modification de la collection."""
        info = result.get("_import_info", {})
        matched = int(info.get("matched_rows", 0) or 0)
        unmatched = int(info.get("unmatched_rows", 0) or 0)
        ambiguous = int(info.get("ambiguous_rows", 0) or 0)
        token_rows = int(info.get("token_rows", 0) or 0)
        fallback = int(info.get("language_fallback_rows", 0) or 0)
        quantity_total = int(info.get("quantity_total", 0) or 0)

        message = (
            f"Fichier : {Path(source_path).name}\n\n"
            f"Lignes analysées : {info.get('total_rows', 0):,}\n"
            f"Cartes reconnues : {matched:,}\n"
            f"Quantité totale à ajouter : {quantity_total:,}\n"
            f"Lignes de type Token rattachées à leur carte réelle : {token_rows:,}\n"
            f"Fallback vers l'anglais : {fallback:,}\n"
            f"Lignes non reconnues : {unmatched:,}\n"
            f"Lignes ambiguës : {ambiguous:,}\n\n"
            f"Langue cible : {LANGUAGE_LABELS.get(language_code, language_code)}\n\n"
            "La collection actuelle sera enrichie : aucune quantité existante "
            "ne sera remplacée."
        )
        if unmatched or ambiguous:
            message += (
                "\n\nLes lignes non reconnues ou ambiguës seront ignorées et "
                "listées dans le compte-rendu final."
            )

        return self._hud_messagebox(
            "askyesno",
            "Vérification de l'import externe",
            message,
            parent=self.root,
        )

    def import_external_collection_csv(self):
        """Importe un Cardex CSV en ajoutant les quantités à la collection."""
        if self.db is None:
            self._hud_messagebox(
                "error", "Import impossible",
                "La base de données n'est pas disponible.",
                parent=self.root,
            )
            return

        try:
            source = filedialog.askopenfilename(
                parent=self.root,
                title="Choisir le fichier de collection externe",
                filetypes=[
                    ("SWU Cardex CSV", "*.csv"),
                    ("Fichiers CSV", "*.csv"),
                    ("Tous les fichiers", "*.*"),
                ],
            )
        except Exception as exc:
            self._hud_messagebox(
                "error", "Import impossible",
                f"Impossible d'ouvrir le choix du fichier.\n\n{exc}",
                parent=self.root,
            )
            return
        if not source:
            return

        language_code = self._ask_external_import_language()
        if not language_code:
            return

        progress, pbody = self._create_hud_toplevel(
            self.root, "Import de collection externe"
        )
        progress.geometry("650x270")
        progress.update_idletasks()

        rw, rh = self.root.winfo_rootx(), self.root.winfo_rooty()
        ww, wh = self.root.winfo_width(), self.root.winfo_height()
        progress.geometry(
            f"650x270+{rw + max(0, (ww - 650)//2)}"
            f"+{rh + max(0, (wh - 270)//2)}"
        )

        msg = tk.StringVar(value="Le droïde analyse votre collection…")
        pct = tk.IntVar(value=2)

        tk.Label(
            pbody, textvariable=msg,
            bg="#07131d", fg="#e7f1f7",
            font=("Arial", 11, "bold"),
        ).pack(pady=(22, 12))

        bar_frame = tk.Frame(pbody, bg="#164b68", height=24)
        bar_frame.pack(fill="x", padx=30, pady=5)
        bar_frame.pack_propagate(False)
        bar = tk.Frame(bar_frame, bg="#2f9bd1", height=20)
        bar.place(x=2, y=2, relwidth=0.02, relheight=1)

        percent_label = tk.Label(
            pbody, text="2 %",
            bg="#07131d", fg="#e2b84b",
            font=("Arial", 10, "bold"),
        )
        percent_label.pack(pady=(5, 2))

        detail_label = tk.Label(
            pbody,
            text="Aucune donnée ne sera modifiée avant ta validation.",
            bg="#07131d", fg="#91a8b5",
            font=("Arial", 9),
        )
        detail_label.pack()

        tk.Label(
            pbody, text=Path(source).name,
            bg="#07131d", fg="#91a8b5",
            font=("Arial", 8),
        ).pack(pady=(5, 0))

        try:
            progress.update_idletasks()
            rw, rh = self.root.winfo_rootx(), self.root.winfo_rooty()
            ww, wh = self.root.winfo_width(), self.root.winfo_height()
            progress.geometry(f"650x270+{rw + max(0, (ww - 650)//2)}+{rh + max(0, (wh - 270)//2)}")
            progress.deiconify()
            progress.lift()
            progress.wait_visibility()
            progress.grab_set()
            progress.focus_force()
        except Exception:
            pass

        state = {"percent": 2, "detail": "Le droïde analyse votre collection…",
                 "done": False, "result": None, "error": None, "finish_scheduled": False}

        def report(value, detail):
            state["percent"] = max(0, min(100, int(value)))
            state["detail"] = str(detail)

        def worker():
            try:
                index = self._load_external_import_index()
                imported_cards = {}
                unmatched = []
                ambiguous = []
                token_rows = 0
                fallback_rows = 0
                quantity_total = 0
                total_rows = 0

                with open(source, "r", encoding="utf-8-sig", newline="") as fh:
                    reader = csv.DictReader(fh)
                    expected = reader.fieldnames or []
                    required = {"Set", "Number", "Quantity", "Name", "VariantType", "Type"}
                    missing = required - set(expected)
                    if missing:
                        raise ValueError(
                            "Le fichier ne contient pas les colonnes attendues : "
                            + ", ".join(sorted(missing))
                        )

                    raw_rows = list(reader)
                total_rows = len(raw_rows)
                if total_rows == 0:
                    raise ValueError("Le fichier CSV est vide.")

                for pos, row in enumerate(raw_rows, start=1):
                    try:
                        quantity = int(float(row.get("Quantity") or 0))
                    except (TypeError, ValueError):
                        quantity = 0
                    quantity = max(0, min(999, quantity))
                    if quantity <= 0:
                        continue

                    if self._normalize_external_text(row.get("Type")) == "token":
                        token_rows += 1

                    candidate, reason = self._match_external_card(row, index)
                    if candidate is None:
                        if reason == "ambigu":
                            ambiguous.append({
                                "set": clean_text(row.get("Set")),
                                "number": clean_text(row.get("Number")),
                                "name": clean_text(row.get("Name")),
                            })
                        else:
                            unmatched.append({
                                "set": clean_text(row.get("Set")),
                                "number": clean_text(row.get("Number")),
                                "name": clean_text(row.get("Name")),
                                "reason": reason,
                            })
                        continue

                    available = {
                        x.strip().lower()
                        for x in clean_text(candidate.get("available_languages")).split(",")
                        if x.strip()
                    }
                    target_lang = language_code
                    if target_lang not in available and "en" in available:
                        target_lang = "en"
                        fallback_rows += 1
                    elif target_lang not in available and available:
                        target_lang = sorted(available)[0]
                        fallback_rows += 1

                    standard_uid = clean_text(candidate.get("standard_uid")) or clean_text(candidate.get("printing_uid"))
                    variant_id = clean_text(candidate.get("variant_id")) or "01"
                    if not standard_uid:
                        unmatched.append({
                            "set": clean_text(row.get("Set")),
                            "number": clean_text(row.get("Number")),
                            "name": clean_text(row.get("Name")),
                            "reason": "uid_manquant",
                        })
                        continue

                    entry = imported_cards.setdefault(
                        standard_uid,
                        {
                            "serial_code": "",
                            "last_title": clean_text(candidate.get("title_fr") or candidate.get("title_en")),
                            "languages": {},
                            "type_code": clean_text(candidate.get("type_code")),
                            "extension_code": clean_text(candidate.get("expansion_code")).upper(),
                        },
                    )
                    lang_map = entry["languages"].setdefault(target_lang, {})
                    lang_map[variant_id] = max(
                        0, min(999, int(lang_map.get(variant_id, 0) or 0) + quantity)
                    )
                    quantity_total += quantity

                    if pos == 1 or pos % 100 == 0:
                        report(
                            5 + int((pos / total_rows) * 88),
                            f"Le droïde recherche vos cartes… {pos:,} / {total_rows:,}".replace(",", " "),
                        )

                report(95, "Le droïde prépare le récapitulatif…")
                state["result"] = {
                    "version": 2,
                    "cards": imported_cards,
                    "_import_info": {
                        "source": Path(source).name,
                        "total_rows": total_rows,
                        "matched_rows": total_rows - len(unmatched) - len(ambiguous),
                        "unmatched_rows": len(unmatched),
                        "ambiguous_rows": len(ambiguous),
                        "unmatched": unmatched,
                        "ambiguous": ambiguous,
                        "token_rows": token_rows,
                        "language_fallback_rows": fallback_rows,
                        "quantity_total": quantity_total,
                    },
                }
            except Exception as exc:
                state["error"] = exc
            finally:
                state["done"] = True

        def close_progress():
            try:
                progress.grab_release()
            except Exception:
                pass
            try:
                progress.destroy()
            except Exception:
                pass

        def finish():
            close_progress()

            def _show_result():
                try:
                    self.root.update_idletasks()
                except Exception:
                    pass

                if state["error"] is not None:
                    self._hud_messagebox(
                        "error", "Import externe impossible",
                        f"Le fichier n'a pas pu être analysé.\n\n{state['error']}",
                        parent=self.root,
                    )
                    return

                result = state["result"]
                info = result.get("_import_info", {})
                if not result.get("cards"):
                    self._hud_messagebox(
                        "warning", "Aucune carte reconnue",
                        "Aucune ligne exploitable n'a été rapprochée de la base de données.",
                        parent=self.root,
                    )
                    return

                if not self._show_external_import_preview(result, source, language_code):
                    self.status.set("Import externe annulé.")
                    return

                added_cards = 0
                added_quantity = 0
                overflow = 0
                cards = self.collection.setdefault("cards", {})

                for key, incoming in result["cards"].items():
                    raw = cards.get(key)
                    if not isinstance(raw, dict):
                        raw = {}
                    languages = raw.get("languages")
                    if not isinstance(languages, dict):
                        languages = {}
                    for lang, variants in incoming.get("languages", {}).items():
                        dest = languages.setdefault(lang, {})
                        for variant_id, qty in variants.items():
                            old = max(0, min(999, int(dest.get(variant_id, 0) or 0)))
                            new_value = old + int(qty)
                            if new_value > 999:
                                overflow += new_value - 999
                                new_value = 999
                            if old == 0 and new_value > 0:
                                added_cards += 1
                            added_quantity += max(0, new_value - old)
                            dest[variant_id] = new_value
                    raw["languages"] = languages
                    if not raw.get("serial_code"):
                        raw["serial_code"] = clean_text(incoming.get("serial_code"))
                    if not raw.get("last_title"):
                        raw["last_title"] = clean_text(incoming.get("last_title"))
                    cards[key] = raw

                if not self.save_collection():
                    return

                self.collection = self.load_collection()
                self.status.set(
                    f"Import externe terminé : {added_quantity:,} exemplaire(s) ajouté(s)."
                    .replace(",", " ")
                )
                try:
                    self.clear_gallery()
                    if (
                        getattr(self, "_recap_view", None) is not None
                        and self._recap_view.winfo_ismapped()
                    ):
                        self.root.after_idle(lambda: self.open_collection_recap())
                except Exception:
                    pass

                unmatched_count = int(info.get("unmatched_rows", 0) or 0)
                ambiguous_count = int(info.get("ambiguous_rows", 0) or 0)
                details = (
                    f"{added_quantity:,} exemplaire(s) ajouté(s)\n"
                    f"{len(result['cards']):,} carte(s) concernée(s)\n"
                    f"{info.get('token_rows', 0):,} ligne(s) Token rattachée(s) à leur type réel\n"
                    f"{info.get('language_fallback_rows', 0):,} ligne(s) avec fallback de langue"
                ).replace(",", " ")

                if unmatched_count or ambiguous_count:
                    details += (
                        f"\n\n{unmatched_count} ligne(s) non reconnue(s), "
                        f"{ambiguous_count} ambiguë(s)."
                    )
                if overflow:
                    details += (
                        f"\n\n{overflow} exemplaire(s) dépassant la limite de 999 "
                        "ont été plafonnés."
                    )

                self._hud_messagebox(
                    "info",
                    "Import externe terminé",
                    details,
                    parent=self.root,
                )

            self.root.after(80, _show_result)

        def animate():
            if not progress.winfo_exists():
                return
            value = max(0, min(100, int(state["percent"])))
            pct.set(value)
            msg.set(state["detail"])
            percent_label.config(text=f"{value} %")
            bar.place_configure(relwidth=max(0.02, value / 100))
            if state["done"]:
                if not state.get("finish_scheduled"):
                    state["finish_scheduled"] = True
                    finish()
                return
            progress.after(100, animate)

        progress.protocol("WM_DELETE_WINDOW", lambda: None)
        threading.Thread(
            target=worker,
            daemon=True,
            name="SWU-External-CSV-Import",
        ).start()
        progress.after(100, animate)

    def import_collection_xlsx(self):
        """Importe un export Excel dans un compte utilisateur avec progression.

        La lecture et la conversion Excel -> JSON sont réalisées dans un thread
        de travail afin que l'interface reste réactive pendant l'import.
        """
        if self.db is None:
            self._hud_messagebox(
                "error",
                "Import impossible",
                "La base de données n'est pas disponible.",
            )
            return

        new_user = self._hud_messagebox(
            "askyesno",
            "Importer une collection",
            "Cette collection doit-elle être importée pour un nouvel utilisateur ?",
            parent=self.root,
        )

        accounts = self._load_accounts()
        new_account = None

        if new_user:
            pseudo = self._ask_new_account(self.root, accounts)
            if not pseudo:
                return
            new_account = {
                "pseudo": pseudo,
                "filename": self._account_filename(pseudo),
            }
            target_dir = ACCOUNTS_DIR / self._account_safe_name(pseudo)
            target_dir.mkdir(parents=True, exist_ok=True)
            target_path = target_dir / new_account["filename"]
        else:
            target_path = self.collection_path

        try:
            source = filedialog.askopenfilename(
                parent=self.root,
                title="Choisir le fichier d'import de la collection",
                filetypes=[
                    ("Export SWU Collection Manager", "*.xlsx"),
                    ("Fichiers Excel", "*.xlsx;*.xlsm"),
                    ("Tous les fichiers", "*.*"),
                ],
            )
        except Exception as exc:
            self._hud_messagebox(
                "error",
                "Import impossible",
                f"Impossible d'ouvrir le choix du fichier.\n\n{exc}",
                parent=self.root,
            )
            return

        if not source:
            return

        # Pour un compte existant, demander la stratégie AVANT de lancer le
        # traitement lourd. Aucun fichier n'est encore modifié à ce stade.
        action = "overwrite"
        if not new_user:
            action = self._ask_import_existing_action(self.root)
            if action == "cancel":
                self.status.set("Importation annulée.")
                return

        self.status.set("Préparation de l'importation…")

        progress, pbody = self._create_hud_toplevel(
            self.root,
            "Import de la collection",
        )
        progress.geometry("650x270")
        progress.update_idletasks()

        rw = self.root.winfo_rootx()
        rh = self.root.winfo_rooty()
        ww = self.root.winfo_width()
        wh = self.root.winfo_height()
        progress.geometry(
            f"650x270+{rw + max(0, (ww - 650) // 2)}"
            f"+{rh + max(0, (wh - 270) // 2)}"
        )

        msg = tk.StringVar(value="Le droïde ouvre le fichier d'import…")
        pct = tk.IntVar(value=2)

        tk.Label(
            pbody,
            textvariable=msg,
            bg="#07131d",
            fg="#e7f1f7",
            font=("Arial", 11, "bold"),
        ).pack(pady=(22, 12))

        bar_frame = tk.Frame(
            pbody,
            bg="#164b68",
            height=24,
        )
        bar_frame.pack(fill="x", padx=30, pady=5)
        bar_frame.pack_propagate(False)

        bar = tk.Frame(
            bar_frame,
            bg="#2f9bd1",
            height=20,
        )
        bar.place(x=2, y=2, relwidth=0.02, relheight=1)

        percent_label = tk.Label(
            pbody,
            text="2 %",
            bg="#07131d",
            fg="#e2b84b",
            font=("Arial", 10, "bold"),
        )
        percent_label.pack(pady=(5, 2))

        detail_label = tk.Label(
            pbody,
            text="Ne ferme pas le Collection Manager pendant l'import.",
            bg="#07131d",
            fg="#91a8b5",
            font=("Arial", 9),
        )
        detail_label.pack()

        source_label = tk.Label(
            pbody,
            text=Path(source).name,
            bg="#07131d",
            fg="#91a8b5",
            font=("Arial", 8),
        )
        source_label.pack(pady=(5, 0))

        try:
            progress.deiconify()
            progress.lift()
            progress.grab_set()
            progress.focus_force()
        except Exception:
            pass

        state = {
            "percent": 2,
            "detail": "Le droïde ouvre le fichier d'import…",
            "done": False,
            "result": None,
            "error": None,
        }

        def progress_callback(value, detail):
            # Cette fonction est appelée depuis le thread de travail.
            state["percent"] = max(0, min(100, int(value)))
            state["detail"] = str(detail)

        def worker():
            try:
                imported = self._read_collection_export_xlsx(
                    source,
                    progress_callback=progress_callback,
                )

                if not imported.get("cards"):
                    raise ValueError(
                        "Le fichier a bien été lu, mais aucune quantité positive "
                        "n'a été trouvée."
                    )

                state["result"] = imported
            except Exception as exc:
                state["error"] = exc
            finally:
                state["done"] = True

        def finish_error(exc):
            try:
                progress.grab_release()
            except Exception:
                pass
            try:
                progress.destroy()
            except Exception:
                pass

            self.status.set("Échec de l'importation.")
            self._hud_messagebox(
                "error",
                "Import impossible",
                f"Le fichier n'a pas pu être importé.\n\n{exc}",
                parent=self.root,
            )

        def finish_success(imported):
            info = imported.get("_import_info", {})
            backup_path = None

            try:
                # Le traitement Excel est terminé et validé. C'est seulement
                # maintenant que l'on modifie le disque.
                state["percent"] = 96
                state["detail"] = "Enregistrement de la nouvelle collection…"
                progress.update_idletasks()

                if new_user:
                    if target_path.exists():
                        raise FileExistsError(
                            f"Le fichier de collection du compte "
                            f"« {new_account['pseudo']} » existe déjà."
                        )

                    self._write_collection_json(target_path, imported)
                    self._write_auxiliary_json(target_dir / self._account_trade_filename(new_account["pseudo"]), self._empty_aux_data())
                    self._write_auxiliary_json(target_dir / self._account_wanted_filename(new_account["pseudo"]), self._empty_aux_data())

                    try:
                        self._save_accounts(accounts + [new_account])
                    except Exception:
                        try:
                            target_path.unlink()
                        except Exception:
                            pass
                        raise

                    self._activate_imported_account(new_account)

                else:
                    if action == "backup" and self.collection_path.exists():
                        BACKUP_COLLECTIONS_DIR.mkdir(
                            parents=True,
                            exist_ok=True,
                        )
                        backup_path = BACKUP_COLLECTIONS_DIR / (
                            f"{self.collection_path.stem}_backup_avant_import_"
                            f"{datetime.now().strftime('%Y%m%d_%H%M%S')}.json"
                        )
                        shutil.copy2(self.collection_path, backup_path)

                    self._write_collection_json(
                        self.collection_path,
                        imported,
                    )
                    self.collection = self.load_collection()
                    self.status.set(
                        f"Collection importée : {len(imported['cards'])} carte(s)."
                    )

                    try:
                        self.clear_gallery()
                    except Exception:
                        pass

                    try:
                        if (
                            getattr(self, "_recap_view", None) is not None
                            and self._recap_view.winfo_ismapped()
                        ):
                            self.root.after_idle(
                                lambda: self.open_collection_recap()
                            )
                    except Exception:
                        pass

                state["percent"] = 100
                state["detail"] = "Importation terminée."
                pct.set(100)
                percent_label.config(text="100 %")
                bar.place_configure(relwidth=1.0)
                msg.set("Le droïde a terminé l'importation.")

                progress.after(
                    700,
                    lambda: close_success(imported, info, backup_path),
                )

            except Exception as exc:
                finish_error(exc)

        def close_success(imported, info, backup_path):
            try:
                progress.grab_release()
            except Exception:
                pass
            try:
                progress.destroy()
            except Exception:
                pass

            warning_parts = []
            if info.get("invalid_rows"):
                warning_parts.append(
                    f"{len(info['invalid_rows'])} ligne(s) non reconnue(s)"
                )
            if info.get("ambiguous_columns"):
                warning_parts.append(
                    f"{len(info['ambiguous_columns'])} colonne(s) ambiguë(s)"
                )

            message = (
                f"{len(imported['cards'])} carte(s) importée(s)\n"
                f"{info.get('quantity_cells', 0)} quantité(s) positive(s)\n"
                f"{info.get('sheets', 0)} feuille(s) traitée(s)"
            )

            if backup_path:
                message += (
                    f"\n\nSauvegarde créée :\n{backup_path.name}"
                )

            if warning_parts:
                message += (
                    "\n\nAttention : "
                    + " ; ".join(warning_parts)
                    + "."
                )

            self._hud_messagebox(
                "info",
                "Importation terminée",
                message,
                parent=self.root,
            )

        def animate():
            if not progress.winfo_exists():
                return

            value = max(0, min(100, int(state["percent"])))
            pct.set(value)
            msg.set(state["detail"])
            percent_label.config(text=f"{value} %")
            bar.place_configure(
                relwidth=max(0.02, value / 100),
            )

            if state["done"]:
                if state["error"] is not None:
                    finish_error(state["error"])
                    return

                finish_success(state["result"])
                return

            progress.after(100, animate)

        try:
            progress.protocol(
                "WM_DELETE_WINDOW",
                lambda: None,
            )
        except Exception:
            pass

        threading.Thread(
            target=worker,
            daemon=True,
            name="SWU-Collection-Import",
        ).start()

        progress.after(100, animate)

    def export_collection_xlsx(self):
        """Exporte la collection puis propose un téléversement manuel sur l'Holonet."""
        if self.db is None:
            self._hud_messagebox("error", "Export impossible", "La base de données n'est pas disponible.")
            return

        # Une seule étape de destination : l'utilisateur choisit le dossier local.
        # Les services Cloud ne sont pas considérés comme des destinations de fichier.
        try:
            folder = filedialog.askdirectory(
                parent=self.root,
                title="Choisir le dossier où enregistrer l'export de ta collection"
            )
        except Exception as exc:
            self._hud_messagebox("error", "Export impossible", f"Impossible d'ouvrir le choix du dossier.\n\n{exc}")
            return
        if not folder:
            return

        try:
            folder = Path(folder)
            folder.mkdir(parents=True, exist_ok=True)
            date_str = datetime.now().strftime("%Y-%m-%d")
            pseudo = safe_filename(self.account_pseudo).strip("._") or "Utilisateur"
            filename = f"SWU-collection_{pseudo}_{date_str}.xlsx"
            target = folder / filename

            if target.exists():
                if not self._hud_messagebox(
                    "askyesno",
                    "Fichier déjà présent",
                    f"Le fichier existe déjà :\n\n{filename}\n\nVeux-tu le remplacer ?",
                    parent=self.root
                ):
                    return

            self.status.set("Préparation de l'export…")

            progress, pbody = self._create_hud_toplevel(self.root, "Export de la collection")
            progress.geometry("620x245")
            progress.update_idletasks()
            rw = self.root.winfo_rootx(); rh = self.root.winfo_rooty()
            ww = self.root.winfo_width(); wh = self.root.winfo_height()
            progress.geometry(f"620x245+{rw + max(0,(ww-620)//2)}+{rh + max(0,(wh-245)//2)}")

            msg = tk.StringVar(value="Le droïde rassemble les cartes…")
            pct = tk.IntVar(value=5)
            tk.Label(pbody, textvariable=msg, bg="#07131d", fg="#e7f1f7", font=("Arial", 11, "bold")).pack(pady=(22,12))
            bar_frame = tk.Frame(pbody, bg="#164b68", height=24)
            bar_frame.pack(fill="x", padx=30, pady=5)
            bar_frame.pack_propagate(False)
            bar = tk.Frame(bar_frame, bg="#2f9bd1", height=20)
            bar.place(x=2, y=2, relwidth=0.03, relheight=1)
            percent_label = tk.Label(pbody, text="5 %", bg="#07131d", fg="#e2b84b", font=("Arial", 10, "bold"))
            percent_label.pack(pady=(5,2))
            tk.Label(pbody, text="Ne ferme pas le Collection Manager pendant l'export.", bg="#07131d", fg="#91a8b5", font=("Arial", 9)).pack()
            progress.deiconify(); progress.lift()
            try:
                progress.attributes("-topmost", True)
                progress.after(350, lambda: progress.attributes("-topmost", False) if progress.winfo_exists() else None)
                progress.grab_set(); progress.focus_force()
            except Exception:
                pass

            stages = [
                (12, "Le droïde rassemble les cartes…"),
                (28, "Tri des exemplaires possédés…"),
                (45, "Même les cartes foil sont priées de se mettre en rang…"),
                (62, "Vérification des langues et variantes…"),
                (76, "Le droïde recompte une dernière fois…"),
                (88, "Compilation du fichier Excel…"),
            ]
            state = {"i": 0}
            result = {"done": False, "error": None}

            def worker():
                try:
                    self._build_collection_workbook(target)
                    if not target.exists() or target.stat().st_size <= 0:
                        raise RuntimeError("Le fichier exporté n'a pas pu être vérifié sur le disque.")
                    unlocked_count = self._verify_and_finalize_export_protection(target)
                    if unlocked_count <= 0:
                        raise RuntimeError("Aucune cellule de quantité modifiable n'a été détectée dans l'export.")
                except Exception as exc:
                    result["error"] = exc
                finally:
                    result["done"] = True

            def animate():
                if not progress.winfo_exists():
                    return
                if not result["done"]:
                    i = state["i"]
                    if i < len(stages):
                        value, text_value = stages[i]
                        pct.set(value)
                        msg.set(text_value)
                        percent_label.config(text=f"{value} %")
                        bar.place_configure(relwidth=max(0.03, value/100))
                        state["i"] += 1
                    progress.after(700, animate)
                    return

                if result["error"] is not None:
                    try:
                        progress.grab_release(); progress.destroy()
                    except Exception:
                        pass
                    self.status.set("Échec de l'export.")
                    self._hud_messagebox("error", "Export impossible", f"Impossible de créer le fichier Excel.\n\n{result['error']}")
                    return

                pct.set(100)
                percent_label.config(text="100 %")
                bar.place_configure(relwidth=1.0)
                msg.set("Le droïde a terminé : aucune carte ne semble avoir disparu.")
                self.status.set(f"Collection exportée : {filename}")
                progress.after(500, finish_success)

            def finish_success():
                try:
                    progress.grab_release(); progress.destroy()
                except Exception:
                    pass
                show_upload_holonet()

            def show_upload_holonet():
                """Annonce la création du fichier et propose son téléversement manuel."""
                dialog, body = self._create_hud_toplevel(self.root, "Téléversement sur l'Holonet")
                dialog.geometry("620x340")
                dialog.update_idletasks()
                rw = self.root.winfo_rootx(); rh = self.root.winfo_rooty()
                ww = self.root.winfo_width(); wh = self.root.winfo_height()
                dialog.geometry(f"620x340+{rw + max(0,(ww-620)//2)}+{rh + max(0,(wh-340)//2)}")
                dialog.deiconify(); dialog.lift()
                try:
                    dialog.attributes("-topmost", True)
                    dialog.after(350, lambda: dialog.attributes("-topmost", False) if dialog.winfo_exists() else None)
                    dialog.grab_set(); dialog.focus_force()
                except Exception:
                    pass

                tk.Label(
                    body, text="EXPORT TERMINÉ", bg="#07131d", fg="#e2b84b",
                    font=("Arial", 16, "bold")
                ).pack(pady=(20, 8))
                tk.Label(
                    body,
                    text="Le droïde confirme que le fichier a été correctement créé.",
                    bg="#07131d", fg="#e7f1f7", font=("Arial", 11, "bold")
                ).pack(pady=(0, 6))
                tk.Label(
                    body,
                    text=f"\n{filename}\n\n{target}",
                    bg="#07131d", fg="#91a8b5", font=("Arial", 9),
                    justify="center", wraplength=560
                ).pack(pady=(0, 12))
                tk.Label(
                    body,
                    text="Souhaites-tu maintenant téléverser ta collection sur l'Holonet ?",
                    bg="#07131d", fg="#e7f1f7", font=("Arial", 10)
                ).pack(pady=(0, 10))

                actions = tk.Frame(body, bg="#07131d")
                actions.pack(fill="x", padx=28, pady=4)

                def finish_dialog():
                    try:
                        dialog.grab_release()
                    except Exception:
                        pass
                    try:
                        dialog.destroy()
                    except Exception:
                        pass

                def open_cloud(url):
                    # Pour faciliter le glisser-déposer, on ouvre d'abord le
                    # dossier local contenant le fichier, puis le service cloud.
                    # Le dépôt reste volontairement manuel.
                    try:
                        if os.name == "nt":
                            os.startfile(str(folder))
                        else:
                            subprocess.Popen(["xdg-open", str(folder)])
                    except Exception:
                        pass
                    try:
                        opened = webbrowser.open_new_tab(url)
                        if not opened and os.name == "nt":
                            os.startfile(url)
                    except Exception:
                        try:
                            webbrowser.open(url)
                        except Exception:
                            pass
                    finish_dialog()

                cloud_options = [
                    ("☁  GOOGLE DRIVE", "https://drive.google.com/drive/my-drive"),
                    ("☁  ONE DRIVE", "https://onedrive.live.com/"),
                ]
                for label, url in cloud_options:
                    hud = HUDFrame(actions, bg="#07131d")
                    hud.pack(fill="x", pady=4)
                    tk.Button(
                        hud, text=label, command=lambda u=url: open_cloud(u),
                        bg="#0d2634", fg="#ffffff", activebackground="#164b68", activeforeground="#ffffff",
                        font=("Arial", 10, "bold"), relief="flat", bd=0, highlightthickness=0,
                        cursor="hand2", padx=12, pady=7
                    ).pack(fill="x", padx=6, pady=4)

                hud = HUDFrame(actions, bg="#07131d")
                hud.pack(fill="x", pady=4)
                tk.Button(
                    hud, text="✕  NON MERCI", command=finish_dialog,
                    bg="#0d2634", fg="#ffffff", activebackground="#164b68", activeforeground="#ffffff",
                    font=("Arial", 10, "bold"), relief="flat", bd=0, highlightthickness=0,
                    cursor="hand2", padx=12, pady=7
                ).pack(fill="x", padx=6, pady=4)

                dialog.protocol("WM_DELETE_WINDOW", finish_dialog)

            threading.Thread(target=worker, daemon=True).start()
            progress.after(100, animate)

        except Exception as exc:
            self.status.set("Échec de l'export.")
            self._hud_messagebox("error", "Export impossible", f"Impossible de préparer l'export.\n\n{exc}")
    def open_collection_recap(self, expansion_code=None, status_mode=None):
        """Affiche le récapitulatif fixe puis la galerie défilante du set."""
        stats = self._collection_recap_stats(expansion_code)
        if not stats:
            self._hud_messagebox("info", "Récapitulatif", "Aucune donnée de collection à afficher.")
            return

        self.clear_gallery()
        self.status.set("Récapitulatif de la collection" if not expansion_code else f"Récapitulatif — {expansion_code}")
        self.page_info.set("")

        if expansion_code:
            rows = self._collection_variant_rows(expansion_code)
            if not rows:
                self._enter_collection_recap_layout(
                    f"Récapitulatif — {expansion_code}", stats, [], lambda _selected: None,
                    expansion_code=expansion_code
                )
                tk.Label(self._gallery_holder,
                         text="Aucune impression trouvée dans la base pour cette extension.",
                         bg="#07131d", fg="#91a8b5", font=("Arial", 11)).pack(pady=25)
                return

            self._enter_collection_recap_layout(
                f"Récapitulatif — {expansion_code}",
                stats,
                rows,
                lambda selected, rs=rows, ec=expansion_code, sm=status_mode: self._display_collection_status_or_owned_gallery(
                    self.content, rs, selected, sm, ec
                ),
                expansion_code=expansion_code
            )
            # Le conteneur de galerie reste le même, mais il faut le prendre
            # après l'entrée dans la mise en page COLLECTION afin de garantir
            # que les cartes sont ajoutées dans le Canvas actuellement visible.
            gallery = self.content
            initial_version = "01" if any(clean_text(r.get("variant_id")) == "01" for r in rows) else clean_text(rows[0].get("variant_id"))
            self._display_collection_status_or_owned_gallery(
                gallery, rows, initial_version, status_mode, expansion_code
            )
        else:
            # Récapitulatif global : on conserve l'affichage historique, mais
            # sans le système de tri de la galerie.
            root = self.content
            title = "Récapitulatif de collection"
            recap_title_row = tk.Frame(root, bg="#07131d")
            recap_title_row.pack(fill="x", padx=0, pady=(12, 10))
            tk.Label(recap_title_row, text=title, bg="#07131d", fg="#f2f2f2",
                     font=("Arial", 20, "bold")).pack(side="left", anchor="w")
            self._global_recap_value_label = tk.Label(
                recap_title_row, text="Valeur estimée : calcul...",
                bg="#07131d", fg="#91a8b5", font=("Arial", 12, "bold")
            )
            self._global_recap_value_label.pack(side="left", padx=(28, 0), anchor="w")
            self._global_recap_value_labels = {}
            table = tk.Frame(root, bg="#07131d")
            table.pack(fill="both", expand=True, pady=(0, 10))
            headers = ["Extension", "Possédées", "Total", "Complétion", "Playsets", "Exemplaires", "Recherchées", "À échanger", "Valeur estimée"]
            for col, header in enumerate(headers):
                table.columnconfigure(col, weight=1 if col == 0 else 0)
                tk.Label(table, text=header, bg="#12384d", fg="#ffffff",
                         font=("Arial", 10, "bold"), padx=8, pady=8).grid(
                             row=0, column=col, sticky="nsew", padx=(0, 1), pady=(0, 1))
            for row_index, x in enumerate(stats, start=1):
                bg = "#0b1d2a" if row_index % 2 else "#102b3b"
                values = (x["code"] + " — " + x["name"], x["owned_cards"], x["total"],
                          f"{x['pct']:.1f} %",
                          f"{x.get('playset_completed', 0)} / {x.get('playset_possible', 0)}",
                          x["copies"], x["wanted"], x.get("trade", 0),
                          self._format_estimated_value(x.get("estimated_value", 0.0)))
                for col, value in enumerate(values):
                    cell = tk.Label(table, text=str(value), bg=bg, fg="#dce8ee",
                                    font=("Arial", 10), padx=8, pady=7,
                                    anchor="w" if col == 0 else "center")
                    cell.grid(row=row_index, column=col, sticky="nsew", padx=(0, 1), pady=(0, 1))
                    if col == 8:
                        self._global_recap_value_labels[x["code"]] = cell
            # Le calcul se lance une fois le tableau affiché.
            self._start_recap_value_calculation(None, stats)

        self.content.update_idletasks()
        self.canvas.configure(scrollregion=self.canvas.bbox("all"))
        self.canvas.yview_moveto(0)

    def on_language_changed(self, _event=None):
        """Actualise les libellés dépendant de la langue sans lancer le chargement."""
        current_expansion_codes = set(getattr(self, "_selected_expansion_codes", set()))
        current_type_filters = {key: var.get() for key, var in self.type_filter_vars.items()}
        current_rarity_filters = {key: var.get() for key, var in self.rarity_filter_vars.items()}
        self.populate_filters()

        for key, value in current_type_filters.items():
            self.type_filter_vars[key].set(value)
        for key, value in current_rarity_filters.items():
            self.rarity_filter_vars[key].set(value)

        buttons = getattr(self, "_filter_extension_buttons", {})
        self._selected_expansion_codes = {
            code for code in current_expansion_codes if code in buttons
        }
        labels = []
        for code in sorted(self._selected_expansion_codes):
            try:
                labels.append(f"{code} — {clean_text(buttons[code].cget('text'))}")
                buttons[code].configure(
                    relief="sunken", bg="#164b68", activebackground="#205f7f",
                    highlightbackground="#f2c94c", highlightcolor="#f2c94c",
                    highlightthickness=2
                )
            except Exception:
                pass
        for code, button in buttons.items():
            if code not in self._selected_expansion_codes:
                try:
                    button.configure(
                        relief="flat", bg="#0d2634", activebackground="#164b68",
                        highlightbackground="#07131d", highlightcolor="#07131d",
                        highlightthickness=0
                    )
                except Exception:
                    pass
        self.expansion.set(" ; ".join(labels))

        self._refresh_dependent_filter_choices()
        self.status.set("Filtres modifiés — clique sur « ✓ Valider les filtres » pour afficher les cartes.")

    def _set_all_category_filters(self, value=True):
        """Active ou désactive toutes les cases Type et Rareté."""
        self.type_all_var.set(value)
        self.rarity_all_var.set(value)
        for var in self.type_filter_vars.values():
            var.set(value)
        for var in self.rarity_filter_vars.values():
            var.set(value)

    def _set_all_types(self):
        """Coche ou décoche tous les filtres de type."""
        value = self.type_all_var.get()
        for var in self.type_filter_vars.values():
            var.set(value)
        self._update_filter_status()

    def _set_all_rarities(self):
        """Coche ou décoche tous les filtres de rareté."""
        value = self.rarity_all_var.get()
        for var in self.rarity_filter_vars.values():
            var.set(value)
        self._update_filter_status()

    def _update_filter_status(self):
        """Met à jour le message sans lancer automatiquement la recherche."""
        self.status.set("Filtres modifiés — clique sur « ✓ Valider les filtres » pour afficher les cartes.")

    def _type_filter_changed(self):
        self.type_all_var.set(all(var.get() for var in self.type_filter_vars.values()))
        self._update_filter_status()

    def _rarity_filter_changed(self):
        self.rarity_all_var.set(all(var.get() for var in self.rarity_filter_vars.values()))
        self._update_filter_status()

    def reset_filters(self):
        self.search.set("")
        self._selected_expansion_codes = set()
        self.expansion.set("")
        self.keyword_filter_var.set("Tous les mots-clés")
        if hasattr(self, "keyword_combo"):
            try:
                self._refresh_dependent_filter_choices()
                self.keyword_combo.set("Tous les mots-clés")
                self.trait_combo.set("Tous les traits")
            except Exception:
                pass
        self.trait_filter_var.set("Tous les traits")
        for button in getattr(self, "_filter_extension_buttons", {}).values():
            try:
                button.configure(
                    relief="flat",
                    bg="#0d2634",
                    activebackground="#164b68",
                    highlightbackground="#07131d",
                    highlightcolor="#07131d",
                    highlightthickness=0,
                )
            except Exception:
                pass
        self._set_all_category_filters(True)
        self._selected_aspects_main.clear()
        self._selected_aspect_alignment = None
        self.aspect1_filter_var.set("")
        self.aspect2_filter_var.set("")
        self._refresh_aspect_filter_line(self.aspect1_filter_var, "main")
        self._refresh_aspect_filter_line(self.aspect1_filter_var, "alignment")
        self.language.set("fr")

        # Réinitialiser signifie aussi vider complètement la galerie :
        # aucune carte ne reste affichée tant qu'un filtre n'est pas validé.
        self.clear_gallery()
        self.status.set("Filtres réinitialisés — galerie vidée. Clique sur « ✓ Valider les filtres » pour afficher les cartes.")

    def build_query(self, name_only=False):
        # Une seule langue d'affichage : celle choisie pour l'interface.
        # Le choix des langues disponibles pour le stock se fait désormais
        # dans la boîte de dialogue de chaque carte.
        selected_language_ids = [LANGUAGES.get(self.language.get(), LANGUAGES["fr"])]

        # On part de card_printing : une ligne = une impression.
        # Le titre vient de la localisation du concept.
        # IMPORTANT :
        # Chaque langue sélectionnée produit sa propre ligne de catalogue.
        # L'image est strictement celle de la langue de cette ligne :
        # aucun fallback anglais n'est utilisé.

        sql = """
        SELECT
            cp.id AS printing_id,
            cp.card_uid,
            cp.serial_code,
            cp.card_number,
            cp.card_count,
            cp.hyperspace,
            cp.showcase,
            cp.art_front_horizontal,
            cp.art_back_horizontal,

            cc.id AS concept_id,
            cc.cost,
            cc.power,
            (
                SELECT GROUP_CONCAT(k.code, ', ')
                FROM card_concept_keyword cck
                JOIN keyword k ON k.id = cck.keyword_id
                WHERE cck.card_concept_id = cc.id
            ) AS keywords_text,
            cc.hp,
            cc.is_unique,

            cl.title,
            cl.subtitle,
            cl.language_id AS display_language_id,

            e.code AS expansion_code,
            COALESCE(el_en.name, e.name, e.code) AS expansion_name,
            COALESCE(el_en.name, e.name, e.code) AS expansion_name_en,

            ct.code AS type_code,
            ct2.code AS type2_code,

            r.code AS rarity_code,

            vt.variant_id,
            vtloc.name AS variant_name,

            ci_front.url AS image_url,
            ci_front.width AS image_width,
            ci_front.height AS image_height,
            cl.language_id AS image_language_id

        FROM card_printing cp

        LEFT JOIN card_concept cc
          ON cc.id = cp.card_concept_id

        JOIN card_localization cl
          ON cl.card_concept_id = cc.id
         AND cl.language_id IN (?,?,?,?,?)

        LEFT JOIN expansion e
          ON e.id = cp.expansion_id

        LEFT JOIN expansion_localization el_en
          ON el_en.expansion_id = e.id
         AND el_en.language_id = 1

        LEFT JOIN card_type ct
          ON ct.id = cc.type_id

        LEFT JOIN card_type ct2
          ON ct2.id = cc.type2_id

        LEFT JOIN rarity r
          ON r.id = cp.rarity_id

        LEFT JOIN variant_type vt
          ON vt.id = cp.variant_type_id

        LEFT JOIN variant_type_localization vtloc
          ON vtloc.variant_type_id = vt.id
         AND vtloc.language_id = ?

        LEFT JOIN card_image ci_front
          ON ci_front.card_printing_id = cp.id
         AND ci_front.image_role = 'front'
         AND ci_front.language_id = cl.language_id

        WHERE 1 = 1
        """

        # Paramètres : langue image (URL, largeur, hauteur),
        # localisation du texte, puis localisation du type de variante.
        params = list(selected_language_ids) + [-1] * (5 - len(selected_language_ids))
        # Libellé de variante dans la langue de l'interface.
        params.append(LANGUAGES.get(self.language.get(), LANGUAGES["fr"]))

        # La recherche par nom n'est active que lorsque build_query() est
        # explicitement appelé en mode "nom uniquement". Elle est donc
        # totalement indépendante des autres filtres.
        search_term = self.search.get().strip() if name_only else ""
        search_mode = bool(search_term)

        selected_expansion_codes = sorted(getattr(self, "_selected_expansion_codes", set()))

        if search_mode:
            # Recherche globale : aucune contrainte d'extension ni autre
            # filtre utilisateur n'est ajoutée ici.
            sql += " AND cl.title LIKE ?"
            params.append(f"%{search_term}%")

        if not search_mode:
            selected_keyword_code = self._selected_keyword_code()
            if selected_keyword_code:
                sql += """
                    AND EXISTS (
                        SELECT 1
                        FROM card_concept_keyword cck_filter
                        JOIN keyword k_filter ON k_filter.id = cck_filter.keyword_id
                        WHERE cck_filter.card_concept_id = cc.id
                          AND k_filter.code = ?
                    )
                """
                params.append(selected_keyword_code)

            selected_trait_code = self._selected_trait_code()
            if selected_trait_code:
                sql += """
                    AND EXISTS (
                        SELECT 1
                        FROM card_concept_trait cct_filter
                        JOIN trait t_filter ON t_filter.id = cct_filter.trait_id
                        WHERE cct_filter.card_concept_id = cc.id
                          AND t_filter.code = ?
                    )
                """
                params.append(selected_trait_code)

            # Filtres Type : une seule sélection SQL regroupant toutes les
            # catégories cochées. Ground / Space passent par la relation
            # card_concept_arena.
            selected_types = [
                key for key, var in self.type_filter_vars.items()
                if var.get()
            ]
            if not selected_types:
                sql += " AND 1 = 0"
            else:
                type_conditions = []
                if "Leader" in selected_types:
                    type_conditions.append("ct.code = ?")
                    params.append("Leader")
                if "Base" in selected_types:
                    type_conditions.append("ct.code = ?")
                    params.append("Base")
                if "Ground" in selected_types:
                    type_conditions.append("EXISTS (SELECT 1 FROM card_concept_arena cca_g JOIN arena a_g ON a_g.id = cca_g.arena_id WHERE cca_g.card_concept_id = cc.id AND LOWER(a_g.code) = 'ground')")
                if "Space" in selected_types:
                    type_conditions.append("EXISTS (SELECT 1 FROM card_concept_arena cca_s JOIN arena a_s ON a_s.id = cca_s.arena_id WHERE cca_s.card_concept_id = cc.id AND LOWER(a_s.code) = 'space')")
                if "Event" in selected_types:
                    type_conditions.append("ct.code = ?")
                    params.append("Event")
                if "Upgrade" in selected_types:
                    type_conditions.append("ct.code = ?")
                    params.append("Upgrade")
                if "Token" in selected_types:
                    type_conditions.append("ct.code = ?")
                    params.append("Token")
                sql += " AND (" + " OR ".join(type_conditions) + ")"

                # Les filtres de type doivent rester indépendants des
                # filtres d'affinité et surtout empêcher explicitement les
                # catégories qui ont été décochées de réapparaître via une
                # autre relation de la carte (type secondaire, arène, etc.).
                # Cela garantit notamment que décocher « Leader » exclut
                # réellement tous les leaders, même lorsqu'un filtre
                # d'affinité Héroïsme/Infâmie est actif.
                excluded_type_codes = []
                for _type_code in ("Leader", "Base", "Event", "Upgrade", "Token"):
                    _type_var = self.type_filter_vars.get(_type_code)
                    if _type_var is not None and not _type_var.get():
                        excluded_type_codes.append(_type_code)
                for _excluded_type in excluded_type_codes:
                    sql += " AND COALESCE(ct.code, '') <> ?"
                    params.append(_excluded_type)

            # Filtres Rareté dans l'ordre demandé : Commune, Peu commune,
            # Rare, Légendaire, Spéciale.
            selected_rarities = [
                key for key, var in self.rarity_filter_vars.items()
                if var.get()
            ]
            if not selected_rarities:
                sql += " AND 1 = 0"
            else:
                placeholders = ",".join("?" for _ in selected_rarities)
                sql += f" AND r.code IN ({placeholders})"
                params.extend(selected_rarities)

            # Filtres d'affinité indépendants, appliqués EN PLUS de tous
            # les filtres précédents.
            #
            # Groupe principal : Vigilance / Commandement / Agressivité / Ruse.
            # Une sélection de couleurs définit l'ensemble autorisé : une carte
            # peut avoir une ou plusieurs de ces couleurs, mais aucune couleur
            # extérieure à la sélection. Héroïsme/Infâmie sont exclus tant
            # qu'ils ne sont pas explicitement sélectionnés.
            #
            # Héroïsme / Infâmie sont un second filtre : leur sélection AJOUTE
            # les cartes correspondantes à la sélection principale.
            # Neutre est totalement indépendant : sa sélection AJOUTE toutes
            # les cartes Neutre, quelle que soit leur autre affinité.
            selected_main_aspects = {clean_text(x).lower() for x in self._selected_aspects_main}
            main_colors = {"vigilance", "command", "aggression", "cunning"}
            selected_main_colors = sorted(selected_main_aspects & main_colors)
            include_neutral = "neutral" in selected_main_aspects
            selected_alignment = clean_text(self._selected_aspect_alignment).lower() if self._selected_aspect_alignment else ""

            # Le groupe d'affinités devient réellement indépendant : on
            # construit une condition d'admission puis on ajoute le joker
            # Neutre par OR.
            affinity_parts = []
            affinity_params = []

            if selected_main_colors:
                ph = ",".join("?" for _ in selected_main_colors)
                # Au moins une couleur sélectionnée et aucune couleur hors
                # sélection. Les cartes Hero/Villain sont volontairement
                # exclues ici tant que le second groupe n'est pas activé.
                base_condition = f"""
                    EXISTS (
                        SELECT 1 FROM card_concept_aspect cca_m
                        JOIN aspect a_m ON a_m.id = cca_m.aspect_id
                        WHERE cca_m.card_concept_id = cc.id
                          AND LOWER(a_m.code) IN ({ph})
                    )
                    AND NOT EXISTS (
                        SELECT 1 FROM card_concept_aspect cca_ex
                        JOIN aspect a_ex ON a_ex.id = cca_ex.aspect_id
                        WHERE cca_ex.card_concept_id = cc.id
                          AND LOWER(a_ex.code) IN ({','.join('?' for _ in (main_colors - set(selected_main_colors))) if main_colors - set(selected_main_colors) else "NULL"})
                    )
                """
                affinity_params.extend(selected_main_colors)
                excluded = sorted(main_colors - set(selected_main_colors))
                if excluded:
                    affinity_params.extend(excluded)
                else:
                    # Remplace le IN (NULL) inutile par une condition vraie.
                    base_condition = base_condition.replace(
                        "AND NOT EXISTS (\n                        SELECT 1 FROM card_concept_aspect cca_ex\n                        JOIN aspect a_ex ON a_ex.id = cca_ex.aspect_id\n                        WHERE cca_ex.card_concept_id = cc.id\n                          AND LOWER(a_ex.code) IN (NULL)\n                    )", "")

                if selected_alignment in ("heroism", "villainy"):
                    # Le second groupe est complémentaire du premier :
                    #   - les cartes correspondant aux couleurs sélectionnées
                    #     restent visibles même sans Héroïsme/Infâmie ;
                    #   - elles peuvent aussi posséder l'alignement choisi ;
                    #   - l'alignement opposé est toujours exclu ;
                    #   - les cartes possédant uniquement l'alignement choisi
                    #     sont également ajoutées.
                    # Exemple : Vigilance + Vilainie donne Vigilance seule,
                    # Vigilance+Vilainie et Vilainie seule.
                    opposite_alignment = "villainy" if selected_alignment == "heroism" else "heroism"
                    affinity_parts.append(f"""
                        (
                            ({base_condition})
                            AND NOT EXISTS (
                                SELECT 1 FROM card_concept_aspect cca_opp
                                JOIN aspect a_opp ON a_opp.id = cca_opp.aspect_id
                                WHERE cca_opp.card_concept_id = cc.id
                                  AND LOWER(a_opp.code) = ?
                            )
                        )
                    """)
                    affinity_params.append(opposite_alignment)
                    affinity_parts.append("""
                        (
                            EXISTS (
                                SELECT 1 FROM card_concept_aspect cca_al
                                JOIN aspect a_al ON a_al.id = cca_al.aspect_id
                                WHERE cca_al.card_concept_id = cc.id
                                  AND LOWER(a_al.code) = ?
                            )
                            AND NOT EXISTS (
                                SELECT 1 FROM card_concept_aspect cca_no
                                JOIN aspect a_no ON a_no.id = cca_no.aspect_id
                                WHERE cca_no.card_concept_id = cc.id
                                  AND LOWER(a_no.code) IN ('vigilance','command','aggression','cunning')
                            )
                            AND NOT EXISTS (
                                SELECT 1 FROM card_concept_aspect cca_opp
                                JOIN aspect a_opp ON a_opp.id = cca_opp.aspect_id
                                WHERE cca_opp.card_concept_id = cc.id
                                  AND LOWER(a_opp.code) = ?
                            )
                        )
                    """)
                    affinity_params.extend([selected_alignment, opposite_alignment])
                elif selected_alignment == "__exclude__":
                    affinity_parts.append(f"(({base_condition}) AND NOT EXISTS (SELECT 1 FROM card_concept_aspect cca_al JOIN aspect a_al ON a_al.id = cca_al.aspect_id WHERE cca_al.card_concept_id = cc.id AND LOWER(a_al.code) IN ('heroism','villainy')))" )
                else:
                    affinity_parts.append(f"(({base_condition}) AND NOT EXISTS (SELECT 1 FROM card_concept_aspect cca_al JOIN aspect a_al ON a_al.id = cca_al.aspect_id WHERE cca_al.card_concept_id = cc.id AND LOWER(a_al.code) IN ('heroism','villainy')))" )
            else:
                # Aucune couleur principale : le second groupe peut être
                # utilisé seul. Sans aucun filtre d'affinité, on ne restreint
                # pas la recherche.
                if selected_alignment in ("heroism", "villainy"):
                    affinity_parts.append("""
                        EXISTS (
                            SELECT 1 FROM card_concept_aspect cca_al
                            JOIN aspect a_al ON a_al.id = cca_al.aspect_id
                            WHERE cca_al.card_concept_id = cc.id
                              AND LOWER(a_al.code) = ?
                        )
                    """)
                    affinity_params.append(selected_alignment)
                elif selected_alignment == "__exclude__":
                    affinity_parts.append("""
                        NOT EXISTS (
                            SELECT 1 FROM card_concept_aspect cca_al
                            JOIN aspect a_al ON a_al.id = cca_al.aspect_id
                            WHERE cca_al.card_concept_id = cc.id
                              AND LOWER(a_al.code) IN ('heroism','villainy')
                        )
                    """)

            if include_neutral:
                # Dans la base SWU, une carte neutre n'est pas enregistrée
                # avec une ligne d'affinité "neutral" : elle ne possède
                # simplement aucune affinité dans card_concept_aspect.
                # Le bouton Neutre doit donc ajouter toutes les cartes sans
                # affinité, quelle que soit la combinaison choisie dans les
                # deux autres groupes.
                affinity_parts.append("""
                    NOT EXISTS (
                        SELECT 1 FROM card_concept_aspect cca_n
                        WHERE cca_n.card_concept_id = cc.id
                    )
                """)

            if affinity_parts:
                sql += " AND (" + " OR ".join(f"({part})" for part in affinity_parts) + ")"
                params.extend(affinity_params)

        # La galerie conserve la vue Standard par défaut.
        # En mode recherche par nom, ce même principe s'applique : on affiche
        # uniquement l'image de la variante Standard (01), tous sets confondus.
        # Ne pas assimiler une variante sans type à Standard : certaines
        # données promotionnelles de SEC, notamment les Serialized Prestige,
        # peuvent sinon être ramenées à Standard par COALESCE.
        conditions = ["vt.variant_id = '01'"]

        if search_mode:
            # En recherche par nom, l'extension éventuellement sélectionnée
            # est déjà appliquée ci-dessus. On force ici uniquement la variante
            # Standard pour éviter Prestige, Hyperspace, Foil, etc.
            sql += " AND vt.variant_id = '01'"
        else:
            # Weekly Play : les extensions dédiées utilisent des codes distincts.
            #
            # Règle spéciale, limitée aux trois premiers sets :
            #   SOR  + variant 60  -> Weekly Play
            #   SORP + variant 02  -> Weekly Play
            #   SHD  + variant 60  -> Weekly Play
            #   SHDP + variant 02  -> Weekly Play
            #   TWI  + variant 60  -> Weekly Play
            #   TWIP + variant 02  -> Weekly Play
            #
            # Pour les sets suivants, on conserve strictement la logique actuelle
            # : extension dédiée + variant 60.
            weekly_map = {
                "SOR": "SORP",
                "SHD": "SHDP",
                "TWI": "TWIP",
                "JTL": "JTLP",
                "LOF": "LOFP",
                "SEC": "SECP",
                "LAW": "LAWP",
                "ASH": "ASHP",
            }
            # Weekly Play = uniquement l'impression standard. Les sous-cases
            # Standard/Foil ont été supprimées de l'interface.
            # Le Weekly Play n'est plus un filtre de galerie : ses variantes
            # sont accessibles depuis la boîte de dialogue de stock.
            weekly_condition = None

            # Construire la contrainte d'extension après avoir déterminé les
            # versions. Les versions classiques restent sur l'extension choisie,
            # tandis que Weekly Play utilise son extension associée.
            if selected_expansion_codes:
                expansion_clauses = []
                selected_expansion_set = set(selected_expansion_codes)

                # Certaines extensions promotionnelles/spéciales utilisent des
                # variant_id qui ne font pas partie des versions classiques
                # affichées ci-dessus. Elles doivent néanmoins être visibles
                # dès que l'utilisateur sélectionne directement l'extension.
                #
                # Représentation constatée dans la base :
                #   C24/C25/C26 -> variant 08 (Convention Exclusive)
                #   J24/J25     -> variant 07 (Judge Program)
                #   MV26        -> variant 10 (Movie Promo)
                #   CST/Costco  -> variant 11 (Costco Exclusive)
                #
                # Le filtre de version classique ne doit donc pas éliminer ces
                # cartes lorsque l'extension spéciale est explicitement choisie.
                special_extension_variants = {
                    "C24": "08",
                    "J24": "07",
                    "C25": "08",
                    "J25": "07",
                    "C26": "08",
                    "MV26": "10",
                    "CST": "11",
                }

                for selected_expansion_code in selected_expansion_codes:
                    special_variant = special_extension_variants.get(
                        selected_expansion_code.upper()
                    )
                    if special_variant:
                        expansion_clauses.append(
                            "(e.code = ? AND vt.variant_id = ?)"
                        )
                        params.extend([selected_expansion_code, special_variant])

                    if conditions:
                        expansion_clauses.append(
                            "(e.code = ? AND (" + " OR ".join(conditions) + "))"
                        )
                        params.append(selected_expansion_code)

                    if weekly_condition:
                        weekly_code = weekly_map.get(selected_expansion_code)

                        # SOR/SHD/TWI : deux représentations sont acceptées, mais
                        # uniquement pour ces trois sets. Les extensions SORP/SHDP/TWIP
                        # sont exclusivement Weekly Play et sont enregistrées en
                        # variant 02 (Hyperspace) dans les données API.
                        if selected_expansion_code in {"SOR", "SHD", "TWI"}:
                            # Dans la base actuelle, les impressions Weekly Play de ces
                            # trois sets ne sont PAS stockées dans une extension SORP/SHDP/TWIP.
                            # Elles sont rattachées à SOR/SHD/TWI et utilisent variant 02.
                            # Elles correspondent précisément aux plages suivantes :
                            # SOR : 04-11 | SHD : 05-12 | TWI : 03-10.
                            # Le variant 60 couvre déjà les autres Weekly Play.
                            expansion_clauses.append(
                                "(e.code = ? AND vt.variant_id = '60')"
                            )
                            params.append(selected_expansion_code)

                            weekly_ranges = {
                                "SOR": (4, 11),
                                "SHD": (5, 12),
                                "TWI": (3, 10),
                            }
                            first_num, last_num = weekly_ranges[selected_expansion_code]
                            expansion_clauses.append(
                                "(e.code = ? AND vt.variant_id = '02' AND cp.card_number BETWEEN ? AND ?)"
                            )
                            params.extend([selected_expansion_code, first_num, last_num])
                        elif weekly_code:
                            # Pour JTL/LOF/SEC/LAW/ASH, aucune modification :
                            # extension Weekly Play dédiée + variant 60.
                            weekly_exists = False
                            try:
                                weekly_exists = self.db.execute(
                                    "SELECT 1 FROM expansion WHERE code = ? LIMIT 1",
                                    (weekly_code,)
                                ).fetchone() is not None
                            except Exception:
                                weekly_exists = False

                            if weekly_exists:
                                expansion_clauses.append(
                                    "(e.code = ? AND (" + weekly_condition + "))"
                                )
                                params.append(weekly_code)
                            else:
                                # Compatibilité avec les anciennes bases où le
                                # Weekly Play pouvait rester rattaché au set principal.
                                expansion_clauses.append(
                                    "(e.code = ? AND (" + weekly_condition + "))"
                                )
                                params.append(selected_expansion_code)
                if expansion_clauses:
                    sql += " AND (" + " OR ".join(expansion_clauses) + ")"
                else:
                    sql += " AND 1 = 0"
            else:
                if weekly_condition:
                    # Vue "Toutes les extensions" : variant 60 reste la règle
                    # générale, avec l'exception explicite SORP/SHDP/TWIP en 02.
                    conditions.append(weekly_condition)
                    conditions.append(
                        "(e.code IN ('SORP', 'SHDP', 'TWIP') AND vt.variant_id = '02')"
                    )
                if conditions:
                    sql += " AND (" + " OR ".join(conditions) + ")"
                else:
                    sql += " AND 1 = 0"

        # Les variantes autres que Standard sont gérées dans la boîte de
        # dialogue de stock ; la galerie reste volontairement centrée sur
        # l'impression Standard de la carte.

        # Ordre fixe de la galerie : extension puis numéro de carte.
        # Le sélecteur de tri a été retiré afin que la vue COLLECTION et la
        # galerie utilisent toujours le même ordre déterministe.
        sql += """
            ORDER BY
                COALESCE(e.sort_value, 9999),
                CASE WHEN ct.code = 'Token' THEN 1 ELSE 0 END,
                CASE
                    WHEN cp.card_number IS NULL OR TRIM(CAST(cp.card_number AS TEXT)) = '' THEN 999999
                    WHEN TRIM(CAST(cp.card_number AS TEXT)) GLOB '[0-9]*'
                        THEN CAST(cp.card_number AS INTEGER)
                    ELSE 999999
                END,
                cp.card_number IS NULL,
                cp.serial_code,
                cp.id
        """

        return sql, params

