    def _show_bug_report_tooltip(self, event=None):
        """Affiche l'infobulle du bouton de signalement."""
        self._hide_bug_report_tooltip()
        try:
            popup = tk.Toplevel(self.root)
            popup.overrideredirect(True)
            popup.configure(bg="#e2b84b")
            label = tk.Label(
                popup,
                text="rapport de bug",
                bg="#0b2635",
                fg="#e2b84b",
                font=("Arial", 9, "bold"),
                padx=8,
                pady=4,
            )
            label.pack(padx=1, pady=1)
            x = self.bug_report_btn.winfo_rootx()
            y = self.bug_report_btn.winfo_rooty() + self.bug_report_btn.winfo_height() + 5
            popup.geometry(f"+{x}+{y}")
            popup.lift()
            self._bug_report_tooltip = popup
        except Exception:
            self._bug_report_tooltip = None

    def _hide_bug_report_tooltip(self, event=None):
        popup = getattr(self, "_bug_report_tooltip", None)
        self._bug_report_tooltip = None
        if popup is not None:
            try:
                popup.destroy()
            except Exception:
                pass

