    def _collect_bug_report(self, problem_type, description):
        """Crée un rapport texte autonome, sur le même principe que le Proxy PDF Generator."""
        now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        expansion = " ; ".join(sorted(getattr(self, "_selected_expansion_codes", set())))
        status = self.status.get().strip() if hasattr(self, "status") else ""
        lang = self.language.get() if hasattr(self, "language") else "fr"
        lines = [
            "SWU COLLECTION MANAGER // BUG REPORT",
            "=" * 52,
            f"Date : {now}",
            "Version : v269",
            f"Système : {platform.system()} {platform.release()}",
            f"Architecture : {platform.machine()}",
            f"Langue : {lang}",
            f"Type : {problem_type}",
            "",
            "DESCRIPTION",
            "-" * 52,
            description.strip() or "(aucune description)",
            "",
            "CONTEXTE DE L'APPLICATION",
            "-" * 52,
            f"Extension sélectionnée : {expansion}",
            f"Statut : {status}",
            f"Répertoire du programme : {Path(__file__).resolve().parent}",
            "",
            "FIN DU RAPPORT",
        ]
        text = "\n".join(lines)
        report_dir = Path(os.environ.get("TEMP", str(Path.home()))) / "SWU_Collection_Manager_Reports"
        report_dir.mkdir(parents=True, exist_ok=True)
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        path = report_dir / f"SWU_Collection_Manager_Bug_v269_{stamp}.txt"
        path.write_text(text, encoding="utf-8")
        try:
            self.root.clipboard_clear()
            self.root.clipboard_append(text)
            self.root.update()
        except Exception:
            pass
        return path, text

    def open_bug_report_dialog(self):
        """Ouvre le formulaire de bug puis propose l'ouverture de la messagerie."""
        dialog, body = self._create_hud_toplevel(self.root, self._bug_report_text("title"))
        colors = getattr(self, "_ui_colors", {
            "bg": "#07131d", "field": "#0b2230", "text": "#e7f1f7", "blue_dark": "#164b68", "gold": "#e2b84b"
        })

        tk.Label(body, text=self._bug_report_text("type"), bg=colors["bg"], fg=colors["gold"],
                 font=("Arial", 10, "bold")).pack(anchor="w", padx=24, pady=(22, 6))
        type_var = tk.StringVar(value=self._bug_report_text("types")[-1])
        combo = ttk.Combobox(body, textvariable=type_var, state="readonly",
                             values=self._bug_report_text("types"), width=42)
        combo.pack(anchor="w", fill="x", padx=24, pady=(0, 14))

        tk.Label(body, text=self._bug_report_text("desc"), bg=colors["bg"], fg=colors["gold"],
                 font=("Arial", 10, "bold")).pack(anchor="w", padx=24, pady=(0, 6))
        text_frame = tk.Frame(body, bg=colors["bg"], highlightbackground="#164b68", highlightthickness=1)
        text_frame.pack(fill="both", expand=True, padx=24)
        text_widget = tk.Text(text_frame, bg="#080D12", fg=colors["text"], insertbackground=colors["text"],
                              relief="flat", bd=0, wrap="word", font=("Arial", 10), padx=10, pady=8)
        text_widget.pack(fill="both", expand=True)

        footer = tk.Frame(body, bg=colors["bg"])
        footer.pack(fill="x", padx=24, pady=(14, 20))
        tk.Label(footer, text=self._bug_report_text("hint"), bg=colors["bg"], fg="#91a8b5",
                 font=("Arial", 8), wraplength=380, justify="left").pack(side="left", anchor="w")

        def close_dialog():
            try: dialog.grab_release()
            except Exception: pass
            dialog.destroy()

        def send_report():
            try:
                path, _report_text = self._collect_bug_report(type_var.get(), text_widget.get("1.0", "end-1c"))
                close_dialog()
                self._ask_open_bug_mail(path)
            except Exception as exc:
                close_dialog()
                self._hud_messagebox("error", "Erreur", str(exc))

        tk.Button(footer, text=self._bug_report_text("send"), command=send_report,
                  bg=colors["gold"], fg="#111111", activebackground="#F0C45A", activeforeground="#111111",
                  relief="flat", bd=0, cursor="hand2", font=("Arial", 10, "bold"), padx=18, pady=8).pack(side="right", padx=(10, 0))
        tk.Button(footer, text=self._bug_report_text("cancel"), command=close_dialog,
                  bg="#102b3b", fg=colors["text"], activebackground=colors["blue_dark"],
                  relief="flat", bd=0, cursor="hand2", font=("Arial", 9, "bold"), padx=16, pady=8).pack(side="right")
        dialog._hud_close_button.configure(command=close_dialog)
        dialog.bind("<Escape>", lambda _e: close_dialog())

        # Le formulaire doit toujours laisser apparaître le pied de page et ses boutons.
        # On réserve une zone de saisie raisonnable et on adapte la hauteur à l'écran.
        text_frame.configure(height=270)
        text_frame.pack_propagate(False)
        dialog.update_idletasks()
        width = 720
        max_height = max(560, self.root.winfo_screenheight() - 80)
        height = min(540, max_height)
        self.root.update_idletasks()
        x = self.root.winfo_rootx() + max(0, (self.root.winfo_width() - width) // 2)
        y = self.root.winfo_rooty() + max(0, (self.root.winfo_height() - height) // 2)
        dialog.geometry(f"{width}x{height}+{x}+{y}")
        dialog.deiconify()
        dialog.lift()
        dialog.grab_set()
        dialog.wait_visibility()
        text_widget.focus_set()
        self.root.wait_window(dialog)

    def _ask_open_bug_mail(self, path):
        """Propose l'ouverture d'un webmail et l'ouverture du dossier du rapport."""
        dialog, body = self._create_hud_toplevel(self.root, self._bug_report_text("created"))
        colors = getattr(self, "_ui_colors", {
            "bg": "#07131d", "field": "#0b2230", "text": "#e7f1f7", "blue_dark": "#164b68", "gold": "#e2b84b"
        })
        report_path = Path(path)
        report_name = report_path.name
        report_folder = report_path.parent

        tk.Label(body, text=self._bug_report_text("question"), bg=colors["bg"], fg=colors["text"],
                 font=("Arial", 10, "bold"), wraplength=650, justify="left").pack(anchor="w", padx=24, pady=(20, 10))

        tk.Label(body, text=self._bug_report_text("attach_instruction"), bg=colors["bg"], fg="#91a8b5",
                 font=("Arial", 9), wraplength=650, justify="left").pack(anchor="w", padx=24, pady=(0, 8))
        tk.Label(body, text=report_name, bg="#0b2230", fg=colors["gold"],
                 font=("Arial", 9, "bold"), anchor="w", padx=10, pady=7).pack(fill="x", padx=24, pady=(0, 10))
        tk.Label(body, text=self._bug_report_text("folder_info") + "\n" + str(report_folder),
                 bg=colors["bg"], fg="#91a8b5", font=("Arial", 8), wraplength=650,
                 justify="left").pack(anchor="w", padx=24, pady=(0, 8))
        tk.Label(body, text=self._bug_report_text("clipboard_info"), bg=colors["bg"], fg="#91a8b5",
                 font=("Arial", 8), wraplength=650, justify="left").pack(anchor="w", padx=24)

        def close_dialog():
            try:
                dialog.grab_release()
            except Exception:
                pass
            dialog.destroy()

        def open_report_folder():
            """Ouvre automatiquement le dossier contenant le rapport."""
            try:
                if os.name == "nt":
                    os.startfile(str(report_folder))
                elif sys.platform == "darwin":
                    subprocess.Popen(["open", str(report_folder)])
                else:
                    subprocess.Popen(["xdg-open", str(report_folder)])
            except Exception as exc:
                self._hud_messagebox("error", "Erreur", self._bug_report_text("folder_error") + "\n\n" + str(exc))

        # Coordonnées et message type préremplis pour les trois modes de messagerie.
        bug_recipient = "fabien.chamaret@gmail.com"
        bug_subject = "[SWU Collection Manager] Rapport de bug"
        bug_body = (
            "Bonjour,\n\n"
            "Je souhaite signaler un problème rencontré avec le SWU Collection Manager.\n\n"
            f"Fichier de rapport à joindre : {report_name}\n\n"
            "Description complémentaire :\n"
            "\n"
            "Merci.\n"
        )

        def open_url(webmail):
            try:
                # Le dossier du rapport est ouvert automatiquement avant le webmail.
                open_report_folder()
                params = (
                    f"to={quote(bug_recipient)}&"
                    f"su={quote(bug_subject)}&"
                    f"body={quote(bug_body)}"
                )
                if webmail == "gmail":
                    url = "https://mail.google.com/mail/?view=cm&fs=1&" + params
                else:
                    url = "https://outlook.live.com/mail/0/deeplink/compose?" + params
                webbrowser.open_new_tab(url)
            except Exception as exc:
                self._hud_messagebox("error", "Erreur", self._bug_report_text("mail_error") + "\n\n" + str(exc))
            finally:
                close_dialog()

        def open_other_mail():
            try:
                # Même message prérempli pour la messagerie par défaut.
                open_report_folder()
                mailto = (
                    "mailto:" + quote(bug_recipient, safe="@") +
                    "?subject=" + quote(bug_subject) +
                    "&body=" + quote(bug_body)
                )
                webbrowser.open(mailto)
            except Exception as exc:
                self._hud_messagebox("error", "Erreur", self._bug_report_text("mail_error") + "\n\n" + str(exc))
            finally:
                close_dialog()

        # Tous les choix sont regroupés sur une seule ligne.
        # « PLUS TARD » reste volontairement à droite.
        row_web = tk.Frame(body, bg=colors["bg"])
        row_web.pack(fill="x", padx=24, pady=(16, 18))

        tk.Button(row_web, text=self._bug_report_text("later"), command=close_dialog,
                  bg="#102b3b", fg=colors["text"], activebackground=colors["blue_dark"], relief="flat", bd=0,
                  cursor="hand2", font=("Arial", 9, "bold"), padx=16, pady=7).pack(side="right")

        tk.Button(row_web, text=self._bug_report_text("gmail"), command=lambda: open_url("gmail"),
                  bg=colors["gold"], fg="#111111", activebackground="#F0C45A", relief="flat", bd=0,
                  cursor="hand2", font=("Arial", 9, "bold"), padx=12, pady=7).pack(side="left", padx=(0, 8))
        tk.Button(row_web, text=self._bug_report_text("outlook"), command=lambda: open_url("outlook"),
                  bg=colors["gold"], fg="#111111", activebackground="#F0C45A", relief="flat", bd=0,
                  cursor="hand2", font=("Arial", 9, "bold"), padx=12, pady=7).pack(side="left", padx=(0, 8))
        tk.Button(row_web, text=self._bug_report_text("other_mail"), command=open_other_mail,
                  bg="#102b3b", fg=colors["text"], activebackground=colors["blue_dark"], relief="flat", bd=0,
                  cursor="hand2", font=("Arial", 9, "bold"), padx=12, pady=7).pack(side="left")

        dialog._hud_close_button.configure(command=close_dialog)
        dialog.bind("<Escape>", lambda _e: close_dialog())
        dialog.update_idletasks()
        width, height = 760, 390
        self.root.update_idletasks()
        x = self.root.winfo_rootx() + max(0, (self.root.winfo_width() - width) // 2)
        y = self.root.winfo_rooty() + max(0, (self.root.winfo_height() - height) // 2)
        dialog.geometry(f"{width}x{height}+{x}+{y}")
        dialog.deiconify(); dialog.lift(); dialog.grab_set(); dialog.wait_visibility()
        self.root.wait_window(dialog)

    def _close_hud_dialog(self, dialog):
        try:
            dialog.grab_release()
        except Exception:
            pass
        try:
            dialog.destroy()
        except Exception:
            pass

    def _create_hud_toplevel(self, parent, title):
        """Crée un Toplevel entièrement contrôlé par le HUD, sans barre Windows."""
        colors = getattr(self, "_ui_colors", {
            "bg": "#07131d",
            "field": "#0b2230",
            "text": "#e7f1f7",
            "blue_dark": "#164b68",
            "gold": "#e2b84b",
        })

        dialog = tk.Toplevel(parent)
        dialog.withdraw()
        dialog.overrideredirect(True)
        dialog.configure(bg=colors["bg"])
        dialog.resizable(False, False)

        outer = tk.Frame(dialog, bg=colors["gold"], bd=0, highlightthickness=0)
        outer.pack(fill="both", expand=True)

        inner = tk.Frame(outer, bg=colors["bg"], bd=0, highlightthickness=0)
        inner.pack(fill="both", expand=True, padx=2, pady=2)

        titlebar = tk.Frame(
            inner, bg="#0b2635", height=38, bd=0, highlightthickness=0
        )
        titlebar.pack(fill="x")
        titlebar.pack_propagate(False)

        title_label = tk.Label(
            titlebar,
            text=f"◈  {title}",
            bg="#0b2635",
            fg=colors["gold"],
            font=("Arial", 10, "bold"),
            anchor="w",
            padx=12,
        )
        title_label.pack(side="left", fill="both", expand=True)

        def default_close():
            try:
                dialog.grab_release()
            except Exception:
                pass
            dialog.destroy()

        close_button = tk.Button(
            titlebar,
            text="×",
            command=default_close,
            bg="#0b2635",
            fg=colors["text"],
            activebackground=colors["blue_dark"],
            activeforeground="#ffffff",
            font=("Arial", 17, "bold"),
            relief="flat",
            bd=0,
            highlightthickness=0,
            width=3,
            cursor="hand2",
        )
        close_button.pack(side="right", fill="y", padx=(0, 2))

        drag = {"x": 0, "y": 0}

        def start_move(event):
            drag["x"] = event.x_root - dialog.winfo_x()
            drag["y"] = event.y_root - dialog.winfo_y()

        def move(event):
            dialog.geometry(
                f"+{event.x_root - drag['x']}+{event.y_root - drag['y']}"
            )

        for widget in (titlebar, title_label):
            widget.bind("<ButtonPress-1>", start_move)
            widget.bind("<B1-Motion>", move)

        body = tk.Frame(inner, bg=colors["bg"], bd=0, highlightthickness=0)
        body.pack(fill="both", expand=False)

        dialog._hud_content = body
        dialog._hud_titlebar = titlebar
        dialog._hud_close_button = close_button

        # La fenêtre reste cachée jusqu'à ce que son contenu et sa géométrie
        # soient complètement construits.
        #
        # IMPORTANT : ne pas rendre le HUD « transient » par rapport à la
        # fenêtre principale. Sous Windows, un Toplevel overrideredirect +
        # transient peut être masqué lorsque l'application perd le focus
        # (capture d'écran, navigateur, etc.). Le dialogue reste alors vivant
        # mais visuellement disparu. Le HUD est donc volontairement autonome.

        # Registre des dialogues HUD encore ouverts : il permet notamment à
        # close() de les détruire proprement avant la fermeture de Tk.
        if not hasattr(self, "_hud_dialogs"):
            self._hud_dialogs = set()
        self._hud_dialogs.add(dialog)

        def _remove_hud_dialog():
            try:
                self._hud_dialogs.discard(dialog)
            except Exception:
                pass

        dialog.bind("<Destroy>", lambda _e: _remove_hud_dialog(), add="+")

        # Gestion de la perte de focus :
        # le dialogue NE DOIT PAS être détruit lorsqu'une autre application
        # (capture d'écran, navigateur, explorateur...) prend le focus.
        # On libère simplement le grab afin que Windows puisse donner le focus
        # à l'autre application. Le dialogue reste vivant et sera remis au
        # premier plan lorsque le Collection Manager reprend le focus.
        def _release_grab_on_focus_loss(_event=None):
            try:
                if dialog.winfo_exists():
                    dialog.grab_release()
            except Exception:
                pass

        def _restore_hud_on_parent_focus(_event=None):
            def _restore():
                try:
                    if not dialog.winfo_exists():
                        return
                    # Une fois la galerie prête, le HUD de progression doit rester
                    # visible sans reprendre le grab : les cartes sont alors
                    # réellement cliquables avant la disparition de la barre.
                    if getattr(dialog, "_gallery_ready_for_click", False):
                        dialog.deiconify()
                        dialog.lift()
                        return
                    # Si le dialogue existe toujours, il redevient le dialogue
                    # actif dès que le Collection Manager reprend le focus.
                    dialog.deiconify()
                    dialog.lift()
                    dialog.grab_set()
                except Exception:
                    pass
            try:
                dialog.after_idle(_restore)
            except Exception:
                pass

        # Perte de focus du dialogue : libération temporaire du grab seulement.
        dialog.bind("<FocusOut>", _release_grab_on_focus_loss, add="+")

        # Retour du focus dans l'application : remettre le HUD au premier plan.
        # On écoute à la fois la fenêtre principale ET le dialogue lui-même,
        # car Windows peut rendre le focus directement au Toplevel.
        parent.bind("<FocusIn>", _restore_hud_on_parent_focus, add="+")
        dialog.bind("<FocusIn>", _restore_hud_on_parent_focus, add="+")

        return dialog, body

    def _show_hud_info(self, title, message):
        """Boîte d'information HUD sans décoration Windows."""
        dialog, body = self._create_hud_toplevel(self.root, title)
        colors = getattr(self, "_ui_colors", {
            "bg": "#07131d", "field": "#0b2230",
            "text": "#e7f1f7", "blue_dark": "#164b68", "gold": "#e2b84b",
        })

        def close_dialog():
            try:
                dialog.grab_release()
            except Exception:
                pass
            dialog.destroy()

        tk.Label(
            body, text=message, bg=colors["bg"], fg=colors["text"],
            font=("Arial", 10), justify="left", wraplength=430
        ).pack(fill="x", padx=24, pady=(24, 18))

        button_border = tk.Frame(body, bg=colors["blue_dark"], bd=0, highlightthickness=0)
        button_border.pack(anchor="e", padx=24, pady=(0, 20))
        tk.Button(
            button_border, text="OK", command=close_dialog,
            bg=colors["field"], fg=colors["text"],
            activebackground=colors["blue_dark"], activeforeground=colors["text"],
            font=("Arial", 10, "bold"), relief="flat", bd=0,
            highlightthickness=1, highlightbackground=colors["blue_dark"],
            highlightcolor=colors["gold"], padx=20, pady=7, cursor="hand2"
        ).pack(padx=2, pady=2)

        dialog._hud_close_button.configure(command=close_dialog)
        dialog.update_idletasks()
        width = max(500, body.winfo_reqwidth() + 48)
        height = max(190, body.winfo_reqheight() + 38)
        self.root.update_idletasks()
        x = self.root.winfo_rootx() + max(0, (self.root.winfo_width() - width) // 2)
        y = self.root.winfo_rooty() + max(0, (self.root.winfo_height() - height) // 2)
        dialog.geometry(f"{width}x{height}+{x}+{y}")
        dialog.deiconify()
        dialog.lift()
        dialog.grab_set()
        dialog.bind("<Return>", lambda _e: close_dialog())
        dialog.bind("<Escape>", lambda _e: close_dialog())
        dialog.wait_visibility()
        self.root.wait_window(dialog)

    def _hud_messagebox(self, kind, title, message, parent=None):
        """Remplace les messagebox Windows par des boîtes HUD."""
        if kind == "askyesno":
            dialog, body = self._create_hud_toplevel(parent or self.root, title)
            colors = getattr(self, "_ui_colors", {
                "bg": "#07131d", "field": "#0b2230", "text": "#e7f1f7",
                "blue_dark": "#164b68", "gold": "#e2b84b",
            })
            result = {"value": False}

            def finish(value):
                result["value"] = value
                try:
                    dialog.grab_release()
                except Exception:
                    pass
                dialog.destroy()

            tk.Label(body, text=message, bg=colors["bg"], fg=colors["text"],
                     font=("Arial", 10), justify="left", wraplength=520).pack(
                         fill="x", padx=24, pady=(24, 20)
                     )
            buttons = tk.Frame(body, bg=colors["bg"])
            buttons.pack(anchor="e", padx=24, pady=(0, 20))
            tk.Button(buttons, text="Non", command=lambda: finish(False),
                      bg="#102b3b", fg=colors["text"], activebackground=colors["blue_dark"],
                      relief="flat", padx=18, pady=7, cursor="hand2").pack(side="right", padx=(8,0))
            tk.Button(buttons, text="Oui", command=lambda: finish(True),
                      bg=colors["blue_dark"], fg="#ffffff", activebackground="#2f9bd1",
                      relief="flat", padx=18, pady=7, cursor="hand2").pack(side="right")
            dialog._hud_close_button.configure(command=lambda: finish(False))
            dialog.bind("<Escape>", lambda _e: finish(False))
            dialog.update_idletasks()
            width = max(520, body.winfo_reqwidth() + 48)
            height = body.winfo_reqheight() + 38
            parent_win = parent or self.root
            parent_win.update_idletasks()
            x = parent_win.winfo_rootx() + max(0, (parent_win.winfo_width() - width)//2)
            y = parent_win.winfo_rooty() + max(0, (parent_win.winfo_height() - height)//2)
            dialog.geometry(f"{width}x{height}+{x}+{y}")
            dialog.deiconify()
            dialog.lift()
            dialog.grab_set()
            dialog.wait_visibility()
            parent_win.wait_window(dialog)
            return result["value"]

        self._show_hud_info(title, message)


    def _refresh_gallery_sort_buttons(self):
        """Actualise l'état visuel des boutons de tri."""
        buttons = getattr(self, "_gallery_sort_buttons", {})
        selected = (
            getattr(self, "_gallery_sort_field", None),
            getattr(self, "_gallery_sort_order", None),
        )
        for key, btn in buttons.items():
            if btn is None or not btn.winfo_exists():
                continue
            active = key == selected
            btn.configure(
                bg="#2b765c" if active else "#12394d",
                activebackground="#3d9878" if active else "#205f7f"
            )

    def _set_gallery_sort(self, field, order=None):
        """Trie immédiatement les résultats de la Recherche par coût, puissance ou HP."""
        # Compatibilité avec l'ancien appel _set_gallery_sort("asc" / "desc").
        if order is None and field in ("asc", "desc"):
            order = field
            field = "cost"
        if field not in ("cost", "power", "hp") or order not in ("asc", "desc"):
            return

        self._gallery_sort_field = field
        self._gallery_sort_order = order
        self._refresh_gallery_sort_buttons()
        if not getattr(self, "current_cards", None):
            return

        def numeric_value(card):
            try:
                value = card.get(field)
                if value is None or str(value).strip() == "":
                    return None
                return float(value)
            except (TypeError, ValueError):
                return None

        # Les cartes sans valeur pour le critère restent toujours à la fin,
        # aussi bien en croissant qu'en décroissant.
        reverse = order == "desc"
        cards = sorted(
            list(self.current_cards),
            key=lambda card: (
                numeric_value(card) is None,
                -(numeric_value(card) or 0.0) if reverse else (numeric_value(card) or 0.0),
            )
        )
        self.current_cards = cards
        self.display_cards(cards, 0)

    def apply_filters(self):
        """Valide les filtres Type/Rareté/Affinités/Extension.

        Pour éviter de créer une galerie gigantesque, une extension doit
        obligatoirement être sélectionnée. La vue « Toutes » ne lance donc
        plus de recherche de cartes.
        """
        if self.loading or self.db is None:
            return

        selected_codes = sorted(getattr(self, "_selected_expansion_codes", set()))

        if not selected_codes:
            self._show_hud_info(
                "Sélection d'une extension",
                "Veuillez sélectionner une extension avant de lancer la recherche.",
            )
            try:
                # Les boutons d'extensions restent immédiatement accessibles.
                try:
                    self.filter_extension_canvas.focus_set()
                except Exception:
                    pass
            except Exception:
                pass
            return

        self.clear_gallery()
        self._gallery_sort_field = None
        self._gallery_sort_order = None
        self._refresh_gallery_sort_buttons()
        try:
            self._gallery_sort_hud.pack(side="right", padx=(10, 0))
        except Exception:
            pass
        self.load_all_cards(name_only=False)

    def apply_name_search(self):
        """Lance une recherche globale sur le nom des cartes uniquement."""
        if self.loading or self.db is None:
            return

        term = self.search.get().strip()
        if not term:
            self.status.set("Saisis un nom ou une partie du nom de carte.")
            try:
                self.search_entry.focus_set()
            except Exception:
                pass
            return

        self.clear_gallery()
        self._gallery_sort_field = None
        self._gallery_sort_order = None
        self._refresh_gallery_sort_buttons()
        try:
            self._gallery_sort_hud.pack(side="right", padx=(10, 0))
        except Exception:
            pass
        self.load_all_cards(name_only=True)

    def load_all_cards(self, name_only=False):
        if self.loading or self.db is None:
            return

        self.loading = True
        if name_only:
            self.status.set("Recherche de toutes les cartes correspondant au nom…")
        else:
            self.status.set("Chargement des cartes correspondant aux filtres…")

        threading.Thread(
            target=self._load_all_cards_worker,
            args=(name_only,),
            daemon=True
        ).start()

    def _load_all_cards_worker(self, name_only=False):
        try:
            sql, params = self.build_query(name_only=name_only)

            cur = self.db.cursor()
            rows = cur.execute(sql, params).fetchall()
            cards = [dict(row) for row in rows]
            total = len(cards)

            self.root.after(
                0,
                lambda: self._finish_all_cards(cards, total)
            )

        except Exception as exc:
            self.root.after(
                0,
                lambda msg=str(exc): self._load_error(msg)
            )

    def _finish_all_cards(self, cards, total):
        self.loading = False

        self.total_rows = total
        self.current_cards = cards
        field = getattr(self, "_gallery_sort_field", None)
        order = getattr(self, "_gallery_sort_order", None)
        if field in ("cost", "power", "hp") and order in ("asc", "desc"):
            def _sort_value(card):
                try:
                    value = card.get(field)
                    if value is None or str(value).strip() == "":
                        return None
                    return float(value)
                except (TypeError, ValueError):
                    return None
            reverse = order == "desc"
            self.current_cards = sorted(
                self.current_cards,
                key=lambda card: (
                    _sort_value(card) is None,
                    -(_sort_value(card) or 0.0) if reverse else (_sort_value(card) or 0.0),
                )
            )
            cards = self.current_cards
        self.display_cards(cards, 0)

        self.result_count.set(
            f"{total:,} impression(s) correspondant aux filtres."
        )
        self.page_info.set(
            f"Affichées : {total:,} / {total:,}"
        )
        self.status.set(
            f"{total:,} carte(s) affichée(s)."
        )

    def _load_error(self, message):
        self.loading = False
        self.status.set("Erreur de chargement.")
        self._hud_messagebox("error", 
            "Erreur",
            "Impossible de lire la base SQLite.\n\n" + message
        )

    def _start_recap_value_calculation(self, expansion_code, stats):
        """Calcule les valeurs Cardmarket après l'affichage du récapitulatif."""
        self._recap_value_generation = getattr(self, "_recap_value_generation", 0) + 1
        generation = self._recap_value_generation
        target_codes = [clean_text(x.get("code")) for x in (stats or [])
                        if isinstance(x, dict) and clean_text(x.get("code"))]
        if expansion_code:
            target_codes = [clean_text(expansion_code)]

        def worker():
            computed = {}
            try:
                for code in target_codes:
                    if generation != getattr(self, "_recap_value_generation", generation):
                        return
                    info = self._estimate_collection_value(code)
                    computed[code] = {
                        "value": float(info.get("value", 0.0) or 0.0),
                        "unpriced_copies": int(info.get("unpriced_copies", 0) or 0),
                    }
            except Exception:
                return
            try:
                self.root.after(0, lambda: self._apply_recap_value_calculation(generation, computed))
            except Exception:
                pass

        threading.Thread(target=worker, daemon=True, name="SWU-RECAP-CARDMARKET").start()

    def _apply_recap_value_calculation(self, generation, computed):
        """Injecte les valeurs calculées sans reconstruire la galerie."""
        if generation != getattr(self, "_recap_value_generation", generation) or not computed:
            return

        for code, info in computed.items():
            label = getattr(self, "_collection_value_labels", {}).get(code)
            if label is not None and label.winfo_exists():
                label.configure(text=self._format_estimated_value(info["value"]))

        global_labels = getattr(self, "_global_recap_value_labels", {})
        global_total = 0.0
        global_unpriced = 0
        for code, info in computed.items():
            global_total += info["value"]
            global_unpriced += info["unpriced_copies"]
            cell = global_labels.get(code)
            if cell is not None and cell.winfo_exists():
                cell.configure(text=self._format_estimated_value(info["value"]))

        global_label = getattr(self, "_global_recap_value_label", None)
        if global_label is not None and global_label.winfo_exists():
            suffix = (f"  •  {global_unpriced} exemplaire(s) sans tarif disponible"
                      if global_unpriced else "")
            global_label.configure(
                text=f"Valeur estimée : {self._format_estimated_value(global_total)}{suffix}"
            )

    def _enter_collection_recap_layout(self, title, stats, rows, refresh_callback, expansion_code=None):
        """Passe la galerie en mode COLLECTION : en-tête fixe + galerie défilante."""
        self._exit_collection_recap_layout()
        try:
            self._gallery_sort_hud.pack_forget()
        except Exception:
            pass
        try:
            self._gallery_top.pack_forget()
            self._gallery_bottom.pack_forget()
            self._gallery_holder.pack_forget()
            if getattr(self, "_gallery_list_hud", None) is not None:
                self._gallery_list_hud.pack_forget()
        except Exception:
            pass

        # « Afficher liste » est placé sur sa propre ligne, en haut à gauche,
        # exactement comme dans le récapitulatif général de la collection.
        # Le titre « Récapitulatif — extension » vient sur la ligne suivante.
        list_row = tk.Frame(self._gallery_body, bg="#07131d", bd=0, highlightthickness=0)
        list_row.pack(fill="x", padx=12, pady=(0, 2))
        self._collection_list_row = list_row

        collection_list_hud = HUDFrame(list_row, bg="#07131d", width=150, height=46)
        collection_list_hud.pack_propagate(False)
        collection_list_hud.pack(side="left", padx=(0, 10), pady=0)
        collection_list_button = tk.Button(
            collection_list_hud,
            text="Afficher liste",
            command=self._show_user_list_selector,
            bg="#12394d", fg="#ffffff",
            activebackground="#205f7f", activeforeground="#ffffff",
            font=("Arial", 10, "bold"), relief="flat", bd=0,
            padx=14, pady=7, cursor="hand2"
        )
